window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s11-4","number":4,"surah":11,"verses":[2],"verseLabel":"هود: 2","question":"ما سرّ تقديم ﴿نذير﴾ على ﴿بشير﴾؟","answer":"لأن المخاطبين كانوا مقيمين على الشرك، فناسب البدء بما يوقظهم من الخطر، ثم فتح باب الأمل بالبشارة لمن رجع.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص385–391، هود: 2.","url":""}]},{"id":"s11-5","number":5,"surah":11,"verses":[3],"verseLabel":"هود: 3","question":"لماذا جمع بين الاستغفار والتوبة: ﴿استغفروا ربكم ثم توبوا إليه﴾؟","answer":"الاستغفار طلب ستر الذنب ومحو أثره، والتوبة رجوع عملي عن طريقه؛ فليس المطلوب كلمة اعتذار وحدها بل تحول في الاتجاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص392–408، هود: 3.","url":""}]},{"id":"s11-6","number":6,"surah":11,"verses":[3],"verseLabel":"هود: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يمتعكم متاعًا حسنًا إلى أجل مسمى﴾؟","answer":"قيد المتاع بالحسن لأنه ثمرة الإيمان والطاعة، وقيده بالأجل حتى لا يُفهم الوعد خلودًا في الدنيا؛ فهي نعمة موقوتة تتصل بعدها بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص392–408، هود: 3.","url":""}]},{"id":"s11-7","number":7,"surah":11,"verses":[3],"verseLabel":"هود: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿ويؤت كل ذي فضل فضله﴾؟","answer":"ليقرر أن زيادة العمل لا تضيع في عموم الوعد؛ فلكل صاحب فضل نصيبه الموافق لفضله، وفي العبارة حث على الاستكثار من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص392–408، هود: 3.","url":""}]},{"id":"s11-8","number":8,"surah":11,"verses":[4],"verseLabel":"هود: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى الله مرجعكم﴾ بتقديم الجار والمجرور؟","answer":"لقصر المرجع عليه وحده؛ فلا مهرب إلى قوة أخرى، ثم جاء ﴿وهو على كل شيء قدير﴾ لإثبات قدرته على البعث والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص409–414، هود: 4.","url":""}]},{"id":"s11-9","number":9,"surah":11,"verses":[5],"verseLabel":"هود: 5","question":"لماذا وصف إخفاء الكافرين بأنه ﴿يثنون صدورهم﴾؟","answer":"صوّر شدة إعراضهم ومحاولتهم كتمان ما فيها بمن يطوي صدره وينحنيه؛ وهي هيئة جسدية تكشف انغلاقًا نفسيًا لا يخفى على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص415–427، هود: 5.","url":""}]},{"id":"s11-10","number":10,"surah":11,"verses":[5],"verseLabel":"هود: 5","question":"لماذا ذكر استغشاء الثياب مع أن الله يعلم السر؟","answer":"لأنهم بالغوا في التستر حتى غطوا أجسادهم، فجاء ذكر الثياب تهكمًا بعجز محاولتهم؛ فالله يعلم ما يسرون وما يعلنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص415–427، هود: 5.","url":""}]},{"id":"s11-11","number":11,"surah":11,"verses":[5],"verseLabel":"هود: 5","question":"لماذا ختم بـ﴿إنه عليم بذات الصدور﴾ ولم يقل: «بما في الصدور»؟","answer":"﴿ذات الصدور﴾ تشمل الخواطر الملازمة والدوافع الخفية، فتدل على علم يتجاوز الظاهر إلى أخص ما يقوم بالنفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص415–427، هود: 5.","url":""}]},{"id":"s11-12","number":12,"surah":11,"verses":[6],"verseLabel":"هود: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وما من دابة في الأرض إلا على الله رزقها﴾ بصيغة الاستغراق؟","answer":"لتشمل كل حي مهما خفي أو ضعف، و﴿على الله﴾ تفيد تكفله فضلًا بالرزق؛ فتطمئن النفس إلى عموم علمه وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص428–438، هود: 6.","url":""}]},{"id":"s11-13","number":13,"surah":11,"verses":[6],"verseLabel":"هود: 6","question":"ما الفرق بين ﴿مستقرها﴾ و﴿مستودعها﴾؟","answer":"المستقر موضع قرارها وإقامتها، والمستودع ما تمر به مؤقتًا؛ فالكلمتان تستوعبان تحولاتها كلها من المنشأ إلى المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص428–438، هود: 6.","url":""}]},{"id":"s11-14","number":14,"surah":11,"verses":[7],"verseLabel":"هود: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿وكان عرشه على الماء﴾ في سياق خلق السماوات والأرض؟","answer":"ليكشف سبق ملكه وتدبيره قبل هذا العالم المشاهد، وأن الخلق وقع عن قدرة وحكمة لا عن حاجة إلى الموجودات.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص439–453، هود: 7.","url":""}]},{"id":"s11-15","number":15,"surah":11,"verses":[7],"verseLabel":"هود: 7","question":"لماذا عُلّل الخلق بقوله: ﴿ليبلوكم أيكم أحسن عملًا﴾ لا «أكثر عملًا»؟","answer":"لأن ميزان الابتلاء جودة العمل وإخلاصه وصوابه، لا مجرد كثرته؛ فكلمة ﴿أحسن﴾ تنقل النظر من العدد إلى القيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص439–453، هود: 7.","url":""}]},{"id":"s11-16","number":16,"surah":11,"verses":[7],"verseLabel":"هود: 7","question":"ما وجه قول الكافرين عن البعث: ﴿إن هذا إلا سحر مبين﴾؟","answer":"لما عجزوا عن دفع الحجة وصفوا الخبر الذي يقلب مألوفهم بالسحر؛ فالتسمية هروب من البرهان لا جواب عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص439–453، هود: 7.","url":""}]},{"id":"s11-17","number":17,"surah":11,"verses":[8],"verseLabel":"هود: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿ولئن أخرنا عنهم العذاب إلى أمة معدودة﴾؟","answer":"سمى المدة ﴿أمة﴾ لأنها جماعة متتابعة من الأزمنة، ووصفها بالمعدودة لتصوير قصرها وضبطها عند الله مهما استبعدها المستهزئون.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص454–465، هود: 8.","url":""}]},{"id":"s11-18","number":18,"surah":11,"verses":[8],"verseLabel":"هود: 8","question":"لماذا جاء الرد: ﴿ألا يوم يأتيهم ليس مصروفًا عنهم﴾؟","answer":"افتتح بـ﴿ألا﴾ للتنبيه، ونفى صرف العذاب لا مجرد تأخره؛ فما اتخذوه مادة للسخرية سيحيط بهم ولا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص454–465، هود: 8.","url":""}]},{"id":"s11-19","number":19,"surah":11,"verses":[9],"verseLabel":"هود: 9","question":"ما سرّ التعبير في قوله تعالى في الرحمة: ﴿أذقنا الإنسان منا رحمة﴾؟","answer":"الإذاقة تدل على أقل قدر من النعمة؛ فإذا كان الإنسان ييأس بزوال لمحة منها ظهر اضطرابه وقلة صبره. وإضافة الرحمة إلى الله تذكر بمصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص466–477، هود: 9.","url":""}]},{"id":"s11-20","number":20,"surah":11,"verses":[9],"verseLabel":"هود: 9","question":"لماذا جمع بين ﴿ليئوس كفور﴾؟","answer":"اليأس وصف نظره إلى المستقبل بعد سلب النعمة، والكفران وصف موقفه من ماضيها؛ فيقطع الرجاء وينسى العطاء معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص466–477، هود: 9.","url":""}]},{"id":"s11-21","number":21,"surah":11,"verses":[10],"verseLabel":"هود: 10","question":"ما سرّ التعبير عند عودة النعمة بقوله: ﴿ليقولن ذهب السيئات عني﴾؟","answer":"لا يرى النعمة فضلًا يستوجب الشكر، بل مجرد انتهاء لما كان يؤلمه؛ ثم يبني على زواله أمنًا مغرورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص478–491، هود: 10.","url":""}]},{"id":"s11-22","number":22,"surah":11,"verses":[10],"verseLabel":"هود: 10","question":"لماذا وصفه بـ﴿فرح فخور﴾؟","answer":"الفرح هنا بطر داخلي، والفخر إظهاره للناس؛ فجمعت الآية فساد إحساسه بالنعمة وفساد سلوكه بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص478–491، هود: 10.","url":""}]},{"id":"s11-23","number":23,"surah":11,"verses":[11],"verseLabel":"هود: 11","question":"لماذا استثنى ﴿الذين صبروا وعملوا الصالحات﴾ من تقلّب الإنسان؟","answer":"لأن الصبر يضبطه عند الضر، والعمل الصالح يضبطه عند النعمة؛ فبهما ينجو من اليأس والكفر والبطر والفخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص478–491، هود: 11.","url":""}]},{"id":"s11-24","number":24,"surah":11,"verses":[12],"verseLabel":"هود: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿فلعلك تارك بعض ما يوحى إليك وضائق به صدرك﴾؟","answer":"يصور شدة ضغط اقتراحاتهم على النبي، لا وقوع ترك الوحي منه؛ فجاء تسليةً وتحذيرًا من أن تصرفه مطالب المعاندين عن البلاغ الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص492–504، هود: 12.","url":""}]},{"id":"s11-25","number":25,"surah":11,"verses":[12],"verseLabel":"هود: 12","question":"لماذا اقترحوا كنزًا أو ملكًا مع الوحي؟","answer":"لأنهم قاسوا الرسالة بموازين الجاه والثراء، فطلبوا علامة مادية توافق تصورهم، بينما وظيفة الرسول الإنذار لا امتلاك خزائن الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص492–504، هود: 12.","url":""}]},{"id":"s11-26","number":26,"surah":11,"verses":[12],"verseLabel":"هود: 12","question":"لماذا ختمت الآية بـ﴿والله على كل شيء وكيل﴾؟","answer":"لتطمئن النبي أن حفظ الدعوة وتدبير نتائجها على الله؛ فعليه البلاغ ولا يلزمه تحقيق مقترحاتهم أو التحكم في استجابتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص492–504، هود: 12.","url":""}]},{"id":"s11-27","number":27,"surah":11,"verses":[13],"verseLabel":"هود: 13","question":"لماذا تحداهم هنا بعشر سور، وفي يونس بسورة واحدة؟","answer":"جاء هنا في سياق تماديهم في دعوى الافتراء، فتدرج التحدي وكشف عجزهم ولو عن مجموعة سور مفتريات مع الاستعانة بكل من يقدرون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص505–519، هود: 13.","url":""}]},{"id":"s11-28","number":28,"surah":11,"verses":[13],"verseLabel":"هود: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مفتريات﴾ مع أن الافتراء باطل؟","answer":"جاراهم في فرضهم: إن كان القرآن مفترى كما تزعمون فاختلقوا أنتم عشر سور تشبهه؛ فحتى مع إسقاط قيد الصدق عجزوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص505–519، هود: 13.","url":""}]},{"id":"s11-29","number":29,"surah":11,"verses":[14],"verseLabel":"هود: 14","question":"لماذا انتقل الخطاب في ﴿فإن لم يستجيبوا لكم﴾؟","answer":"الخطاب للمشركين على الأظهر: إن لم يجبكم أعوانكم إلى المعارضة فاعلموا أن القرآن منزل بعلم الله؛ فسقوط المعين يكشف سقوط الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص520–530، هود: 14.","url":""}]},{"id":"s11-30","number":30,"surah":11,"verses":[14],"verseLabel":"هود: 14","question":"لماذا ختم التحدي بسؤال ﴿فهل أنتم مسلمون﴾؟","answer":"لأن العجز ليس نهاية مناظرة لغوية فقط، بل حجة تستدعي قرارًا: هل تنقادون بعد أن ثبت أن القرآن من عند الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص520–530، هود: 14.","url":""}]},{"id":"s11-31","number":31,"surah":11,"verses":[15],"verseLabel":"هود: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿من كان يريد الحياة الدنيا وزينتها﴾ ولم يكتفِ بالدنيا؟","answer":"فرق بين أصل الحياة وما يلتصق بها من زخارف؛ ليشمل من جعل غايته البقاء واللذة والجاه جميعًا دون نظر إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص531–539، هود: 15.","url":""}]},{"id":"s11-32","number":32,"surah":11,"verses":[15],"verseLabel":"هود: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿نوف إليهم أعمالهم فيها وهم فيها لا يبخسون﴾؟","answer":"قد ينال صاحب العمل الدنيوي ثمرته العاجلة كاملة، لكن وفاء الأجر في الدنيا لا يعني قبول العمل في الآخرة إذا خلا من قصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص531–539، هود: 15.","url":""}]},{"id":"s11-33","number":33,"surah":11,"verses":[16],"verseLabel":"هود: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿وحبط ما صنعوا فيها وباطل ما كانوا يعملون﴾؟","answer":"الحبوط يصور سقوط ثمرة ما صنعوه، والباطل يكشف فساد قيمة أعمالهم الأخروية؛ فجمع ضياع النتيجة وانعدام الوزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص540–545، هود: 16.","url":""}]},{"id":"s11-34","number":34,"surah":11,"verses":[17],"verseLabel":"هود: 17","question":"لماذا عبّر عن المؤمن بأنه ﴿على بينة من ربه﴾؟","answer":"﴿على﴾ تشعر بالتمكن والثبات، والبينة نور واضح من الله؛ فالمؤمن قائم على حجة لا على تقليد أو هوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص546–579، هود: 17.","url":""}]},{"id":"s11-35","number":35,"surah":11,"verses":[17],"verseLabel":"هود: 17","question":"ما المراد بالشاهد الذي ﴿يتلوه منه﴾، ولماذا جاء بعد البينة؟","answer":"تعددت أقوال المفسرين فيه، وأشهرها القرآن أو شاهد من الله؛ والمقصود تتابع دلائل التصديق، فلا تقوم الرسالة على دليل منفرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص546–579، هود: 17.","url":""}]},{"id":"s11-36","number":36,"surah":11,"verses":[17],"verseLabel":"هود: 17","question":"لماذا وصف التوراة بأنها ﴿إمامًا ورحمة﴾؟","answer":"لأنها كانت كتابًا يُقتدى به في الهداية، ورحمة لمن اتبعها، فشهادتها للوحي الجديد امتداد لسلسلة الكتب لا أمر منقطع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص546–579، هود: 17.","url":""}]},{"id":"s11-37","number":37,"surah":11,"verses":[17],"verseLabel":"هود: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تك في مرية منه﴾ مع يقين النبي؟","answer":"تثبيت له، وتعريض بمن يشك، وتعليم للأمة أن اجتماع البينة والشاهد والكتاب السابق يقطع أسباب الارتياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص546–579، هود: 17.","url":""}]},{"id":"s11-38","number":38,"surah":11,"verses":[18],"verseLabel":"هود: 18","question":"لماذا عدّ افتراء الكذب على الله أظلم الظلم؟","answer":"لأنه يفسد أصل الهداية وينسب إلى الله ما لم يقله، فيضل صاحبه ويضل غيره؛ لذلك عُرض أصحابه على ربهم وشهد عليهم الأشهاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص580–595، هود: 18.","url":""}]},{"id":"s11-39","number":39,"surah":11,"verses":[18],"verseLabel":"هود: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿هؤلاء الذين كذبوا على ربهم﴾ أمام الأشهاد؟","answer":"اسم الإشارة يشهرهم بعد أن كانوا يفترون في الخفاء، وشهادة الأشهاد تقلب دعواهم إلى فضيحة عامة يوم الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص580–595، هود: 18.","url":""}]},{"id":"s11-40","number":40,"surah":11,"verses":[19],"verseLabel":"هود: 19","question":"لماذا وصفهم بأنهم ﴿يصدون عن سبيل الله ويبغونها عوجًا﴾؟","answer":"لم يكتفوا بضلال أنفسهم، بل منعوا غيرهم وصوروا الطريق المستقيم معوجًا؛ فجمعوا الصد والتحريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص596–611، هود: 19.","url":""}]},{"id":"s11-41","number":41,"surah":11,"verses":[20],"verseLabel":"هود: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كانوا معجزين في الأرض﴾؟","answer":"ينفي قدرتهم على الإفلات من سلطان الله في أي مكان، ثم ينفي وجود أولياء ينصرونهم؛ فسد عليهم طريق الهرب وطريق الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص596–611، هود: 20.","url":""}]},{"id":"s11-42","number":42,"surah":11,"verses":[20],"verseLabel":"هود: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿يضاعف لهم العذاب ما كانوا يستطيعون السمع وما كانوا يبصرون﴾؟","answer":"لأنهم عطلوا أدوات الهداية عمدًا؛ فصار الإعراض المتكرر سببًا لمضاعفة الجزاء، لا عجزًا خَلقيًا عن السمع والبصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص596–611، هود: 20.","url":""}]},{"id":"s11-43","number":43,"surah":11,"verses":[21],"verseLabel":"هود: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وضل عنهم ما كانوا يفترون﴾؟","answer":"صوّر الآلهة والدعاوى الباطلة كشيء بحثوا عنه وقت الحاجة ففقدوه؛ فما صنعه الوهم لا يحضر عند الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص596–611، هود: 21.","url":""}]},{"id":"s11-44","number":44,"surah":11,"verses":[22],"verseLabel":"هود: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿لا جرم أنهم في الآخرة هم الأخسرون﴾؟","answer":"﴿لا جرم﴾ تفيد تحقق الحكم، وضمير الفصل مع صيغة التفضيل يثبت أنهم بلغوا النهاية في الخسران: خسروا أنفسهم ومعبوداتهم وأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص596–611، هود: 22.","url":""}]},{"id":"s11-45","number":45,"surah":11,"verses":[23],"verseLabel":"هود: 23","question":"لماذا عُدي الإخبات بـ﴿إلى﴾ في ﴿وأخبتوا إلى ربهم﴾؟","answer":"لأن الإخبات ليس خشوعًا ساكنًا فقط، بل توجه وطمأنينة وانقياد ينتهي إلى الله؛ فالحرف يرسم جهة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص612–621، هود: 23.","url":""}]},{"id":"s11-46","number":46,"surah":11,"verses":[24],"verseLabel":"هود: 24","question":"لماذا شبّه الفريقين بالأعمى والأصم، والبصير والسميع؟","answer":"الكافر لا يرى الدليل ولا يسمع داعيه سماع قبول، والمؤمن يجمع الإدراكين؛ فالصورة تحول الفرق المعنوي إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص622–632، هود: 24.","url":""}]},{"id":"s11-47","number":47,"surah":11,"verses":[24],"verseLabel":"هود: 24","question":"لماذا ختم المثل بقوله: ﴿هل يستويان مثلًا أفلا تذكرون﴾؟","answer":"الاستفهام يحمل السامع على إصدار الحكم بنفسه، ثم يوبخه على ترك أبسط تذكر يميز بين النور والعمى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص622–632، هود: 24.","url":""}]},{"id":"s11-48","number":48,"surah":11,"verses":[25],"verseLabel":"هود: 25","question":"لماذا افتتح نوح دعوته بقوله: ﴿إني لكم نذير مبين﴾؟","answer":"عرّف مهمته بوضوح قبل التفصيل: إنذار صادق لا طلب ملك أو مال، و﴿لكم﴾ تشعر بأن إنذاره لمصلحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص633–639، هود: 25.","url":""}]},{"id":"s11-49","number":49,"surah":11,"verses":[26],"verseLabel":"هود: 26","question":"لماذا حصر العبادة بقوله: ﴿ألا تعبدوا إلا الله﴾؟","answer":"لأن أصل فسادهم توزيع العبادة بين الله وغيره، فجاء النفي والاستثناء ليهدما كل شريك ويثبتا العبادة له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص640–648، هود: 26.","url":""}]},{"id":"s11-50","number":50,"surah":11,"verses":[27],"verseLabel":"هود: 27","question":"لماذا وصف الملأ نوحًا بأنه ﴿بشرًا مثلنا﴾؟","answer":"جعلوا البشرية مانعًا من الرسالة، مع أنها موضع الاقتداء والفهم؛ فكشف اعتراضهم أنهم يطلبون تميزًا ماديًا لا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص649–671، هود: 27.","url":""}]},{"id":"s11-51","number":51,"surah":11,"verses":[27],"verseLabel":"هود: 27","question":"ما وجه قولهم عن أتباع نوح: ﴿أراذلنا بادي الرأي﴾؟","answer":"احتقروا ضعفهم الاجتماعي وزعموا أنهم آمنوا لأول خاطر بلا تدبر، فاستبدلوا وزن الدليل بميزان الطبقة والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص649–671، هود: 27.","url":""}]},{"id":"s11-52","number":52,"surah":11,"verses":[27],"verseLabel":"هود: 27","question":"ما وجه قولهم: ﴿وما نرى لكم علينا من فضل﴾؟","answer":"جمعوا الرسول وأتباعه في خطاب واحد، وجعلوا التفوق الدنيوي معيار الحق؛ فلما لم يجدوا مالًا أو جاهًا نفوا الفضل كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص649–671، هود: 27.","url":""}]},{"id":"s11-53","number":53,"surah":11,"verses":[28],"verseLabel":"هود: 28","question":"ما سرّ التعبير في قول نوح: ﴿إن كنت على بينة من ربي وآتاني رحمة من عنده فعميت عليكم﴾؟","answer":"قابل ظنهم الظاهر ببصيرته القائمة على البينة، وبيّن أن خفاء الرحمة عنهم ناشئ من إعراضهم لا من ضعفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص672–688، هود: 28.","url":""}]},{"id":"s11-54","number":54,"surah":11,"verses":[28],"verseLabel":"هود: 28","question":"ما سرّ التعبير في قوله تعالى: ﴿أنلزمكموها وأنتم لها كارهون﴾؟","answer":"الإيمان لا يتحقق بإكراه القلب، والعبارة الطويلة في ﴿أنلزمكموها﴾ تشعر بثقل الإلزام الذي أنكروه؛ ومهمة الرسول البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص672–688، هود: 28.","url":""}]},{"id":"s11-55","number":55,"surah":11,"verses":[29],"verseLabel":"هود: 29","question":"لماذا كرر نوح: ﴿يا قوم﴾؟","answer":"التكرار يستعطفهم ويؤكد بقاء رابطة النصح رغم أذاهم؛ فهو لا يخاطب أعداء غرباء بل قومًا يريد نجاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص689–701، هود: 29.","url":""}]},{"id":"s11-56","number":56,"surah":11,"verses":[29],"verseLabel":"هود: 29","question":"ما سرّ التعبير في قوله تعالى: ﴿لا أسألكم عليه مالًا إن أجري إلا على الله﴾؟","answer":"نفى التهمة التي قد تحجبهم عن مضمون الدعوة؛ فاستغناؤه عن مالهم دليل إخلاصه، وحصر أجره في الله يحرره من ضغطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص689–701، هود: 29.","url":""}]},{"id":"s11-57","number":57,"surah":11,"verses":[29],"verseLabel":"هود: 29","question":"لماذا رفض طرد المؤمنين الضعفاء؟","answer":"لأن قيمتهم بلقاء ربهم وإيمانهم لا بمكانتهم عند الملأ؛ وطردهم إرضاءً للكبراء يقلب ميزان الرسالة إلى ميزان الجاهلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص689–701، هود: 29.","url":""}]},{"id":"s11-58","number":58,"surah":11,"verses":[30],"verseLabel":"هود: 30","question":"ما سرّ التعبير في قوله تعالى: ﴿من ينصرني من الله إن طردتهم﴾؟","answer":"نقل السؤال من رضا الزعماء إلى حساب الله: من يحمي الرسول إن ظلم عبادًا آمنوا؟ وبذلك كشف أن اقتراحهم يوقعه في معصية لا مصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص702–707، هود: 30.","url":""}]},{"id":"s11-59","number":59,"surah":11,"verses":[31],"verseLabel":"هود: 31","question":"لماذا نفى نوح امتلاك خزائن الله وعلم الغيب والملكية؟","answer":"صحح تصور النبوة: الرسول بشر يوحى إليه، لا يملك الرزق ولا الغيب ولا يتكلف طبيعة الملك؛ فقيمة دعوته في الوحي لا الخوارق المقترحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص708–721، هود: 31.","url":""}]},{"id":"s11-60","number":60,"surah":11,"verses":[31],"verseLabel":"هود: 31","question":"ما سرّ التعبير في قوله تعالى عن الضعفاء: ﴿الله أعلم بما في أنفسهم﴾؟","answer":"لم يزكِّ باطنهم من عند نفسه، لكنه رفض احتقارهم؛ فحساب السرائر لله، والواجب قبول ظاهر الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص708–721، هود: 31.","url":""}]},{"id":"s11-61","number":61,"surah":11,"verses":[32],"verseLabel":"هود: 32","question":"ما وجه قولهم: ﴿قد جادلتنا فأكثرت جدالنا﴾؟","answer":"حولوا طول البيان والحجة إلى تهمة، ثم طلبوا العذاب استعجالًا؛ وهو انتقال من عجز المناظرة إلى المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص722–728، هود: 32.","url":""}]},{"id":"s11-62","number":62,"surah":11,"verses":[33],"verseLabel":"هود: 33","question":"ما سرّ التعبير في قول نوح: ﴿إنما يأتيكم به الله إن شاء﴾؟","answer":"رد طلب العذاب إلى مالكه؛ فالرسول لا يستعرض القوة ولا يحدد ميعاد العقوبة، وإنما ينذر بما يملكه الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص729–734، هود: 33.","url":""}]},{"id":"s11-63","number":63,"surah":11,"verses":[34],"verseLabel":"هود: 34","question":"ما وجه عدم انتفاع القوم بنصح نوح عليه السلام إذا أراد الله إغواءهم؟","answer":"المعنى أن من أصر حتى استحق الخذلان لا ينتفع بالنصح؛ فإرادة الله جزاء لا تلغي مسؤوليتهم، وإليه يرجعون للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص735–742، هود: 34.","url":""}]},{"id":"s11-64","number":64,"surah":11,"verses":[35],"verseLabel":"هود: 35","question":"لماذا اعترضت جملة ﴿أم يقولون افتراه﴾ وسط قصة نوح؟","answer":"لتصل القصة بحال مكذبي محمد ﷺ؛ فاتهام الرسول بالافتراء واحد، والجواب أن تبعة الإجرام على صاحبه والرسول بريء منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص743–748، هود: 35.","url":""}]},{"id":"s11-65","number":65,"surah":11,"verses":[36],"verseLabel":"هود: 36","question":"ما سرّ التعبير بقوله تعالى: لنوح: ﴿لن يؤمن من قومك إلا من قد آمن﴾؟","answer":"إعلان انتهاء زمن الاستجابة بعد استنفاد البلاغ؛ فأراحه من انتظار جديد، ونهاه عن الحزن على اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص749–755، هود: 36.","url":""}]},{"id":"s11-66","number":66,"surah":11,"verses":[37],"verseLabel":"هود: 37","question":"لماذا صنع نوح الفلك ﴿بأعيننا ووحينا﴾؟","answer":"﴿بأعيننا﴾ كناية عن الحفظ والرعاية، و﴿وحينا﴾ عن التعليم الدقيق؛ فالمشروع الغريب في الصحراء يجري تحت ضمان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص756–762، هود: 37.","url":""}]},{"id":"s11-67","number":67,"surah":11,"verses":[37],"verseLabel":"هود: 37","question":"لماذا نُهي نوح عن مخاطبة الله في الظالمين؟","answer":"لأن الحكم قد صدر بإغراقهم بعد انغلاق باب الإيمان، فلا يكون مقام التنفيذ موضع شفاعة تعطل العدل الموعود.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص756–762، هود: 37.","url":""}]},{"id":"s11-68","number":68,"surah":11,"verses":[38],"verseLabel":"هود: 38","question":"لماذا عبّر بالمضارع: ﴿ويصنع الفلك﴾؟","answer":"يستحضر مشهد البناء المتجدد أمام الساخرين، وكل مرور للملأ يفتح جولة استهزاء؛ فكأن القارئ يرى الحدث.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص763–781، هود: 38.","url":""}]},{"id":"s11-69","number":69,"surah":11,"verses":[38],"verseLabel":"هود: 38","question":"ما سرّ التعبير في قول نوح: ﴿إن تسخروا منا فإنا نسخر منكم﴾؟","answer":"ليس مقابلة سباب، بل وعد بانكشاف موضع السخرية الحقيقي عند حلول العذاب؛ ستتحول سخريتهم القصيرة إلى حسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص763–781، هود: 38.","url":""}]},{"id":"s11-70","number":70,"surah":11,"verses":[39],"verseLabel":"هود: 39","question":"لماذا وصف العذاب بأنه ﴿يخزيه﴾ ثم ﴿عذاب مقيم﴾؟","answer":"الأول يصور فضيحته في الدنيا، والثاني دوامه في الآخرة؛ فجمع هوان العاجل واستمرار الآجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص782–793، هود: 39.","url":""}]},{"id":"s11-71","number":71,"surah":11,"verses":[40],"verseLabel":"هود: 40","question":"ما دلالة ﴿فار التنور﴾ علامةً لبدء الطوفان؟","answer":"خروج الماء من موضع النار انقلاب خارق للمألوف وإشارة حاسمة إلى تنفيذ الوعد؛ فإذا نبع الماء من التنور فغيره أولى أن يفور.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص794–812، هود: 40.","url":""}]},{"id":"s11-72","number":72,"surah":11,"verses":[40],"verseLabel":"هود: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿من كل زوجين اثنين﴾؟","answer":"أمر بحمل الذكر والأنثى من الأنواع اللازمة لبقاء الحياة بعد الطوفان؛ فجمع اللفظ معنى الاقتران ومعنى العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص794–812، هود: 40.","url":""}]},{"id":"s11-73","number":73,"surah":11,"verses":[40],"verseLabel":"هود: 40","question":"لماذا استُثني من أهل نوح ﴿من سبق عليه القول﴾؟","answer":"لأن القرابة لا تنقض حكم الإيمان والكفر؛ فالنجاة متصلة بالاستجابة لا بالنسب، وقد سبق الحكم على من اختار التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص794–812، هود: 40.","url":""}]},{"id":"s11-74","number":74,"surah":11,"verses":[41],"verseLabel":"هود: 41","question":"ما سرّ التعبير في قول نوح: ﴿بسم الله مجراها ومرساها﴾؟","answer":"نسب بدء السفينة وسيرها ووقوفها إلى اسم الله، ليعلن أن الأسباب المادية وحدها لا تنجي، وإنما تجري برعايته وتقف بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص9–22، هود: 41.","url":""}]},{"id":"s11-75","number":75,"surah":11,"verses":[41],"verseLabel":"هود: 41","question":"لماذا ختم بـ﴿إن ربي لغفور رحيم﴾ وسط مشهد الطوفان؟","answer":"ليبين أن حمل المؤمنين نجاة برحمته ومغفرته، وأن العاصفة ليست غضبًا مجردًا بل يجاورها باب الرحمة لمن آمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص9–22، هود: 41.","url":""}]},{"id":"s11-76","number":76,"surah":11,"verses":[42],"verseLabel":"هود: 42","question":"لماذا شُبهت أمواج الطوفان بالجبال؟","answer":"لبيان علوها وضخامتها وثقل رهبتها؛ فالسفينة لا تسير فوق ماء هادئ بل بين كتل هائلة لا ينجي منها إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص9–22، هود: 42.","url":""}]},{"id":"s11-77","number":77,"surah":11,"verses":[42],"verseLabel":"هود: 42","question":"لماذا نادى نوح ابنه ﴿وكان في معزل﴾؟","answer":"العزلة المكانية تكشف عزلته الإيمانية، ومع ذلك ظل قلب الأب متعلقًا بنجاته فناداه في آخر لحظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص9–22، هود: 42.","url":""}]},{"id":"s11-78","number":78,"surah":11,"verses":[43],"verseLabel":"هود: 43","question":"لماذا ظن ابن نوح أن الجبل سيعصمه من الماء؟","answer":"نظر إلى سبب مألوف وغفل عن أن الطوفان أمر إلهي تجاوز نظام الأسباب؛ لذلك صحح نوح تصوره: ﴿لا عاصم اليوم من أمر الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص23–42، هود: 43.","url":""}]},{"id":"s11-79","number":79,"surah":11,"verses":[43],"verseLabel":"هود: 43","question":"ما سرّ التعبير في قوله تعالى: ﴿وحال بينهما الموج فكان من المغرقين﴾؟","answer":"الجملة تقطع الحوار فجأة كما قطع الموج الصلة بينهما؛ فسرعة الأسلوب تجسد مباغتة النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص23–42، هود: 43.","url":""}]},{"id":"s11-80","number":80,"surah":11,"verses":[44],"verseLabel":"هود: 44","question":"لماذا خوطبت الأرض والسماء: ﴿يا أرض ابلعي ماءك ويا سماء أقلعي﴾؟","answer":"صوّرهما مأمورتين تستجيبان فورًا لسلطان الله؛ فالمشهد الكوني الهائل ينتهي بكلمتين موجزتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص43–78، هود: 44.","url":""}]},{"id":"s11-81","number":81,"surah":11,"verses":[44],"verseLabel":"هود: 44","question":"ما سرّ توجيه الخطاب إلى الأرض بـ﴿ابلعي﴾ وإلى السماء بـ﴿أقلعي﴾؟","answer":"الأرض مأمورة بابتلاع الماء الموجود، والسماء مأمورة بالكف عن إنزاله؛ فاختير لكل جهة الفعل المطابق لدورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص43–78، هود: 44.","url":""}]},{"id":"s11-82","number":82,"surah":11,"verses":[44],"verseLabel":"هود: 44","question":"لماذا بُنيت الأفعال للمجهول: ﴿غيض الماء وقضي الأمر﴾؟","answer":"لأن الفاعل معلوم وهو الله، والمقام يركز على سرعة تحقق النتائج وحسمها: نقص الماء وانتهى الحكم واستقرت السفينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص43–78، هود: 44.","url":""}]},{"id":"s11-83","number":83,"surah":11,"verses":[44],"verseLabel":"هود: 44","question":"لماذا ختم المشهد بـ﴿بعدًا للقوم الظالمين﴾؟","answer":"بعد سكون الطبيعة صدر الحكم الأخلاقي: لم يكن الغرق حادثًا طبيعيًا عابرًا، بل إبعادًا مستحقًا بسبب الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص43–78، هود: 44.","url":""}]},{"id":"s11-84","number":84,"surah":11,"verses":[45],"verseLabel":"هود: 45","question":"ما سرّ التعبير في قول نوح: ﴿إن ابني من أهلي وإن وعدك الحق﴾؟","answer":"لم يعترض، بل استوضح وجه الوعد اعتمادًا على ظاهر الأهل؛ فجمع عاطفة الأب وأدب النبي في رد الأمر إلى حكم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص79–88، هود: 45.","url":""}]},{"id":"s11-85","number":85,"surah":11,"verses":[46],"verseLabel":"هود: 46","question":"ما سرّ التعبير في قوله تعالى عن ابن نوح: ﴿إنه ليس من أهلك إنه عمل غير صالح﴾؟","answer":"نفى عنه أهلية النجاة لا النسب، لأن رابطة الإيمان مقدمة في هذا الوعد؛ وقد جسّد الابن العمل الفاسد حتى كأنه نفس العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص89–103، هود: 46.","url":""}]},{"id":"s11-86","number":86,"surah":11,"verses":[46],"verseLabel":"هود: 46","question":"لماذا عُد سؤال نوح مما ليس له به علم؟","answer":"لأنه بنى الطلب على فهم لم يتبين له تمامه، فعلّمه الله ألا يتقدم بين يدي الوحي ولو حمله أشرف العواطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص89–103، هود: 46.","url":""}]},{"id":"s11-87","number":87,"surah":11,"verses":[47],"verseLabel":"هود: 47","question":"ما سرّ التعبير في قول نوح: ﴿أعوذ بك أن أسألك ما ليس لي به علم﴾؟","answer":"لم يكتفِ بترك السؤال، بل استعاذ من عودته واعترف بحاجته إلى المغفرة والرحمة؛ وهذا كمال سرعة الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص104–112، هود: 47.","url":""}]},{"id":"s11-88","number":88,"surah":11,"verses":[48],"verseLabel":"هود: 48","question":"ما سرّ التعبير بقوله تعالى: ﴿اهبط بسلام منا وبركات عليك﴾؟","answer":"قابل خوف الطوفان بأمن السلام، وفقد العالم بامتداد البركات؛ فكان الهبوط بداية عمران جديد تحت رعاية الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص113–126، هود: 48.","url":""}]},{"id":"s11-89","number":89,"surah":11,"verses":[48],"verseLabel":"هود: 48","question":"لماذا ذُكرت أمم سيُمَتَّعون ثم يمسهم العذاب؟","answer":"حتى لا يُتوهم أن ذرية الناجين كلها ستبقى على الإيمان؛ فحرية الاختيار ستنشئ مؤمنين ومنحرفين، والمتاع لا يدل وحده على الرضا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص113–126، هود: 48.","url":""}]},{"id":"s11-90","number":90,"surah":11,"verses":[49],"verseLabel":"هود: 49","question":"ما سرّ التعبير بقوله تعالى: للنبي بعد القصة: ﴿تلك من أنباء الغيب نوحيها إليك﴾؟","answer":"لأن تفاصيلها لم تكن معلومة له ولا لقومه، فصارت دقة الخبر شاهدًا على الوحي، ثم استُخرج منها أمر الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص127–139، هود: 49.","url":""}]},{"id":"s11-91","number":91,"surah":11,"verses":[49],"verseLabel":"هود: 49","question":"لماذا ختمت قصة نوح بـ﴿فاصبر إن العاقبة للمتقين﴾؟","answer":"نقل القصة من الماضي إلى حاضر الدعوة: كما طال ابتلاء نوح ثم نجا، فاصبر؛ فالعبرة ليست الحكاية بل تثبيت الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص127–139، هود: 49.","url":""}]},{"id":"s11-92","number":92,"surah":11,"verses":[50],"verseLabel":"هود: 50","question":"ما سرّ التعبير في قوله تعالى في إرسال هود إلى عاد: ﴿أخاهم هودًا﴾؟","answer":"أخوّته لهم في النسب والقوم تجعل نصحه أقرب، وتنفي أن يكون غريبًا عن مصالحهم؛ أما مفاصلته فكانت في العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص140–154، هود: 50.","url":""}]},{"id":"s11-93","number":93,"surah":11,"verses":[50],"verseLabel":"هود: 50","question":"ما سرّ التعبير في قوله تعالى: ﴿ما لكم من إله غيره إن أنتم إلا مفترون﴾؟","answer":"بعد حصر الإله الحق كشف أن تعدد الآلهة اختلاق بلا برهان؛ فالشرك ليس نقص دليل فقط بل نسبة باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص140–154، هود: 50.","url":""}]},{"id":"s11-94","number":94,"surah":11,"verses":[51],"verseLabel":"هود: 51","question":"لماذا كرر هود ما قاله نوح: ﴿لا أسألكم عليه أجرًا﴾؟","answer":"وحدة العبارة تكشف وحدة منهج الرسل: الدعوة خالصة لا تجارة، وأجرهم عند الخالق الذي فطرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص140–154، هود: 51.","url":""}]},{"id":"s11-95","number":95,"surah":11,"verses":[52],"verseLabel":"هود: 52","question":"لماذا ربط الاستغفار بنزول المطر وزيادة القوة؟","answer":"لأن التوبة تصلح الصلة بالله فتفتح أبواب البركة، وجاء الوعد بما يحتاجه قوم عاد خاصة: الغيث والقوة فوق قوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص155–165، هود: 52.","url":""}]},{"id":"s11-96","number":96,"surah":11,"verses":[53],"verseLabel":"هود: 53","question":"ما وجه قول قوم هود: ﴿ما جئتنا ببينة﴾ مع وضوح دعوته؟","answer":"حصروا البينة في خوارق يختارونها وتجاهلوا حجة التوحيد وصدق الرسول؛ فالنفي وصف لعنادهم لا لفقد الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص166–173، هود: 53.","url":""}]},{"id":"s11-97","number":97,"surah":11,"verses":[54],"verseLabel":"هود: 54","question":"لماذا اتهموا بعض آلهتهم بأنها أصابت هودًا بسوء؟","answer":"عجزوا عن رد حجته ففسروا ثباته بالمس والجنون، ونسبوا الضر إلى أصنامهم ليحموا هيبتها؛ فجاء إعلان براءته منها وتحديه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص166–173، هود: 54.","url":""}]},{"id":"s11-98","number":98,"surah":11,"verses":[55],"verseLabel":"هود: 55","question":"لماذا تحداهم هود جميعًا: ﴿فكيدوني جميعًا ثم لا تنظرون﴾؟","answer":"إظهار عملي لبطلان آلهتهم وثقته بالله؛ دعاهم مع معبوداتهم إلى أقصى الكيد دون إمهال، فعجزهم حجة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص174–189، هود: 55.","url":""}]},{"id":"s11-99","number":99,"surah":11,"verses":[56],"verseLabel":"هود: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿إني توكلت على الله ربي وربكم﴾؟","answer":"جمع بين ربوبيته الخاصة التي تبعث الطمأنينة وربوبيته لهم التي تثبت سلطان الله عليهم ولو أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص190–200، هود: 56.","url":""}]},{"id":"s11-100","number":100,"surah":11,"verses":[56],"verseLabel":"هود: 56","question":"ما سر صورة ﴿ما من دابة إلا هو آخذ بناصيتها﴾؟","answer":"الناصية موضع القيادة، فالصورة تجعل كل حي تحت القبضة والتدبير؛ لا تتحرك قوة مستقلة عن سلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص190–200، هود: 56.","url":""}]},{"id":"s11-101","number":101,"surah":11,"verses":[56],"verseLabel":"هود: 56","question":"لماذا أتبع القدرة بقوله: ﴿إن ربي على صراط مستقيم﴾؟","answer":"حتى لا تُفهم القدرة بطشًا بلا حكمة؛ تدبيره قائم على العدل والحق، فلا يضيع المتوكل ولا ينجو الظالم بظلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص190–200، هود: 56.","url":""}]},{"id":"s11-102","number":102,"surah":11,"verses":[57],"verseLabel":"هود: 57","question":"ما سرّ التعبير في قول هود: ﴿فقد أبلغتكم ما أرسلت به إليكم﴾؟","answer":"أقام الحجة وأعلن تمام مهمته؛ فإذا تولوا فالخسارة عليهم، والله قادر أن يستبدل بهم قومًا لا يعصونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص201–211، هود: 57.","url":""}]},{"id":"s11-103","number":103,"surah":11,"verses":[58],"verseLabel":"هود: 58","question":"لماذا تكرر فعل النجاة: ﴿نجينا هودًا... ونجيناهم من عذاب غليظ﴾؟","answer":"الأولى نجاة من العذاب الدنيوي عند مجيء الأمر، والثانية نجاة من العذاب الغليظ أو تأكيد لعظم الرحمة؛ فجمعت وجهي السلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص212–223، هود: 58.","url":""}]},{"id":"s11-104","number":104,"surah":11,"verses":[59],"verseLabel":"هود: 59","question":"ما سرّ التعبير في قوله تعالى عن عاد: ﴿وتلك عاد جحدوا بآيات ربهم﴾؟","answer":"اسم الإشارة يعرضهم كأثر حاضر للعبرة، وجمع الجحود وعصيان الرسل واتباع الجبابرة جذور سقوطهم الديني والسياسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص224–235، هود: 59.","url":""}]},{"id":"s11-105","number":105,"surah":11,"verses":[60],"verseLabel":"هود: 60","question":"لماذا تكررت اللعنة في الدنيا ويوم القيامة؟","answer":"لأن آثار جحودهم لحقتهم في التاريخ، ثم تتجدد كاملة في الآخرة؛ فليس سقوط حضارتهم نهاية الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص236–245، هود: 60.","url":""}]},{"id":"s11-106","number":106,"surah":11,"verses":[60],"verseLabel":"هود: 60","question":"لماذا ختمت قصتهم بـ﴿ألا بعدًا لعاد قوم هود﴾؟","answer":"﴿ألا﴾ تلفت إلى الحكم النهائي، ونسبتهم إلى هود تزيد التوبيخ: جاءهم ناصح منهم فعادوه، فاستحقوا الإبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص236–245، هود: 60.","url":""}]},{"id":"s11-107","number":107,"surah":11,"verses":[61],"verseLabel":"هود: 61","question":"ما سرّ التعبير في قول صالح: ﴿هو أنشأكم من الأرض واستعمركم فيها﴾؟","answer":"ذكّرهم بأصلهم الأرضي وبالتكليف بعمارتها؛ فالذي أنشأهم ومكّنهم هو المستحق للعبادة لا ما يصنعونه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص246–260، هود: 61.","url":""}]},{"id":"s11-108","number":108,"surah":11,"verses":[61],"verseLabel":"هود: 61","question":"لماذا ختم دعوة التوبة بـ﴿إن ربي قريب مجيب﴾؟","answer":"القرب يزيل وحشة الرجوع، والإجابة تبعث الأمل في قبول الدعاء؛ فجاءت الخاتمة ملائمة للاستغفار والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص246–260، هود: 61.","url":""}]},{"id":"s11-109","number":109,"surah":11,"verses":[62],"verseLabel":"هود: 62","question":"ما وجه قول قوم صالح: ﴿قد كنت فينا مرجوًا قبل هذا﴾؟","answer":"حاولوا الضغط عليه بماضي مكانته بينهم: كنا نرجو أن تكون زعيمًا موافقًا لنا، فإذا بالتوحيد يهدم توقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص261–272، هود: 62.","url":""}]},{"id":"s11-110","number":110,"surah":11,"verses":[62],"verseLabel":"هود: 62","question":"لماذا وصفوا دعوتهم بأنها في ﴿شك مريب﴾؟","answer":"المريب ما يوقع في الريبة ويقلق النفس؛ بالغوا في وصف شكهم ليبرروا رفض الموروث، مع أن منشأ القلق تعارض الحق مع عادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص261–272، هود: 62.","url":""}]},{"id":"s11-111","number":111,"surah":11,"verses":[63],"verseLabel":"هود: 63","question":"ما سرّ التعبير في قول صالح: ﴿فمن ينصرني من الله إن عصيته﴾؟","answer":"رد طلبهم ضمنًا إلى ميزان المسؤولية: موافقتهم في الشرك عصيان، ولا يملك أحد حمايته من الله إن ترك البينة إرضاء لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص273–291، هود: 63.","url":""}]},{"id":"s11-112","number":112,"surah":11,"verses":[64],"verseLabel":"هود: 64","question":"لماذا سميت الناقة ﴿ناقة الله﴾؟","answer":"إضافة تشريف وملكية خاصة؛ لأنها آية خلقها الله على وجه خارق وجعل لها حرمة، لا لأنها تحتاج إلى مرعى يملكه البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص292–303، هود: 64.","url":""}]},{"id":"s11-113","number":113,"surah":11,"verses":[64],"verseLabel":"هود: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿فذروها تأكل في أرض الله﴾؟","answer":"قابل ملكيتهم الضيقة بملك الله للأرض كلها؛ فلا حق لهم في منع آيته من رزقه، والمس بها يستجلب عذابًا قريبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص292–303، هود: 64.","url":""}]},{"id":"s11-114","number":114,"surah":11,"verses":[65],"verseLabel":"هود: 65","question":"لماذا أُمهلوا ثلاثة أيام بعد عقر الناقة؟","answer":"إقامة للحجة وإتاحة زمن يرون فيه صدق الوعيد قبل وقوعه، ووصف الوعد بأنه غير مكذوب يقطع احتمال النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص304–312، هود: 65.","url":""}]},{"id":"s11-115","number":115,"surah":11,"verses":[66],"verseLabel":"هود: 66","question":"ما سرّ التعبير في قوله تعالى: ﴿نجينا صالحًا والذين آمنوا معه برحمة منا ومن خزي يومئذ﴾؟","answer":"النجاة ليست بالقوة بل برحمة الله، وسمى العذاب خزيًا لأنه فضح المكذبين وأذلهم في اليوم الذي توهموا القدرة على الإفلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص313–333، هود: 66.","url":""}]},{"id":"s11-116","number":116,"surah":11,"verses":[67],"verseLabel":"هود: 67","question":"لماذا أخذ الظالمين ﴿الصيحة﴾؟","answer":"صيحة واحدة تناسب حسم القدرة الإلهية وتبطل مظاهر قوتهم؛ فتحولوا في ديارهم من متجبرين إلى أجساد هامدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص313–333، هود: 67.","url":""}]},{"id":"s11-117","number":117,"surah":11,"verses":[68],"verseLabel":"هود: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿كأن لم يغنوا فيها﴾؟","answer":"صور زوالهم التام حتى كأنهم لم يقيموا وينعموا في تلك الديار قط؛ وهو انقلاب يبدد غرور الحضارة الراسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص313–333، هود: 68.","url":""}]},{"id":"s11-118","number":118,"surah":11,"verses":[69],"verseLabel":"هود: 69","question":"لماذا بدأت قصة إبراهيم بقوله: ﴿ولقد جاءت رسلنا إبراهيم بالبشرى﴾؟","answer":"قُدمت البشرى لأنها مقصد زيارتهم الأول في حقه، ثم انكشف مقصدهم الآخر في قوم لوط؛ فجمع اللقاء رحمة للمؤمن وعقوبة للظالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص334–342، هود: 69.","url":""}]},{"id":"s11-119","number":119,"surah":11,"verses":[69],"verseLabel":"هود: 69","question":"ما سرّ التعبير في قول إبراهيم: ﴿فما لبث أن جاء بعجل حنيذ﴾؟","answer":"﴿فما لبث﴾ تفيد سرعة الضيافة، والعجل الحنيذ طعام كريم مشوي؛ فعبّر القليل عن تمام جوده قبل أن يعرف ضيوفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص334–342، هود: 69.","url":""}]},{"id":"s11-120","number":120,"surah":11,"verses":[70],"verseLabel":"هود: 70","question":"ما سبب خوف إبراهيم حين لم تصل أيديهم إلى الطعام؟","answer":"كان امتناع الضيف عن الطعام علامة ريبة في عرفهم، فظهرت مخافته قبل أن يعلم أنهم ملائكة لا يأكلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص334–354، هود: 70.","url":""}]},{"id":"s11-121","number":121,"surah":11,"verses":[71],"verseLabel":"هود: 71","question":"لماذا ضحكت امرأة إبراهيم قبل بشارتها بإسحاق؟","answer":"وردت أقوال في سبب الضحك، والسياق يجعله تمهيدًا لتحول الخوف إلى سرور، ثم جاءت البشرى بما يفوق انتظارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص343–354، هود: 71.","url":""}]},{"id":"s11-122","number":122,"surah":11,"verses":[71],"verseLabel":"هود: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن وراء إسحاق يعقوب﴾؟","answer":"لم تقتصر البشرى على الولد مع الكبر، بل امتدت إلى الحفيد؛ فضمنت بقاء إسحاق حتى يولد له يعقوب وزادت الطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص343–354، هود: 71.","url":""}]},{"id":"s11-123","number":123,"surah":11,"verses":[72],"verseLabel":"هود: 72","question":"لماذا جمعت سارة بين التعجب من كبرها وكبر زوجها؟","answer":"لأن سبب الاستبعاد مركب من حالهما معًا، فجاء الاستفهام ليصور شدة دهشتها البشرية أمام القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص355–377، هود: 72.","url":""}]},{"id":"s11-124","number":124,"surah":11,"verses":[73],"verseLabel":"هود: 73","question":"لماذا ردت الملائكة: ﴿أتعجبين من أمر الله﴾؟","answer":"ليس إنكارًا لقدرة الله منها، بل إزالة لمقياس العادة في مقام القدرة؛ وما يبدو عجيبًا للبشر يسير بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص355–377، هود: 73.","url":""}]},{"id":"s11-125","number":125,"surah":11,"verses":[73],"verseLabel":"هود: 73","question":"ما سرّ التعبير في قول الملائكة: ﴿رحمت الله وبركاته عليكم أهل البيت﴾؟","answer":"جعلوا الولد امتدادًا لرحمات وبركات عرفها هذا البيت النبوي، لا حادثًا منفصلًا؛ وختموا بالحمد والمجد المناسبين للإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص355–377، هود: 73.","url":""}]},{"id":"s11-126","number":126,"surah":11,"verses":[74],"verseLabel":"هود: 74","question":"لماذا أخذ إبراهيم يجادل الملائكة في قوم لوط بعد ذهاب الروع؟","answer":"لما زال خوفه وحصلت البشرى ظهر حلمه ورحمته، فراجع في تأخير العذاب رجاء وجود مؤمنين أو مهلة للتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص355–377، هود: 74.","url":""}]},{"id":"s11-127","number":127,"surah":11,"verses":[75],"verseLabel":"هود: 75","question":"لماذا وُصف إبراهيم بأنه ﴿حليم أواه منيب﴾؟","answer":"الحلم يفسر رفقه بالمعاندين، والأواه رقة قلبه، والإنابة رجوعه إلى الله؛ فهذه الصفات هي مصدر مجادلته الرحيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص355–377، هود: 75.","url":""}]},{"id":"s11-128","number":128,"surah":11,"verses":[76],"verseLabel":"هود: 76","question":"ما سرّ التعبير بقوله تعالى: له: ﴿أعرض عن هذا إنه قد جاء أمر ربك﴾؟","answer":"لأن الرحمة لا ترد حكمًا بلغ نهايته بعد قيام الحجة؛ فحين جاء الأمر صار الجدال بلا محل والعذاب غير مردود.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص378–400، هود: 76.","url":""}]},{"id":"s11-129","number":129,"surah":11,"verses":[77],"verseLabel":"هود: 77","question":"ما سرّ التعبير في قوله تعالى عن لوط: ﴿سيء بهم وضاق بهم ذرعًا﴾؟","answer":"ساءه مجيء الضيوف لما خشي عليهم من قومه، وضاق عجزه عن حمايتهم؛ فجمع ألم النفس وقلة الحيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص401–409، هود: 77.","url":""}]},{"id":"s11-130","number":130,"surah":11,"verses":[78],"verseLabel":"هود: 78","question":"ما سرّ عرض لوط على قومه الطريق الطاهر بقوله: ﴿هؤلاء بناتي هن أطهر لكم﴾؟","answer":"دعاهم إلى الطريق المشروع مع النساء، وقيل أراد نساء قومه لأن النبي بمنزلة الأب؛ والمقصود نقلهم من الفاحشة إلى الطهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص410–418، هود: 78.","url":""}]},{"id":"s11-131","number":131,"surah":11,"verses":[78],"verseLabel":"هود: 78","question":"ما سرّ التعبير في قوله تعالى: ﴿أليس منكم رجل رشيد﴾؟","answer":"استفهام يوقظ بقية الفطرة: أليس في هذا الجمع عاقل واحد يردهم عن فضيحة الضيف والفاحشة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص410–418، هود: 78.","url":""}]},{"id":"s11-132","number":132,"surah":11,"verses":[79],"verseLabel":"هود: 79","question":"ما وجه قول قوم لوط: ﴿لقد علمت ما لنا في بناتك من حق﴾؟","answer":"أعلنوا انصرافهم التام عن الحلال الذي عرضه، وزعموا أن مقصدهم معلوم؛ فبلغت المجاهرة حد إسقاط الحياء والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص419–440، هود: 79.","url":""}]},{"id":"s11-133","number":133,"surah":11,"verses":[80],"verseLabel":"هود: 80","question":"ما سرّ تمني لوط قوة أو ركنًا شديدًا؟","answer":"نطق بها في لحظة استضعاف طلبًا لوسيلة تحمي ضيوفه، مع أن ركنه الحقيقي كان الله؛ ولذلك كشفت الملائكة فورًا أنهم رسل ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص419–440، هود: 80.","url":""}]},{"id":"s11-134","number":134,"surah":11,"verses":[81],"verseLabel":"هود: 81","question":"لماذا أمر لوط أن يسري بأهله ﴿بقطع من الليل﴾؟","answer":"الليل أستر للخروج وأبعد عن ملاحقة القوم، والقطع جزء منه؛ فالتعبير يرسم نجاة خفية قبل حلول الصبح.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص441–456، هود: 81.","url":""}]},{"id":"s11-135","number":135,"surah":11,"verses":[81],"verseLabel":"هود: 81","question":"لماذا نُهوا عن الالتفات؟","answer":"ليقطعوا صلتهم النفسية والمكانية ببلد العذاب، ويمضوا إلى النجاة بلا تباطؤ أو تحسر على ما تركوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص441–456، هود: 81.","url":""}]},{"id":"s11-136","number":136,"surah":11,"verses":[81],"verseLabel":"هود: 81","question":"ما سرّ التعبير بقوله تعالى: ﴿إن موعدهم الصبح أليس الصبح بقريب﴾؟","answer":"استعجل لوط النجاة، فطمأنته الملائكة بقرب الموعد؛ والاستفهام يجعل قرب الصبح محسوسًا بعد ليل الضيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص441–456، هود: 81.","url":""}]},{"id":"s11-137","number":137,"surah":11,"verses":[82],"verseLabel":"هود: 82","question":"ما سرّ التعبير في قوله تعالى: ﴿جعلنا عاليها سافلها﴾؟","answer":"قلب القرى يناسب انقلابهم على الفطرة؛ فجاء الجزاء في صورته الحسية من جنس فسادهم المعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص457–476، هود: 82.","url":""}]},{"id":"s11-138","number":138,"surah":11,"verses":[82],"verseLabel":"هود: 82","question":"لماذا وصفت الحجارة بأنها ﴿من سجيل منضود﴾؟","answer":"سجيل يدل على حجارة عذاب شديدة، و﴿منضود﴾ يصورها متتابعة أو معدة بعضها فوق بعض؛ فلا يفلت منها المستهدف.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص457–476، هود: 82.","url":""}]},{"id":"s11-139","number":139,"surah":11,"verses":[83],"verseLabel":"هود: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿مسومة عند ربك﴾؟","answer":"أي معلَّمة أو مقدرة لمستحقيها، فتبدو العقوبة دقيقة لا عشوائية؛ كل حجر يجري بعلم وتقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص457–476، هود: 83.","url":""}]},{"id":"s11-140","number":140,"surah":11,"verses":[83],"verseLabel":"هود: 83","question":"لماذا ختم بـ﴿وما هي من الظالمين ببعيد﴾؟","answer":"يحول القصة إلى تهديد دائم لكل من يشابههم في الظلم؛ فالعبرة ليست محصورة في قوم مضوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص457–476، هود: 83.","url":""}]},{"id":"s11-141","number":141,"surah":11,"verses":[84],"verseLabel":"هود: 84","question":"ما سرّ التعبير في قوله تعالى في شعيب: ﴿أخاهم شعيبًا﴾؟","answer":"يكرر قرب الرسول من قومه ومعرفته بأحوالهم، فلا عذر لهم بدعوى الغربة؛ وقد واجه فساد عبادتهم ومعاملاتهم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص477–497، هود: 84.","url":""}]},{"id":"s11-142","number":142,"surah":11,"verses":[84],"verseLabel":"هود: 84","question":"لماذا جمع شعيب بين التوحيد والنهي عن نقص المكيال والميزان؟","answer":"لأن الدين لا ينفصل عن السوق؛ فمن عبد الله لزمه العدل في أموال الناس، وإلا ناقضت معاملته عقيدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص477–497، هود: 84.","url":""}]},{"id":"s11-143","number":143,"surah":11,"verses":[84],"verseLabel":"هود: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أراكم بخير﴾ ثم خوّفهم العذاب؟","answer":"كانوا في سعة تغنيهم عن الغش، فصار التطفيف أشد قبحًا؛ كما أن الخير القائم قد يزول بعذاب محيط إن كفروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص477–497، هود: 84.","url":""}]},{"id":"s11-144","number":144,"surah":11,"verses":[85],"verseLabel":"هود: 85","question":"لماذا زاد هنا ﴿بالقسط﴾ بعد الأمر بإيفاء المكيال والميزان؟","answer":"الإيفاء قد يدعى مع تفاوت خفي، فجاء القسط ليجعل العدل معيارًا دقيقًا في الكيل والوزن وكل حقوق الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص498–511، هود: 85.","url":""}]},{"id":"s11-145","number":145,"surah":11,"verses":[85],"verseLabel":"هود: 85","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تعثوا في الأرض مفسدين﴾؟","answer":"العثو فساد شديد منتشر، والحال ﴿مفسدين﴾ تكشف أن حركتهم في الأرض تحولت إلى صناعة فساد لا خطأ عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص498–511، هود: 85.","url":""}]},{"id":"s11-146","number":146,"surah":11,"verses":[86],"verseLabel":"هود: 86","question":"ما المقصود بـ﴿بقية الله خير لكم﴾؟","answer":"ما يبقيه الله لكم من الربح الحلال بعد ترك التطفيف خير من الزيادة المحرمة، ويدخل فيه ثواب الطاعة الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص512–520، هود: 86.","url":""}]},{"id":"s11-147","number":147,"surah":11,"verses":[86],"verseLabel":"هود: 86","question":"ما سرّ التعبير في قول شعيب: ﴿وما أنا عليكم بحفيظ﴾؟","answer":"مهمته البيان لا مراقبة كل صفقة وإجبارهم على العدل؛ فاستقامة المعاملة يجب أن تنبع من مراقبة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص512–520، هود: 86.","url":""}]},{"id":"s11-148","number":148,"surah":11,"verses":[87],"verseLabel":"هود: 87","question":"ما وجه قولهم ساخرين: ﴿أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء﴾؟","answer":"استنكروا أن تمتد الصلاة إلى العقيدة والاقتصاد، فكشفت سخريتهم حقيقة الصلاة: عبادة تعيد تشكيل السلوك لا طقسًا معزولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص521–535، هود: 87.","url":""}]},{"id":"s11-149","number":149,"surah":11,"verses":[87],"verseLabel":"هود: 87","question":"لماذا وصفوه بـ﴿الحليم الرشيد﴾ وهم يسخرون؟","answer":"قالوها تهكمًا؛ لأنهم رأوا مخالفته لموروثهم وحرية أموالهم ضد الحلم والرشد، بينما أثبت السياق أن الحلم والرشد الحقيقيين معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص521–535، هود: 87.","url":""}]},{"id":"s11-150","number":150,"surah":11,"verses":[88],"verseLabel":"هود: 88","question":"ما سرّ التعبير في قول شعيب: ﴿وما أريد أن أخالفكم إلى ما أنهاكم عنه﴾؟","answer":"أعلن اتساق القول والعمل: لا ينهاهم عن الغش ثم يفعله خفية، فمصداقية المصلح تبدأ من نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص536–560، هود: 88.","url":""}]},{"id":"s11-151","number":151,"surah":11,"verses":[88],"verseLabel":"هود: 88","question":"ما سرّ التعبير في قوله تعالى: ﴿إن أريد إلا الإصلاح ما استطعت﴾؟","answer":"حصر قصده في الإصلاح، لكنه قيده بالاستطاعة تواضعًا واعترافًا بحدود البشر؛ أما التوفيق فمن الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص536–560، هود: 88.","url":""}]},{"id":"s11-152","number":152,"surah":11,"verses":[89],"verseLabel":"هود: 89","question":"ما سرّ التعبير في قوله تعالى: ﴿لا يجرمنكم شقاقي﴾؟","answer":"أي لا يحملنكم بغضي ومخالفتي على الإصرار حتى يصيبكم ما أصاب الأمم؛ فلا تجعلوا الخصومة مع الداعية تحجبكم عن مصير الفكرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص561–598، هود: 89.","url":""}]},{"id":"s11-153","number":153,"surah":11,"verses":[89],"verseLabel":"هود: 89","question":"لماذا ختم تعداد الأمم بقوله: ﴿وما قوم لوط منكم ببعيد﴾؟","answer":"لأنهم قريبون زمانًا أو مكانًا ومعرفةً، وآثارهم أمامهم؛ فالحجة الأقرب أشد إيقاظًا من أخبار بعيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص561–598، هود: 89.","url":""}]},{"id":"s11-154","number":154,"surah":11,"verses":[90],"verseLabel":"هود: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ربي رحيم ودود﴾ بعد الاستغفار والتوبة؟","answer":"الرحمة تزيل أثر الذنب، والود يمنح التائب قربًا ومحبة؛ فلا يقتصر الرجوع على النجاة من العقوبة بل يفتح علاقة جديدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص561–598، هود: 90.","url":""}]},{"id":"s11-155","number":155,"surah":11,"verses":[91],"verseLabel":"هود: 91","question":"ما وجه قول قوم شعيب: ﴿ما نفقه كثيرًا مما تقول﴾ دون «لا نفهم»؟","answer":"ادعوا أن أكثر كلامه غامض مع وضوحه، وهي وسيلة لتهميش الحجة دون مناقشتها؛ ثم انتقلوا إلى استضعاف شخصه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص561–598، هود: 91.","url":""}]},{"id":"s11-156","number":156,"surah":11,"verses":[91],"verseLabel":"هود: 91","question":"ما وجه قولهم: ﴿ولولا رهطك لرجمناك﴾؟","answer":"اعترفوا أن الذي يمنعهم عصبية القبيلة لا حرمة الحق؛ فصار أمان الرسول عندهم للمجتمع لا للرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص561–598، هود: 91.","url":""}]},{"id":"s11-157","number":157,"surah":11,"verses":[92],"verseLabel":"هود: 92","question":"ما سرّ التعبير في قول شعيب: ﴿أرهطي أعز عليكم من الله﴾؟","answer":"فضح انقلاب ميزانهم: راعوا رهطه الضعيف ولم يراعوا الله القادر، فجعلوا حرمة القبيلة فوق حرمة الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص599–610، هود: 92.","url":""}]},{"id":"s11-158","number":158,"surah":11,"verses":[92],"verseLabel":"هود: 92","question":"ما دلالة ﴿واتخذتموه وراءكم ظهريًا﴾؟","answer":"صورة لمن يرمي الأمر خلف ظهره فلا يراه ولا يعتد به؛ جعلوا الله وأمره مهمَلًا مع أن علمه محيط بأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص599–610، هود: 92.","url":""}]},{"id":"s11-159","number":159,"surah":11,"verses":[93],"verseLabel":"هود: 93","question":"ما سرّ التعبير في قوله تعالى: ﴿اعملوا على مكانتكم إني عامل﴾؟","answer":"تهديد بعد استنفاد النصح: اثبتوا على طريقتكم وسأثبت على طريقتي، وستكشف العاقبة من يأتيه الخزي ومن هو كاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص611–634، هود: 93.","url":""}]},{"id":"s11-160","number":160,"surah":11,"verses":[94],"verseLabel":"هود: 94","question":"ما سرّ التعبير في قوله تعالى: ﴿نجينا شعيبًا والذين آمنوا معه برحمة منا﴾؟","answer":"نسب النجاة للرحمة لا للاستحقاق المجرد، فيبقى المؤمن شاكرًا حتى وهو على الحق؛ ثم قابلها أخذُ الظالمين بالصيحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص611–634، هود: 94.","url":""}]},{"id":"s11-161","number":161,"surah":11,"verses":[95],"verseLabel":"هود: 95","question":"لماذا تكرر ﴿كأن لم يغنوا فيها﴾ في ثمود ومدين؟","answer":"لتوحيد العبرة: مهما اختلفت قوة الحضارات وأسواقها، يمحو العذاب أثرها حتى كأنها لم تعمر المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص611–634، هود: 95.","url":""}]},{"id":"s11-162","number":162,"surah":11,"verses":[96],"verseLabel":"هود: 96","question":"ما سرّ التعبير في قوله تعالى: ﴿ولقد أرسلنا موسى بآياتنا وسلطان مبين﴾؟","answer":"الآيات دلائل محسوسة، والسلطان حجة وقوة بيان؛ فجمع لموسى ما يثبت صدقه أمام فرعون وملئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص635–645، هود: 96.","url":""}]},{"id":"s11-163","number":163,"surah":11,"verses":[97],"verseLabel":"هود: 97","question":"ما سرّ التعبير في قوله تعالى: ﴿فاتبعوا أمر فرعون وما أمر فرعون برشيد﴾؟","answer":"أبرز طاعتهم العمياء ثم حكم على مصدرها؛ فالمشكلة ليست في ضعف الحجة فقط بل في اتباع قيادة لا تقود إلى رشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص646–677، هود: 97.","url":""}]},{"id":"s11-164","number":164,"surah":11,"verses":[98],"verseLabel":"هود: 98","question":"ما سرّ التعبير في قوله تعالى عن فرعون: ﴿يقدم قومه يوم القيامة فأوردهم النار﴾؟","answer":"كما قادهم في الدنيا إلى الضلال يتقدمهم في الآخرة إلى نتيجته؛ فقلب صورة الزعيم الذي يوصل قومه إلى الموارد إلى قائد يوردهم النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص646–677، هود: 98.","url":""}]},{"id":"s11-165","number":165,"surah":11,"verses":[99],"verseLabel":"هود: 99","question":"لماذا سميت اللعنة ﴿رفدًا﴾ لهم في الدنيا والقيامة؟","answer":"الرفد عادة عطاء ومعونة، فاستعمل تهكمًا: عطاؤهم المتتابع لعنة في الدنيا ثم لعنة في الآخرة، وبئس العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص646–677، هود: 99.","url":""}]},{"id":"s11-166","number":166,"surah":11,"verses":[100],"verseLabel":"هود: 100","question":"ما سرّ التعبير في قوله تعالى عن القرى: ﴿منها قائم وحصيد﴾؟","answer":"شبه آثارها بزرع: منه ما بقي قائمًا يراه الناس، ومنه ما استؤصل كالحصيد؛ وفي الحالتين تشهد البقايا أو الفراغ بالمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص678–684، هود: 100.","url":""}]},{"id":"s11-167","number":167,"surah":11,"verses":[101],"verseLabel":"هود: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿فما أغنت عنهم آلهتهم... من شيء﴾؟","answer":"النفي مع ﴿من شيء﴾ يستغرق أدنى نفع؛ ففي اللحظة التي احتاجوا إليها غابت الآلهة، ولم تزدهم عبادتها إلا هلاكًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص685–694، هود: 101.","url":""}]},{"id":"s11-168","number":168,"surah":11,"verses":[102],"verseLabel":"هود: 102","question":"لماذا شُبه أخذ الله للقرى بأخذ واحد: ﴿إن أخذه أليم شديد﴾؟","answer":"جمع قصصًا متعددة في سنة واحدة: إذا أخذ الظالم بعد الإمهال جاء الأخذ موجعًا قويًا لا يفلت منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص695–701، هود: 102.","url":""}]},{"id":"s11-169","number":169,"surah":11,"verses":[103],"verseLabel":"هود: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿إن في ذلك لآية لمن خاف عذاب الآخرة﴾؟","answer":"المنتفع بالتاريخ هو من يرى وراء هلاك الدنيا حسابًا أكبر؛ أما من لا يخاف الآخرة فقد يشاهد الآثار ولا يعتبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص702–712، هود: 103.","url":""}]},{"id":"s11-170","number":170,"surah":11,"verses":[103],"verseLabel":"هود: 103","question":"لماذا وصف يوم القيامة بأنه ﴿يوم مجموع له الناس ويوم مشهود﴾؟","answer":"الناس يُجمعون لأجله، وتحضره الخلائق كلها؛ فليس حسابًا خفيًا أو فرديًا بل مشهدًا كونيًا جامعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص702–712، هود: 103.","url":""}]},{"id":"s11-171","number":171,"surah":11,"verses":[104],"verseLabel":"هود: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وما نؤخره إلا لأجل معدود﴾؟","answer":"تأخر القيامة ليس ترددًا ولا عجزًا؛ أجلها مضبوط معدود، فإذا اكتمل لم يتقدم ولم يتأخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص702–712، هود: 104.","url":""}]},{"id":"s11-172","number":172,"surah":11,"verses":[105],"verseLabel":"هود: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿لا تكلم نفس إلا بإذنه﴾؟","answer":"يسقط كل وهم في الاحتجاج أو الشفاعة المستقلة؛ حتى الكلام في ذلك الموقف خاضع لسلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص713–720، هود: 105.","url":""}]},{"id":"s11-173","number":173,"surah":11,"verses":[105],"verseLabel":"هود: 105","question":"لماذا قسم الناس إلى ﴿شقي وسعيد﴾؟","answer":"لخّص المصير النهائي بعد انقضاء زمن العمل: فريق بلغ الشقاء وفريق نال السعادة، ثم فصل حال كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص713–720، هود: 105.","url":""}]},{"id":"s11-174","number":174,"surah":11,"verses":[106],"verseLabel":"هود: 106","question":"لماذا وصف أهل النار بأن لهم فيها ﴿زفير وشهيق﴾؟","answer":"استعار أصوات التنفس الشديد لتجسيد الكرب المتواصل؛ فالزفير والشهيق يحولان الألم إلى صوت يكاد يسمعه القارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص721–728، هود: 106.","url":""}]},{"id":"s11-175","number":175,"surah":11,"verses":[107],"verseLabel":"هود: 107","question":"ما معنى الاستثناء في ﴿خالدين فيها... إلا ما شاء ربك﴾؟","answer":"يثبت أن الخلود نفسه واقع بمشيئة الله لا مستقلًا عنها، مع نفاذ حكمه في أهل النار؛ ولذلك ختم بـ﴿فعال لما يريد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص721–728، هود: 107.","url":""}]},{"id":"s11-176","number":176,"surah":11,"verses":[108],"verseLabel":"هود: 108","question":"لماذا ختم نعيم الجنة بقوله: ﴿عطاء غير مجذوذ﴾؟","answer":"﴿غير مجذوذ﴾ أي غير مقطوع؛ فجاءت العبارة لتزيل أي توهم يولده الاستثناء السابق في انقطاع نعيمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص729–734، هود: 108.","url":""}]},{"id":"s11-177","number":177,"surah":11,"verses":[109],"verseLabel":"هود: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تك في مرية مما يعبد هؤلاء﴾؟","answer":"ليس نهيًا عن الشك في وقوع عبادتهم، بل عن الارتياب في بطلانها ومصيرها؛ فهم يقلدون آباءهم وسينالون نصيبهم كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص735–752، هود: 109.","url":""}]},{"id":"s11-178","number":178,"surah":11,"verses":[109],"verseLabel":"هود: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿وإنا لموفوهم نصيبهم غير منقوص﴾؟","answer":"استعار النصيب لما استحقوه من الجزاء، وأكد عدم نقصه؛ فالإمهال لا يعني إسقاط شيء من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص735–752، هود: 109.","url":""}]},{"id":"s11-179","number":179,"surah":11,"verses":[110],"verseLabel":"هود: 110","question":"لماذا ذُكر اختلاف بني إسرائيل في كتاب موسى بعد قصص المكذبين؟","answer":"لتسلية النبي: الاختلاف في الوحي سنة قديمة، وتأخير الفصل بينهم ليس تصديقًا للباطل بل تنفيذ لكلمة سبقت إلى أجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص753–764، هود: 110.","url":""}]},{"id":"s11-180","number":180,"surah":11,"verses":[111],"verseLabel":"هود: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كلًا لما ليوفينهم ربك أعمالهم﴾ بهذا التوكيد المتراكم؟","answer":"كثرة أدوات التوكيد تزيل الشك في شمول الجزاء لكل مختلف، وأن أعمالهم محفوظة لا يغيب منها شيء عن الخبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص765–773، هود: 111.","url":""}]},{"id":"s11-181","number":181,"surah":11,"verses":[112],"verseLabel":"هود: 112","question":"لماذا كان الأمر ﴿فاستقم كما أمرت﴾ شديدًا حتى قيل إن سورة هود شيبت النبي؟","answer":"لأنه يطلب دوام الاستقامة على الحد الذي أمر الله به بلا ميل تحت ضغط التكذيب، ويشمل معه التائبين، ثم يمنع الطغيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص774–783، هود: 112.","url":""}]},{"id":"s11-182","number":182,"surah":11,"verses":[112],"verseLabel":"هود: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تطغوا﴾ بعد الأمر بالاستقامة؟","answer":"الاستقامة وسط بين التقصير ومجاوزة الحد؛ فحتى الحماسة للحق لا تبرر تعدي ما أمر الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص774–783، هود: 112.","url":""}]},{"id":"s11-183","number":183,"surah":11,"verses":[113],"verseLabel":"هود: 113","question":"لماذا نُهي المؤمنون عن مجرد الركون إلى الظالمين؟","answer":"لأن الميل اليسير إليهم يمد الظلم بالقبول ويضعف مقاومته؛ فإذا كان الركون موجبًا للوعيد فالاشتراك في ظلمهم أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص784–795، هود: 113.","url":""}]},{"id":"s11-184","number":184,"surah":11,"verses":[113],"verseLabel":"هود: 113","question":"ما سرّ التعبير في قوله تعالى: ﴿فتمسكم النار﴾؟","answer":"المس يوحي بأن أدنى اتصال بالنار كاف في التحذير، وهو مناسب للنهي عن أدنى ميل إلى الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص784–795، هود: 113.","url":""}]},{"id":"s11-185","number":185,"surah":11,"verses":[114],"verseLabel":"هود: 114","question":"لماذا عبر عن أوقات الصلاة بـ﴿طرفي النهار وزلفًا من الليل﴾؟","answer":"جمع طرفي النهار وساعات الليل القريبة ليحيط اليوم بمحطات ذكر متكررة، فتكون الصلاة مددًا للاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص796–نهاية الجزء، هود: 114.","url":""}]},{"id":"s11-186","number":186,"surah":11,"verses":[114],"verseLabel":"هود: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحسنات يذهبن السيئات﴾ بعد الأمر بالصلاة؟","answer":"لأن الطاعات، وفي مقدمتها الصلاة، تمحو آثار الصغائر وتقاوم مسار الذنب؛ فجاء الوعد علاجًا عمليًا بعد النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص796–نهاية الجزء، هود: 114.","url":""}]},{"id":"s11-187","number":187,"surah":11,"verses":[115],"verseLabel":"هود: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿واصبر فإن الله لا يضيع أجر المحسنين﴾؟","answer":"الصبر قد يبدو انتظارًا بلا ثمرة، فربطه بضمان الأجر، ووصف الصابرين بالمحسنين لأنهم يثبتون على الطاعة في الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص9–13، هود: 115.","url":""}]},{"id":"s11-188","number":188,"surah":11,"verses":[116],"verseLabel":"هود: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿فلولا كان من القرون من قبلكم أولو بقية ينهون عن الفساد﴾؟","answer":"﴿أولو بقية﴾ أصحاب فضل وعقل ودين باقٍ؛ والاستفهام التوبيخي يتحسر على ندرة الفئة التي تحفظ المجتمع بمقاومة الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص14–31، هود: 116.","url":""}]},{"id":"s11-189","number":189,"surah":11,"verses":[116],"verseLabel":"هود: 116","question":"لماذا استثنى ﴿قليلًا ممن أنجينا منهم﴾؟","answer":"لأن المقاومة الصادقة للفساد كانت نادرة، وهؤلاء القليل هم الذين استحقوا النجاة؛ فالقلة لا تنقص قيمة موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص14–31، هود: 116.","url":""}]},{"id":"s11-190","number":190,"surah":11,"verses":[116],"verseLabel":"هود: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبع الذين ظلموا ما أترفوا فيه﴾؟","answer":"جعل الترف متبوعًا يقودهم؛ فلم تعد النعمة في أيديهم، بل صاروا أسرى لها حتى تركوا الإصلاح وأجرموا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص14–31، هود: 116.","url":""}]},{"id":"s11-191","number":191,"surah":11,"verses":[117],"verseLabel":"هود: 117","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان ربك ليهلك القرى بظلم وأهلها مصلحون﴾؟","answer":"ينفي أن يهلكهم ظلمًا منه وهم قائمون بالإصلاح؛ فالهلاك العام لا يأتي مع حياة الإصلاح، وإنما حين يستحكم فساد الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص14–31، هود: 117.","url":""}]},{"id":"s11-192","number":192,"surah":11,"verses":[118],"verseLabel":"هود: 118","question":"لماذا لم يجعل الله الناس أمة واحدة مع قدرته؟","answer":"شاء أن يكون التكليف والابتلاء في مجال الاختيار، فتظهر الاستجابة والإعراض؛ ولو شاء قسرهم على طريق واحد لفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص32–62، هود: 118.","url":""}]},{"id":"s11-193","number":193,"surah":11,"verses":[118],"verseLabel":"هود: 118","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يزالون مختلفين﴾؟","answer":"يصور استمرار الاختلاف ما دام الاختيار والهوى، لا أنه غاية محمودة في ذاته؛ ثم استثنى من رحمهم الله بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص32–62، هود: 118.","url":""}]},{"id":"s11-194","number":194,"surah":11,"verses":[119],"verseLabel":"هود: 119","question":"ما معنى ﴿ولذلك خلقهم﴾: أخلقهم للاختلاف أم للرحمة؟","answer":"اختلف المفسرون في عود الإشارة؛ والمعنى الجامع أنهم خُلقوا للابتلاء الذي تظهر فيه الرحمة لمن اهتدى والاختلاف ممن أعرض، لا أن الله يحب الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص32–62، هود: 119.","url":""}]},{"id":"s11-195","number":195,"surah":11,"verses":[119],"verseLabel":"هود: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿وتمت كلمة ربك لأملأن جهنم من الجنة والناس أجمعين﴾؟","answer":"يقرر نفاذ الحكم فيمن اختار طريق الشقاء من الصنفين؛ فلا يعطل اختلافهم وعد الله ولا يخرجهم عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص32–62، هود: 119.","url":""}]},{"id":"s11-196","number":196,"surah":11,"verses":[120],"verseLabel":"هود: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وكلا نقص عليك من أنباء الرسل ما نثبت به فؤادك﴾؟","answer":"القصص لم تسق للاستمتاع التاريخي، بل كل خبر منها يمد القلب بدليل ثبات جديد أمام تكرر التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص63–82، هود: 120.","url":""}]},{"id":"s11-197","number":197,"surah":11,"verses":[120],"verseLabel":"هود: 120","question":"ما سرّ التعبير في قوله تعالى: ﴿وجاءك في هذه الحق وموعظة وذكرى للمؤمنين﴾؟","answer":"خص هذه السورة بما جمعته من حقائق القصص المطمئنة، وموعظة تزجر، وذكرى تجدد ما يعرفه المؤمن؛ فتنوع أثر الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص63–82، هود: 120.","url":""}]},{"id":"s11-198","number":198,"surah":11,"verses":[121],"verseLabel":"هود: 121","question":"ما سرّ توجيه الخطاب إلى المكذبين بقوله تعالى: ﴿اعملوا على مكانتكم إنا عاملون﴾؟","answer":"أمر تهديد لا إباحة: استمروا على طريقكم وسنستمر على الحق، وستكشف النهاية قيمة كل عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص83–96، هود: 121.","url":""}]},{"id":"s11-199","number":199,"surah":11,"verses":[122],"verseLabel":"هود: 122","question":"لماذا كرر الانتظار: ﴿وانتظروا إنا منتظرون﴾؟","answer":"قابل انتظارهم سقوط الدعوة بانتظار المؤمنين حكم الله؛ والتكرار يصور المواجهة ويثبت أن العاقبة ستفصل بين الانتظارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص83–96، هود: 122.","url":""}]},{"id":"s11-200","number":200,"surah":11,"verses":[123],"verseLabel":"هود: 123","question":"لماذا خُتمت السورة بقوله: ﴿ولله غيب السماوات والأرض وإليه يرجع الأمر كله﴾؟","answer":"بعد أخبار الغيب ووعد العاقبة رد العلم والتدبير كله إلى الله؛ فلا يملك أحد سر المستقبل ولا نتيجته سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص97–نهاية تفسير السورة، هود: 123.","url":""}]},{"id":"s11-201","number":201,"surah":11,"verses":[123],"verseLabel":"هود: 123","question":"لماذا جمع الختام بين ﴿فاعبده وتوكل عليه﴾؟","answer":"العبادة تبذل الجهد في الأمر، والتوكل يفوض النتيجة لله؛ فبهما تستقيم حركة الرسول بين العمل والثقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص97–نهاية تفسير السورة، هود: 123.","url":""}]},{"id":"s11-202","number":202,"surah":11,"verses":[123],"verseLabel":"هود: 123","question":"لماذا كانت آخر كلمة: ﴿وما ربك بغافل عما تعملون﴾؟","answer":"تختم بالرقابة الشاملة: لا يضيع عمل الداعية ولا يغيب ظلم المكذب، وفيها وعد ووعيد يلخصان مسار السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص97–نهاية تفسير السورة، هود: 123.","url":""}]},{"id":"s12-1","number":1,"surah":12,"verses":[1],"verseLabel":"يوسف: 1","question":"لماذا افتتحت سورة يوسف بالحروف ﴿الر﴾؟","answer":"تلفت السامع إلى أن هذا الكتاب المعجز مؤلف من الحروف التي يعرفها العرب، ومع ذلك عجزوا عن الإتيان بمثله؛ ثم جاء ذكر الكتاب المبين مناسبًا لهذا التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص129–136، يوسف: 1.","url":""}]},{"id":"s12-2","number":2,"surah":12,"verses":[1],"verseLabel":"يوسف: 1","question":"لماذا وصف القرآن هنا بأنه ﴿الكتاب المبين﴾؟","answer":"لأنه يبين الحق والهدى، وتتكشف في قصة يوسف دلائل الوحي والحكمة ببيان بالغ؛ كما أن ظهوره وإعجازه مبينان لصدق مصدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص129–136، يوسف: 1.","url":""}]},{"id":"s12-3","number":3,"surah":12,"verses":[2],"verseLabel":"يوسف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿إنا أنزلناه قرآنًا عربيًا﴾، دون أن يقال «كتابًا عربيًا»؟","answer":"اسم القرآن يبرز كونه مقروءًا متلوًا، والعربية هي الوعاء الذي يتحقق به فهم المخاطبين الأولين وتذوقهم لبيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص137–148، يوسف: 2.","url":""}]},{"id":"s12-4","number":4,"surah":12,"verses":[2],"verseLabel":"يوسف: 2","question":"لماذا عُلّل إنزال القرآن عربيًا بقوله: ﴿لعلكم تعقلون﴾؟","answer":"لأن وضوح اللسان يزيل عذر عدم الفهم، لكن الغاية ليست سماع الألفاظ وحدها بل عقل المعاني والاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص137–148، يوسف: 2.","url":""}]},{"id":"s12-5","number":5,"surah":12,"verses":[3],"verseLabel":"يوسف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿نحن نقص عليك أحسن القصص﴾؟","answer":"أضاف القصص إلى الله فدل على صدقه وحسن اختياره وترتيبه، ووصفه بالأحسن لما جمعته القصة من العبرة والجمال ووحدة البناء وحسن العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص149–170، يوسف: 3.","url":""}]},{"id":"s12-6","number":6,"surah":12,"verses":[3],"verseLabel":"يوسف: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿بما أوحينا إليك هذا القرآن﴾؟","answer":"يقرر أن معرفة النبي بهذه التفاصيل لم تأت من تعلم بشري، بل من الوحي؛ فالقصة نفسها برهان على النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص149–170، يوسف: 3.","url":""}]},{"id":"s12-7","number":7,"surah":12,"verses":[3],"verseLabel":"يوسف: 3","question":"لماذا وصف النبي قبل الوحي بأنه ﴿لمن الغافلين﴾ عن القصة؟","answer":"الغفلة هنا عدم العلم لا الذم؛ وذكرها يقوي الدليل، إذ جاءه خبر لم يكن يعرفه بهذه الصورة المحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص149–170، يوسف: 3.","url":""}]},{"id":"s12-8","number":8,"surah":12,"verses":[4],"verseLabel":"يوسف: 4","question":"ما سرّ التعبير في قول يوسف: ﴿إني رأيت أحد عشر كوكبًا والشمس والقمر﴾ ثم كرر: ﴿رأيتهم لي ساجدين﴾؟","answer":"أعاد فعل الرؤية عند الانتقال من رؤية الأجرام إلى رؤيتها في هيئة عاقلة ساجدة؛ فالتكرار يبرز المشهد الأعجب في الرؤيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص171–182، يوسف: 4.","url":""}]},{"id":"s12-9","number":9,"surah":12,"verses":[4],"verseLabel":"يوسف: 4","question":"لماذا استعمل ضمير العقلاء في ﴿رأيتهم﴾ للكواكب والشمس والقمر؟","answer":"لأنها ظهرت في الرؤيا ساجدة، والسجود فعل العقلاء؛ فشخّصها التعبير وجعلها مشهدًا حيًا ينبئ بأشخاص يسجدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص171–182، يوسف: 4.","url":""}]},{"id":"s12-10","number":10,"surah":12,"verses":[5],"verseLabel":"يوسف: 5","question":"لماذا بدأ يعقوب جوابه بـ﴿يا بني﴾؟","answer":"تصغير التحبيب يهيئ يوسف لقبول النصح ويكشف حنان الأب، خصوصًا أن الأمر يتضمن كتمان رؤيا عظيمة عن إخوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 5.","url":""}]},{"id":"s12-11","number":11,"surah":12,"verses":[5],"verseLabel":"يوسف: 5","question":"لماذا نهى يعقوب يوسف عن قص الرؤيا على إخوته؟","answer":"أدرك دلالتها على رفعة يوسف وخشي أن توقظ الغيرة الكامنة فيكيدوا له؛ فالكتمان هنا حكمة لحماية النعمة قبل نضجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 5.","url":""}]},{"id":"s12-12","number":12,"surah":12,"verses":[5],"verseLabel":"يوسف: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فيكيدوا لك كيدًا﴾، دون أن يقال «فيكيدوك»؟","answer":"اللام تشعر بأنهم يدبرون كيدًا مخصوصًا لأجله، والمفعول المطلق ﴿كيدًا﴾ يؤكد إحكام التدبير وخطورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 5.","url":""}]},{"id":"s12-13","number":13,"surah":12,"verses":[5],"verseLabel":"يوسف: 5","question":"لماذا نقل يعقوب التحذير من الإخوة إلى الشيطان؟","answer":"لم يقطع رابطة الأخوة باتهامهم وحدهم، بل كشف المحرك الذي يوقد الحسد؛ فالشيطان عدو ظاهر يسعى لإفساد الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 5.","url":""}]},{"id":"s12-14","number":14,"surah":12,"verses":[6],"verseLabel":"يوسف: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك يجتبيك ربك﴾ بعد الرؤيا مباشرة؟","answer":"ربط الرمز بمستقبله: هذا السجود علامة اصطفاء وتعليم وإتمام نعمة؛ فالمحنة الآتية جزء من طريق الاجتباء لا نقيض له.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 6.","url":""}]},{"id":"s12-15","number":15,"surah":12,"verses":[6],"verseLabel":"يوسف: 6","question":"ما المقصود بـ﴿تأويل الأحاديث﴾؟","answer":"معرفة مآلات الرؤى وما تؤول إليه الوقائع والكلمات؛ واللفظ أوسع من تفسير المنام، إذ ظهر علم يوسف في فهم الأحداث وتدبيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 6.","url":""}]},{"id":"s12-16","number":16,"surah":12,"verses":[6],"verseLabel":"يوسف: 6","question":"لماذا ذكر إتمام النعمة على يوسف وعلى آل يعقوب؟","answer":"لأن رفعة يوسف ستعود نجاةً واجتماعًا ورخاءً على أسرته كلها؛ فالنعمة الفردية في القصة ذات أثر جماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 6.","url":""}]},{"id":"s12-17","number":17,"surah":12,"verses":[7],"verseLabel":"يوسف: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد كان في يوسف وإخوته آيات للسائلين﴾ بالجمع؟","answer":"القصة ليست علامة واحدة؛ ففيها صدق الوحي، وعاقبة الصبر، وخطر الحسد، ولطف التدبير، وتحول المحنة إلى منحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 7.","url":""}]},{"id":"s12-18","number":18,"surah":12,"verses":[7],"verseLabel":"يوسف: 7","question":"لماذا خص ﴿السائلين﴾ بالانتفاع من الآيات؟","answer":"لأن من يسأل طالبًا للحق يفتح قلبه للعبرة، وقيل نزلت جوابًا لمن سأل النبي عن خبر يوسف؛ فوافق اللفظ سبب السؤال وعموم الباحثين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص183–221، يوسف: 7.","url":""}]},{"id":"s12-19","number":19,"surah":12,"verses":[8],"verseLabel":"يوسف: 8","question":"ما سرّ التعبير في قول الإخوة: ﴿ليوسف وأخوه أحب إلى أبينا منا﴾ ولم يسموا بنيامين؟","answer":"أضافوه إلى يوسف لأن وحدة الأم جعلته في نظرهم تابعًا له في المحبة والمنافسة، فكشف التعبير نظرتهم المنقسمة للأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص222–237، يوسف: 8.","url":""}]},{"id":"s12-20","number":20,"surah":12,"verses":[8],"verseLabel":"يوسف: 8","question":"لماذا احتجوا بأنهم ﴿عصبة﴾؟","answer":"جعلوا القوة والعدد معيار استحقاق المحبة؛ رأوا أنفسهم أنفع للأب، وغفلوا أن المحبة ليست صفقة تقاس بالكثرة والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص222–237، يوسف: 8.","url":""}]},{"id":"s12-21","number":21,"surah":12,"verses":[8],"verseLabel":"يوسف: 8","question":"ما وجه قولهم عن أبيهم: ﴿إن أبانا لفي ضلال مبين﴾؟","answer":"أرادوا خطأه في تقدير المحبة لا ضلال الدين، لكن العبارة تكشف كيف يدفع الحسد صاحبه إلى تضخيم الحكم على أقرب الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص222–237، يوسف: 8.","url":""}]},{"id":"s12-22","number":22,"surah":12,"verses":[9],"verseLabel":"يوسف: 9","question":"لماذا بدأ اقتراحهم بـ﴿اقتلوا يوسف أو اطرحوه أرضًا﴾؟","answer":"الحسد إذا استحكم يرى إزالة المنافس حلًا، وتنكير ﴿أرضًا﴾ يدل على أي مكان بعيد يقطع صلته بأبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص238–251، يوسف: 9.","url":""}]},{"id":"s12-23","number":23,"surah":12,"verses":[9],"verseLabel":"يوسف: 9","question":"ما وجه قولهم: ﴿يخل لكم وجه أبيكم﴾؟","answer":"صوّروا وجه الأب واهتمامه كمساحة مشغولة بيوسف، وتوهموا أن إزالته ستفرغها لهم؛ وهي صورة دقيقة لاستحواذ الغيرة على رؤيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص238–251، يوسف: 9.","url":""}]},{"id":"s12-24","number":24,"surah":12,"verses":[9],"verseLabel":"يوسف: 9","question":"كيف خططوا للجريمة ثم قالوا: ﴿وتكونوا من بعده قومًا صالحين﴾؟","answer":"سوّل لهم الهوى توبة مؤجلة بعد تحصيل الغرض؛ فجعلوا الصلاح غطاءً مستقبليًا لجريمة حاضرة، وهي من أخطر خدع النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص238–251، يوسف: 9.","url":""}]},{"id":"s12-25","number":25,"surah":12,"verses":[10],"verseLabel":"يوسف: 10","question":"ما سرّ التعبير في قول أحدهم: ﴿لا تقتلوا يوسف وألقوه في غيابت الجب﴾؟","answer":"خفف الجريمة من القتل المباشر إلى الإبعاد، لكنه لم يرفض أصل الظلم؛ والجب المظلم يحقق غرضهم مع احتمال التقاط القافلة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص252–265، يوسف: 10.","url":""}]},{"id":"s12-26","number":26,"surah":12,"verses":[10],"verseLabel":"يوسف: 10","question":"ما دلالة ﴿غيابت الجب﴾؟","answer":"الغيابة قعر مظلم يغيب فيه الشيء عن الأبصار؛ فالكلمة ترسم وحدة يوسف وخفاءه، كما تلائم مقصدهم في محو أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص252–265، يوسف: 10.","url":""}]},{"id":"s12-27","number":27,"surah":12,"verses":[10],"verseLabel":"يوسف: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿يلتقطه بعض السيارة﴾؟","answer":"الالتقاط أخذ الشيء من غير طلب سابق، و﴿السيارة﴾ رفقة المسافرين؛ فالتعبير يصور أن بعض القافلة يعثر عليه فيخرجه من الجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص252–265، يوسف: 10.","url":""}]},{"id":"s12-28","number":28,"surah":12,"verses":[11],"verseLabel":"يوسف: 11","question":"ما وجه قولهم: ﴿ما لك لا تأمنا على يوسف﴾؟","answer":"بدأوا باستنكار عدم الثقة قبل طلب إخراجه، ليجعلوا الأب في موقف المدافع ويزيلوا حاجزه النفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص266–285، يوسف: 11.","url":""}]},{"id":"s12-29","number":29,"surah":12,"verses":[11],"verseLabel":"يوسف: 11","question":"لماذا أكدوا: ﴿وإنا له لناصحون﴾؟","answer":"جمعوا إنَّ واللام وتقديم ﴿له﴾ لتغطية موضع الشك، وكثرة التوكيد نفسها تناسب كذبًا يحتاج إلى تدعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص266–285، يوسف: 11.","url":""}]},{"id":"s12-30","number":30,"surah":12,"verses":[12],"verseLabel":"يوسف: 12","question":"ما وجه قولهم: ﴿يرتع ويلعب﴾؟","answer":"اختاروا ما يلائم سنه ويستميل قلب الأب إلى الترفيه عنه، ثم ألحقوا ضمان الحفظ ليكتمل الإقناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص266–285، يوسف: 12.","url":""}]},{"id":"s12-31","number":31,"surah":12,"verses":[13],"verseLabel":"يوسف: 13","question":"ما سرّ تقديم يعقوب حزنه على خوف الذئب؟","answer":"فراق يوسف يؤلمه في ذاته، ثم ذكر الخطر الخارجي؛ فالأول باعث عاطفي دائم والثاني احتمال مخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص286–303، يوسف: 13.","url":""}]},{"id":"s12-32","number":32,"surah":12,"verses":[13],"verseLabel":"يوسف: 13","question":"لماذا خص الذئب بالذكر؟","answer":"لأنه خطر معروف في مراعيهم عند الغفلة، لكن ذكره منحهم من حيث لا يريد الحجة التي سيستعملونها لاحقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص286–303، يوسف: 13.","url":""}]},{"id":"s12-33","number":33,"surah":12,"verses":[14],"verseLabel":"يوسف: 14","question":"ما وجه قولهم: ﴿لئن أكله الذئب ونحن عصبة إنا إذا لخاسرون﴾؟","answer":"احتجوا بقوتهم مرة أخرى: وقوع الخطر مع كثرتهم يعني سقوط قيمتهم كلها؛ فكلامهم ألزمهم بالحفظ وأبطل عذرهم قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص298–303، يوسف: 14.","url":""}]},{"id":"s12-34","number":34,"surah":12,"verses":[15],"verseLabel":"يوسف: 15","question":"لماذا حُذف تفصيل ما فعلوه بين الذهاب والإلقاء في الجب؟","answer":"حُذف جواب ﴿فلما﴾ لدلالة السياق عليه، والتقدير أنهم فعلوا ما عزموا عليه وجعلوا يوسف في غيابة الجب؛ فالحذف إيجاز استُغني فيه عن تفصيل معلوم من السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص304–317، يوسف: 15.","url":""}]},{"id":"s12-35","number":35,"surah":12,"verses":[15],"verseLabel":"يوسف: 15","question":"لماذا أوحى الله إلى يوسف في قاع الجب: ﴿لتنبئنهم بأمرهم هذا﴾؟","answer":"جاء الوعد في أشد لحظة ضعف ليغرس يقين العاقبة: سيأتي يوم يكون هو المخبر وهم لا يعرفونه؛ فالوحي سبق النجاة المادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص304–317، يوسف: 15.","url":""}]},{"id":"s12-36","number":36,"surah":12,"verses":[15],"verseLabel":"يوسف: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم لا يشعرون﴾؟","answer":"تحتمل أنهم لا يشعرون بالوحي أو لا يعرفونه عند تحقق الوعد؛ وفي الحالين يظهر أن تدبير الله يجري خارج إدراكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص304–317، يوسف: 15.","url":""}]},{"id":"s12-37","number":37,"surah":12,"verses":[16],"verseLabel":"يوسف: 16","question":"لماذا جاءوا أباهم ﴿عشاء يبكون﴾؟","answer":"اختاروا ظلمة العشاء لتستر وجوههم وتخفف الفحص، واتخذوا البكاء دليلًا مصطنعًا على الصدق؛ ففضح السياق صناعة المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص304–336، يوسف: 16.","url":""}]},{"id":"s12-38","number":38,"surah":12,"verses":[17],"verseLabel":"يوسف: 17","question":"ما وجه قولهم: ﴿إنا ذهبنا نستبق وتركنا يوسف عند متاعنا﴾؟","answer":"نسجوا القصة من عناصر معقولة: منافسة تشغلهم، وصغير يبقى مع المتاع، ثم حادث مفاجئ؛ لكن اعترافهم بالترك يثبت تقصيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص318–336، يوسف: 17.","url":""}]},{"id":"s12-39","number":39,"surah":12,"verses":[17],"verseLabel":"يوسف: 17","question":"ما وجه قولهم: ﴿وما أنت بمؤمن لنا ولو كنا صادقين﴾؟","answer":"حاولوا تفسير عدم تصديقه مسبقًا بمحبة يوسف لا بضعف روايتهم، وعبارة ﴿ولو كنا صادقين﴾ زلة تكشف قلق الكاذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص318–336، يوسف: 17.","url":""}]},{"id":"s12-40","number":40,"surah":12,"verses":[18],"verseLabel":"يوسف: 18","question":"لماذا جاءوا على قميص يوسف ﴿بدم كذب﴾؟","answer":"وصف الدم نفسه بالكذب مبالغة، لأنه دليل مصنوع ينطق بخلاف الحقيقة؛ والقميص السليم فضح تناقض روايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص337–350، يوسف: 18.","url":""}]},{"id":"s12-41","number":41,"surah":12,"verses":[18],"verseLabel":"يوسف: 18","question":"ما سرّ التعبير في قول يعقوب: ﴿بل سولت لكم أنفسكم أمرًا﴾؟","answer":"لم يعرف التفصيل لكنه أدرك أن النفس زينت لهم فعلًا قبيحًا؛ فانتقل من دليل القميص إلى تشخيص الجذر الداخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص337–350، يوسف: 18.","url":""}]},{"id":"s12-42","number":42,"surah":12,"verses":[18],"verseLabel":"يوسف: 18","question":"ما سر قوله: ﴿فصبر جميل﴾؟","answer":"حذف المبتدأ أو الفعل ليجعل الصبر قراره المباشر، ووصفه بالجميل لأنه بلا جزع إلى الخلق ولا اعتراض على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص337–350، يوسف: 18.","url":""}]},{"id":"s12-43","number":43,"surah":12,"verses":[18],"verseLabel":"يوسف: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿والله المستعان على ما تصفون﴾؟","answer":"لم يقل «على فقد يوسف»؛ لأن البلاء يشمل كذبهم وما يرسمونه من رواية، فاستعان بالله على الحقيقة التي أخفوها وآثارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص337–350، يوسف: 18.","url":""}]},{"id":"s12-44","number":44,"surah":12,"verses":[19],"verseLabel":"يوسف: 19","question":"ما سرّ التعبير في قول الوارد: ﴿يا بشرى هذا غلام﴾؟","answer":"نادى البشرى، أو خاطب أصحابه بها، فرحًا بما وجد؛ فالتعبير يصور مفاجأة العثور على الغلام وشدة الاستبشار به.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص351–369، يوسف: 19.","url":""}]},{"id":"s12-45","number":45,"surah":12,"verses":[19],"verseLabel":"يوسف: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿وأسروه بضاعة﴾؟","answer":"أخفوا أمره وجعلوه في حكم البضاعة التي تُتجر؛ فجمع التعبير بين الكتمان واتخاذه متاعًا للبيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص351–369، يوسف: 19.","url":""}]},{"id":"s12-46","number":46,"surah":12,"verses":[19],"verseLabel":"يوسف: 19","question":"لماذا ختم بـ﴿والله عليم بما يعملون﴾؟","answer":"ما خفي عن القافلة والإخوة مكشوف لله، وعلمه هنا تمهيد لتدبير يحيط بأفعالهم ويحولها إلى طريق لتحقيق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص351–369، يوسف: 19.","url":""}]},{"id":"s12-47","number":47,"surah":12,"verses":[20],"verseLabel":"يوسف: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وشروه بثمن بخس دراهم معدودة﴾؟","answer":"تراكم الأوصاف يقلل القيمة: ثمن ناقص، ودراهم قليلة تُعد باليد؛ وهو يقابل رفعة من بيعوه بجهل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص370–378، يوسف: 20.","url":""}]},{"id":"s12-48","number":48,"surah":12,"verses":[20],"verseLabel":"يوسف: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وكانوا فيه من الزاهدين﴾؟","answer":"أرادوا التخلص منه أو لم يعرفوا قدره، فباعوه بلا مساومة تليق به؛ والزهد فيه يزيد مفارقة ما سيبلغه من مكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص370–378، يوسف: 20.","url":""}]},{"id":"s12-49","number":49,"surah":12,"verses":[21],"verseLabel":"يوسف: 21","question":"ما سرّ التعبير في قول عزيز مصر: ﴿أكرمي مثواه﴾؟","answer":"لم يقل أكرميه فقط؛ بل طلب حسن إقامته كلها، فكان البيت الكريم أول انتقال من ذل الرق إلى بيئة التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص379–401، يوسف: 21.","url":""}]},{"id":"s12-50","number":50,"surah":12,"verses":[21],"verseLabel":"يوسف: 21","question":"لماذا جمع العزيز بين احتمال النفع واتخاذه ولدًا؟","answer":"رأى فيه أمارات الخير، فتردد نفعه بين الخدمة والقرب الأسري؛ وكلاهما نقيض ما أراده إخوته من إبعاده وإهماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص379–401، يوسف: 21.","url":""}]},{"id":"s12-51","number":51,"surah":12,"verses":[21],"verseLabel":"يوسف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك مكنا ليوسف في الأرض﴾ وهو ما يزال مملوكًا؟","answer":"لأن دخول بيت العزيز بداية التمكين الخفي؛ فالتمكين لا يبدأ عند ظهور السلطة بل عند ترتيب أسبابها التي لا يراها الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص379–401، يوسف: 21.","url":""}]},{"id":"s12-52","number":52,"surah":12,"verses":[21],"verseLabel":"يوسف: 21","question":"لماذا ختم بـ﴿والله غالب على أمره ولكن أكثر الناس لا يعلمون﴾؟","answer":"يلخص منطق القصة: أراد الإخوة إبعاده فأوصلوه إلى مصر، وأراد البائعون رخصه فبدأ تمكينه؛ أمر الله يغلب مقاصدهم من حيث لا يعلمون.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص379–401، يوسف: 21.","url":""}]},{"id":"s12-53","number":53,"surah":12,"verses":[22],"verseLabel":"يوسف: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿ولما بلغ أشده آتيناه حكمًا وعلمًا﴾؟","answer":"لما اكتملت قوته الجسدية والنفسية آتاه الله نضج الحكم والعلم، ليستقبل فتنة القصر بالبصيرة لا بالقوة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص402–411، يوسف: 22.","url":""}]},{"id":"s12-54","number":54,"surah":12,"verses":[22],"verseLabel":"يوسف: 22","question":"لماذا ختم بـ﴿وكذلك نجزي المحسنين﴾؟","answer":"نقل عطاء يوسف من حالة خاصة إلى سنة عامة: الإحسان سبب لعطاء العلم والحكمة، فيفتح القصة لكل مقتدٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص402–411، يوسف: 22.","url":""}]},{"id":"s12-55","number":55,"surah":12,"verses":[23],"verseLabel":"يوسف: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وراودته التي هو في بيتها﴾ ولم يذكر اسمها؟","answer":"صلة الموصول تكشف عنصر الفتنة الأخطر: هو تحت سلطانها وفي بيتها، بينما إبهام الاسم يصرف النظر من الشخص إلى الموقف والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص412–433، يوسف: 23.","url":""}]},{"id":"s12-56","number":56,"surah":12,"verses":[23],"verseLabel":"يوسف: 23","question":"ما دلالة فعل ﴿راودته﴾؟","answer":"يدل على طلب متكرر بلطف وحيلة، لا خاطر عابر؛ فالكلمة تختصر إلحاحًا ومقاومة امتدت ولم تستجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص412–433، يوسف: 23.","url":""}]},{"id":"s12-57","number":57,"surah":12,"verses":[23],"verseLabel":"يوسف: 23","question":"ما سرّ التعبير في قولها: ﴿هيت لك﴾ بعد إغلاق الأبواب؟","answer":"عبارة دعوة صريحة جاءت بعد إحكام المكان، فبلغت الفتنة ذروتها؛ وقابلها يوسف فورًا بـ﴿معاذ الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص412–433، يوسف: 23.","url":""}]},{"id":"s12-58","number":58,"surah":12,"verses":[23],"verseLabel":"يوسف: 23","question":"لماذا كان أول جواب يوسف: ﴿معاذ الله﴾؟","answer":"لجأ إلى حماية الله قبل مجادلة المرأة أو الثقة بنفسه؛ فالعصمة تبدأ بالافتقار لا بادعاء القوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص412–433، يوسف: 23.","url":""}]},{"id":"s12-59","number":59,"surah":12,"verses":[23],"verseLabel":"يوسف: 23","question":"من المقصود بقوله: ﴿إنه ربي أحسن مثواي﴾؟","answer":"يحتمل سيده العزيز، فيكون وفاءً لمن أكرمه، ويحتمل الله وهو الأليق بأصل الاستعاذة؛ والمعنيان يجتمعان في قبح الخيانة وكفر الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص412–433، يوسف: 23.","url":""}]},{"id":"s12-60","number":60,"surah":12,"verses":[24],"verseLabel":"يوسف: 24","question":"كيف نفهم ﴿ولقد همت به وهم بها لولا أن رأى برهان ربه﴾ بما يصون مقام يوسف؟","answer":"همُّها عزم على الفاحشة، أما جوابه فمعلق بـ﴿لولا﴾؛ أي لولا رؤيته البرهان لوقع مقتضى الطبيعة، لكنه لم يقع لأن الله صرفه وثبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص434–452، يوسف: 24.","url":""}]},{"id":"s12-61","number":61,"surah":12,"verses":[24],"verseLabel":"يوسف: 24","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك لنصرف عنه السوء والفحشاء﴾؟","answer":"لم يقل صرفناه عنهما فقط، بل صرفهما عنه؛ فالعناية الإلهية أبعدت أسباب الشر من طريق العبد المخلص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص434–452، يوسف: 24.","url":""}]},{"id":"s12-62","number":62,"surah":12,"verses":[24],"verseLabel":"يوسف: 24","question":"لماذا وصف يوسف بأنه من ﴿عبادنا المخلصين﴾؟","answer":"الإخلاص سر نجاته من الفتنة؛ وعلى قراءة المخلَصين هو ممن اصطفاهم الله، وعلى المخلِصين هو صادق القصد، والمعنيان متلازمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص434–452، يوسف: 24.","url":""}]},{"id":"s12-63","number":63,"surah":12,"verses":[25],"verseLabel":"يوسف: 25","question":"ما سرّ التعبير في قوله تعالى: ﴿واستبقا الباب﴾؟","answer":"فعل واحد جمع مقصدين متضادين: يوسف يسابق إلى الهرب، وهي تسابق لمنعه؛ فاختصر حركة المشهد وصراعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص453–467، يوسف: 25.","url":""}]},{"id":"s12-64","number":64,"surah":12,"verses":[25],"verseLabel":"يوسف: 25","question":"لماذا كان تمزيق القميص ﴿من دبر﴾ حاسمًا؟","answer":"لأنه دليل مادي على أنه كان هاربًا وهي خلفه تمسكه؛ فتحول القميص من أثر اعتداء إلى شاهد براءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص453–467، يوسف: 25.","url":""}]},{"id":"s12-65","number":65,"surah":12,"verses":[25],"verseLabel":"يوسف: 25","question":"لماذا بدأت المرأة اتهامها بصيغة السؤال: ﴿ما جزاء من أراد بأهلك سوءًا﴾؟","answer":"سبقت يوسف إلى صياغة الجريمة والعقوبة معًا، واستعملت التعميم لتخفي نفسها في دور الضحية وتدفع العزيز إلى الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص453–467، يوسف: 25.","url":""}]},{"id":"s12-66","number":66,"surah":12,"verses":[26],"verseLabel":"يوسف: 26","question":"ما سرّ التعبير في قول يوسف باقتضاب: ﴿هي راودتني عن نفسي﴾؟","answer":"أجاب بالحقيقة الضرورية بلا إسهاب ولا تشهير؛ فلما اتهمته دفع التهمة وسمى الفاعل في جملة حاسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص468–476، يوسف: 26.","url":""}]},{"id":"s12-67","number":67,"surah":12,"verses":[26],"verseLabel":"يوسف: 26","question":"لماذا كان الشاهد ﴿من أهلها﴾؟","answer":"شهادة القريب أبعد عن تهمة الانحياز ليوسف وأقوى حجة على المرأة؛ فجاء البرهان من الجهة التي يُنتظر أن تدافع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص468–476، يوسف: 26.","url":""}]},{"id":"s12-68","number":68,"surah":12,"verses":[27,28],"verseLabel":"يوسف: 27–28","question":"لماذا علق الشاهد الحكم على جهة شق القميص؟","answer":"حوّل النزاع من دعويين متعارضتين إلى أثر محسوس: شقه من الأمام يدل على إقبال، ومن الخلف يدل على هرب؛ فالبينة ناطقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص468–485، يوسف: 27–28.","url":""}]},{"id":"s12-69","number":69,"surah":12,"verses":[28],"verseLabel":"يوسف: 28","question":"ما سرّ التعبير في قول العزيز: ﴿إنه من كيدكن إن كيدكن عظيم﴾؟","answer":"لما رأى الدليل انتقل من الواقعة إلى وصف طريقة التدبير الخفي التي قلبت البريء متهمًا؛ وعظم الكيد هنا لأثره في الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص477–485، يوسف: 28.","url":""}]},{"id":"s12-70","number":70,"surah":12,"verses":[29],"verseLabel":"يوسف: 29","question":"ما سرّ التعبير في قول العزيز: ﴿يوسف أعرض عن هذا﴾؟","answer":"أراد إغلاق الفضيحة وحفظ البيت، فطلب من يوسف الكتمان، ثم أمر المرأة بالاستغفار اعترافًا بخطئها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص486–492، يوسف: 29.","url":""}]},{"id":"s12-71","number":71,"surah":12,"verses":[29],"verseLabel":"يوسف: 29","question":"ما سرّ التعبير في قوله لها: ﴿إنك كنت من الخاطئين﴾ بصيغة المذكر الجمع؟","answer":"﴿الخاطئين﴾ جمع يغلب فيه التذكير ويشمل جنس المذنبين، فيضع فعلها ضمن خطأ أخلاقي عام لا خصوص النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص486–492، يوسف: 29.","url":""}]},{"id":"s12-72","number":72,"surah":12,"verses":[30],"verseLabel":"يوسف: 30","question":"ما سرّ التعبير في قول نسوة المدينة: ﴿تراود فتاها عن نفسه﴾ بالمضارع؟","answer":"استحضرن استمرار المراودة وتكررها، وجعلن الخبر حديثًا متجددًا؛ ولم يكن عتبهن بريئًا من الفضول والشماتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص493–504، يوسف: 30.","url":""}]},{"id":"s12-73","number":73,"surah":12,"verses":[30],"verseLabel":"يوسف: 30","question":"لماذا قلن: ﴿قد شغفها حبًا﴾؟","answer":"الشغاف غلاف القلب أو سويداؤه؛ فالصورة تجعل الحب قد نفذ إلى أعماقها واستولى عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص493–504، يوسف: 30.","url":""}]},{"id":"s12-74","number":74,"surah":12,"verses":[31],"verseLabel":"يوسف: 31","question":"لماذا أعدت لكل واحدة متكأً وسكينًا قبل إخراج يوسف؟","answer":"رتبت تجربة تجعل النسوة يحكمن بأنفسهن: راحة وطعام يحتاج إلى قطع، ثم ظهور مفاجئ يصرف وعيهن عن أيديهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص505–524، يوسف: 31.","url":""}]},{"id":"s12-75","number":75,"surah":12,"verses":[31],"verseLabel":"يوسف: 31","question":"ما سرّ التعبير في قوله تعالى: ﴿فلما رأينه أكبرنه وقطعن أيديهن﴾؟","answer":"جاءت الفاء لتصور فورية الدهشة، والمبالغة في تقطيع الأيدي تكشف غياب الإحساس أمام جمال لم يتوقعنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص505–524، يوسف: 31.","url":""}]},{"id":"s12-76","number":76,"surah":12,"verses":[31],"verseLabel":"يوسف: 31","question":"لماذا قلن: ﴿ما هذا بشرًا إن هذا إلا ملك كريم﴾؟","answer":"لم يجدن في معيارهن البشري جمالًا يفسر المشهد، فنفين عنه البشرية على سبيل المبالغة وشبهنه بملك متخيل الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص505–524، يوسف: 31.","url":""}]},{"id":"s12-77","number":77,"surah":12,"verses":[32],"verseLabel":"يوسف: 32","question":"لماذا انتقلت امرأة العزيز من الخفاء إلى قولها: ﴿ولئن لم يفعل ما آمره ليسجنن﴾؟","answer":"لما انكشف سرها تحول الحياء إلى تحدٍّ واستعانت بالسلطة بعد فشل الإغراء؛ فظهرت فتنة القهر بعد فتنة الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص525–538، يوسف: 32.","url":""}]},{"id":"s12-78","number":78,"surah":12,"verses":[32],"verseLabel":"يوسف: 32","question":"ما سرّ التعبير في قولها: ﴿وليكونًا من الصاغرين﴾؟","answer":"لم ترد سجنه فقط بل إذلاله لكسر مقاومته؛ والنون الخفيفة بعد الثقيلة توافق توكيد التهديد مع اختلاف إيقاع الفاصلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص525–538، يوسف: 32.","url":""}]},{"id":"s12-79","number":79,"surah":12,"verses":[33],"verseLabel":"يوسف: 33","question":"ما سرّ التعبير في قول يوسف: ﴿السجن أحب إلي مما يدعونني إليه﴾؟","answer":"ليست محبة السجن لذاته، بل تفضيل ألم الجسد المؤقت على معصية القلب؛ فالمفاضلة تكشف ترتيب القيم عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص539–551، يوسف: 33.","url":""}]},{"id":"s12-80","number":80,"surah":12,"verses":[33],"verseLabel":"يوسف: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿وإلا تصرف عني كيدهن أصب إليهن﴾؟","answer":"مع طهارته لم يعتمد على نفسه، بل اعترف بضعف الطبيعة البشرية وطلب الصرف الإلهي؛ وهذا أبلغ في صدق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص539–551، يوسف: 33.","url":""}]},{"id":"s12-81","number":81,"surah":12,"verses":[34],"verseLabel":"يوسف: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿فاستجاب له ربه فصرف عنه كيدهن﴾؟","answer":"استجاب الله دعاءه فصرف عنه كيدهن، أي أبعد عنه أثر الإغراء وحماه من الميل إليهن؛ أما السجن فجاء بعد ذلك بقرار القوم، وليس هو عين الاستجابة المذكورة في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص552–558، يوسف: 34.","url":""}]},{"id":"s12-82","number":82,"surah":12,"verses":[34],"verseLabel":"يوسف: 34","question":"لماذا ختم بـ﴿إنه هو السميع العليم﴾؟","answer":"سمع دعاء يوسف الخفي وعلم صدق قلبه وخطر الكيد المحيط به، فجاء الاسمان مطابقين للحاجة والاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص552–558، يوسف: 34.","url":""}]},{"id":"s12-83","number":83,"surah":12,"verses":[35],"verseLabel":"يوسف: 35","question":"لماذا سجنوه ﴿من بعد ما رأوا الآيات﴾؟","answer":"لم يكن السجن لخفاء البراءة، بل لحماية السمعة وتهدئة الحديث؛ فالجملة تدين حكمًا سياسيًا خالف الأدلة التي رآها أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص559–566، يوسف: 35.","url":""}]},{"id":"s12-84","number":84,"surah":12,"verses":[35],"verseLabel":"يوسف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿ليسجننه حتى حين﴾ دون تحديد؟","answer":"لأن غرضهم إبعاد القضية إلى أن تخمد، لا تنفيذ عقوبة ثابتة؛ فناسبه زمن مجهول يخضع لمصلحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص559–566، يوسف: 35.","url":""}]},{"id":"s12-85","number":85,"surah":12,"verses":[36],"verseLabel":"يوسف: 36","question":"ما سرّ التعبير في قول أحد الفتيين: ﴿إني أراني أعصر خمرًا﴾ مع أنه يعصر عنبًا؟","answer":"سمّى الشيء بما سيؤول إليه؛ فالرؤيا تعرض النتيجة في مقدماتها، وهذا من المجاز باعتبار المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص567–578، يوسف: 36.","url":""}]},{"id":"s12-86","number":86,"surah":12,"verses":[36],"verseLabel":"يوسف: 36","question":"ما سرّ التعبير في قولهما ليوسف: ﴿إنا نراك من المحسنين﴾ قبل طلب التأويل؟","answer":"رأيا إحسانه في السجن فوثقا بعلمه وصدقه؛ فالخلق الحسن كان مدخلًا لقبول كلمته قبل ظهور معجزته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص567–578، يوسف: 36.","url":""}]},{"id":"s12-87","number":87,"surah":12,"verses":[37],"verseLabel":"يوسف: 37","question":"لماذا أخّر يوسف جواب الرؤيا وبدأ بالتوحيد؟","answer":"استثمر حاجتهما إلى علمه ليبلغهما أصل النجاة، لكنه طمأنهما أولًا أنه سيجيبهما قبل مجيء الطعام؛ فجمع الدعوة وحسن التعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص579–595، يوسف: 37.","url":""}]},{"id":"s12-88","number":88,"surah":12,"verses":[37],"verseLabel":"يوسف: 37","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلكما مما علمني ربي﴾؟","answer":"نسب العلم إلى الله فلم يتخذ إعجاب السائلين فرصة لتعظيم نفسه؛ وبهذا جعل موهبته دليلًا على ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص579–595، يوسف: 37.","url":""}]},{"id":"s12-89","number":89,"surah":12,"verses":[38],"verseLabel":"يوسف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبعت ملة آبائي إبراهيم وإسحاق ويعقوب﴾؟","answer":"أثبت أن توحيده امتداد لرسالة راسخة لا فكرة نشأت في السجن، وجمع نسب النبوة مع شكر فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص596–615، يوسف: 38.","url":""}]},{"id":"s12-90","number":90,"surah":12,"verses":[38],"verseLabel":"يوسف: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان لنا أن نشرك بالله من شيء﴾؟","answer":"﴿من شيء﴾ تستغرق كل شريك وكل صورة من الشرك، و﴿ما كان لنا﴾ تفيد أن الشرك لا يليق بمن عرف الله وفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص596–615، يوسف: 38.","url":""}]},{"id":"s12-91","number":91,"surah":12,"verses":[39],"verseLabel":"يوسف: 39","question":"ما سرّ التعبير في قوله تعالى: ﴿يا صاحبي السجن﴾؟","answer":"نسبهما إلى مكان الصحبة ليقربهما ويؤنسهما، ولم يخاطبهما كمجرمين؛ فتهيأت النفس لسؤال التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص616–624، يوسف: 39.","url":""}]},{"id":"s12-92","number":92,"surah":12,"verses":[39],"verseLabel":"يوسف: 39","question":"لماذا سأل: ﴿أأرباب متفرقون خير أم الله الواحد القهار﴾؟","answer":"وضع التعدد المتنازع في كفة، والوحدة والقدرة في كفة؛ والسؤال يحمل العقل إلى الجواب بداهةً دون إكراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص616–624، يوسف: 39.","url":""}]},{"id":"s12-93","number":93,"surah":12,"verses":[40],"verseLabel":"يوسف: 40","question":"لماذا وصف المعبودات بأنها ﴿أسماء سميتموها﴾؟","answer":"نزع عنها كل حقيقة وسلطان؛ لم يبق من ألوهيتها إلا أسماء اخترعها البشر وورثوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص625–642، يوسف: 40.","url":""}]},{"id":"s12-94","number":94,"surah":12,"verses":[40],"verseLabel":"يوسف: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحكم إلا لله﴾ بعد نفي سلطان الأصنام؟","answer":"لأن حق التشريع والعبادة فرع عن الملك والعلم، وهما لله وحده؛ فحصر الحكم يكمل حصر العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص625–642، يوسف: 40.","url":""}]},{"id":"s12-95","number":95,"surah":12,"verses":[40],"verseLabel":"يوسف: 40","question":"لماذا وصف التوحيد بأنه ﴿الدين القيم﴾؟","answer":"لأنه مستقيم في دليله، مقيم لحياة الإنسان، لا اعوجاج فيه كتعدد الآلهة؛ لكن أكثر الناس لا يدركون هذه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص625–642، يوسف: 40.","url":""}]},{"id":"s12-96","number":96,"surah":12,"verses":[41],"verseLabel":"يوسف: 41","question":"لماذا عاد إلى ندائهما: ﴿يا صاحبي السجن﴾ عند التأويل؟","answer":"بعد الاستطراد الدعوي أعاد رابط الصحبة لينقل إلى الجواب الشخصي برفق، حتى مع قسوة مصير أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص643–656، يوسف: 41.","url":""}]},{"id":"s12-97","number":97,"surah":12,"verses":[41],"verseLabel":"يوسف: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿قضي الأمر الذي فيه تستفتيان﴾؟","answer":"التأويل وحي محقق لا ظن قابل للتغيير؛ فجاء الماضي ﴿قضي﴾ ليصور النتيجة كأنها انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص643–656، يوسف: 41.","url":""}]},{"id":"s12-98","number":98,"surah":12,"verses":[42],"verseLabel":"يوسف: 42","question":"ما سرّ التعبير في قوله للناجي: ﴿اذكرني عند ربك﴾؟","answer":"طلب سببًا مشروعًا لرفع الظلم بذكر حاله عند الملك، ولم يكن ذلك منافيًا للتوكل؛ فالأنبياء يأخذون بالأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص657–667، يوسف: 42.","url":""}]},{"id":"s12-99","number":99,"surah":12,"verses":[42],"verseLabel":"يوسف: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنساه الشيطان ذكر ربه﴾، ومن الذي أنساه؟","answer":"يحتمل أن الشيطان أنسى الناجي ذكر يوسف عند سيده، وهو الأظهر، ويحتمل أن الضمير ليوسف في قول؛ والنتيجة امتداد مكثه في السجن لحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص657–667، يوسف: 42.","url":""}]},{"id":"s12-100","number":100,"surah":12,"verses":[43],"verseLabel":"يوسف: 43","question":"لماذا تكررت السبعات في رؤيا الملك؟","answer":"سبع بقرات وسبع سنابل تمثل سبع سنوات رخاء تقابلها سبع شداد، فالتكرار العددي هو مفتاح الخطة الاقتصادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص668–681، يوسف: 43.","url":""}]},{"id":"s12-101","number":101,"surah":12,"verses":[43],"verseLabel":"يوسف: 43","question":"ما سرّ التعبير في قول الملك: ﴿أفتوني في رؤياي إن كنتم للرؤيا تعبرون﴾؟","answer":"لم يطلب حدسًا، بل فتوى من أهل الاختصاص، وشرط ﴿إن كنتم﴾ يختبر قدرتهم أمام رؤيا أقلقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص668–681، يوسف: 43.","url":""}]},{"id":"s12-102","number":102,"surah":12,"verses":[44],"verseLabel":"يوسف: 44","question":"لماذا وصف الملأ الرؤيا بأنها ﴿أضغاث أحلام﴾ بالجمع؟","answer":"الأضغاث أخلاط الرؤى الملتبسة التي لا ينتظم لها تأويل؛ وجاء ﴿أحلام﴾ بالجمع موافقًا لمعنى الأخلاط وتعدد ما توهموه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص682–697، يوسف: 44.","url":""}]},{"id":"s12-103","number":103,"surah":12,"verses":[44],"verseLabel":"يوسف: 44","question":"ما وجه قولهم: ﴿وما نحن بتأويل الأحلام بعالمين﴾؟","answer":"نفوا علمهم بهذا النوع المختلط لا مطلق التعبير، حفظًا لمكانتهم؛ لكن اعترافهم مهّد لظهور علم يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص682–697، يوسف: 44.","url":""}]},{"id":"s12-104","number":104,"surah":12,"verses":[45],"verseLabel":"يوسف: 45","question":"ما سرّ التعبير في وصف الناجي بقوله تعالى: ﴿وادكر بعد أمة﴾؟","answer":"تذكر يوسف بعد مدة طويلة؛ والكلمة تصور غياب الذكر وسط زمن ممتد ثم عودته فجأة عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص698–707، يوسف: 45.","url":""}]},{"id":"s12-105","number":105,"surah":12,"verses":[45],"verseLabel":"يوسف: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿أنا أنبئكم بتأويله فأرسلون﴾؟","answer":"نسب الإنباء إلى نفسه لأنه سيتولى الوصول إلى مصدره، ثم طلب الإرسال؛ فانتقل من عجز الملأ إلى باب الحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص698–707، يوسف: 45.","url":""}]},{"id":"s12-106","number":106,"surah":12,"verses":[46],"verseLabel":"يوسف: 46","question":"لماذا خاطب يوسف بـ﴿أيها الصديق﴾؟","answer":"خاطبه بالوصف الذي عرفه به من صدق القول والتأويل وحسن السيرة في السجن؛ فـ﴿الصديق﴾ صيغة مبالغة في الصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص708–718، يوسف: 46.","url":""}]},{"id":"s12-107","number":107,"surah":12,"verses":[46],"verseLabel":"يوسف: 46","question":"لماذا كرر صفة البقرات والسنابل بالتفصيل؟","answer":"نقل الرؤيا بأمانة حتى لا يضيع عنصر من رموزها، ولتكون الإجابة مطابقة للواقع ومقنعة للملك والناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص708–718، يوسف: 46.","url":""}]},{"id":"s12-108","number":108,"surah":12,"verses":[47],"verseLabel":"يوسف: 47","question":"لماذا تجاوز يوسف تفسير الرؤيا إلى خطة: ﴿تزرعون سبع سنين دأبًا﴾؟","answer":"لم يقتصر على تأويل الرؤيا، بل ضم إليه إرشادهم إلى ما يفعلونه في سنوات الخصب؛ فدلهم على الزراعة المتتابعة وحفظ أكثر الحصاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص719–726، يوسف: 47.","url":""}]},{"id":"s12-109","number":109,"surah":12,"verses":[47],"verseLabel":"يوسف: 47","question":"لماذا أمرهم بترك الحب في سنبله؟","answer":"لأنه أحفظ له من التلف، وليأكلوا قدرًا قليلًا فقط؛ فاختار التعبير تفصيلًا عمليًا لا وعظًا عامًا بالاقتصاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص719–726، يوسف: 47.","url":""}]},{"id":"s12-110","number":110,"surah":12,"verses":[48],"verseLabel":"يوسف: 48","question":"لماذا وصف السنوات بـ﴿سبع شداد﴾؟","answer":"نقل الشدة من الناس إلى السنين نفسها، كأن الزمن كله اشتد عليهم؛ وهي صورة لشمول القحط وطوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص727–734، يوسف: 48.","url":""}]},{"id":"s12-111","number":111,"surah":12,"verses":[48],"verseLabel":"يوسف: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿يأكلن ما قدمتم لهن﴾ عن السنين؟","answer":"شخص سنوات القحط ككائنات جائعة تلتهم المخزون؛ فالصورة توقظ الخوف وتدفع إلى الادخار المنظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص727–734، يوسف: 48.","url":""}]},{"id":"s12-112","number":112,"surah":12,"verses":[49],"verseLabel":"يوسف: 49","question":"ما سرّ التعبير بعد الشدة بقوله تعالى: ﴿ثم يأتي من بعد ذلك عام فيه يغاث الناس وفيه يعصرون﴾؟","answer":"أضاف سنة الفرج التي لم تكن ظاهرة في رموز السبع والسبع، فكانت وحيًا وبشارة؛ يتنزل الغيث وتعود الثمار والعصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص735–739، يوسف: 49.","url":""}]},{"id":"s12-113","number":113,"surah":12,"verses":[50],"verseLabel":"يوسف: 50","question":"لماذا رفض يوسف الخروج فورًا وقال: ﴿ارجع إلى ربك فاسأله ما بال النسوة﴾؟","answer":"أراد براءة علنية قبل الحرية، حتى لا يخرج بعفو يوهم بقاء التهمة؛ فقدم صفاء السمعة على عجلة الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص740–752، يوسف: 50.","url":""}]},{"id":"s12-114","number":114,"surah":12,"verses":[50],"verseLabel":"يوسف: 50","question":"لماذا سأل عن النسوة ولم يذكر امرأة العزيز؟","answer":"تلطفًا وسترًا، ولأن شهادة النسوة تكفي لكشف أصل القضية، كما أنهن شهود مستقلات على المراودة والتهديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص740–752، يوسف: 50.","url":""}]},{"id":"s12-115","number":115,"surah":12,"verses":[50],"verseLabel":"يوسف: 50","question":"لماذا ختم بقوله: ﴿إن ربي بكيدهن عليم﴾؟","answer":"فوض كشف التفاصيل إلى علم الله، فلم يشهر بهن، وأظهر أن ثقته بالبراءة قائمة على علم لا يضيع معه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص740–752، يوسف: 50.","url":""}]},{"id":"s12-116","number":116,"surah":12,"verses":[51],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول الملك: ﴿ما خطبكن إذ راودتن يوسف﴾ فنسب المراودة إليهن جميعًا؟","answer":"لأنهن شاركن في الضغط عليه أو علمن بالقضية، فجمعهن التحقيق ليظهر الأمر من كل أطرافه لا من صاحبة البيت وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص753–769، يوسف: 51.","url":""}]},{"id":"s12-117","number":117,"surah":12,"verses":[51],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول النسوة: ﴿حاش لله ما علمنا عليه من سوء﴾؟","answer":"نزهن الله أن يقع ما اتهم به يوسف، ونفين حتى علمهن بأدنى سوء؛ فكانت شهادة جماعية صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص753–769، يوسف: 51.","url":""}]},{"id":"s12-118","number":118,"surah":12,"verses":[51],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول امرأة العزيز: ﴿الآن حصحص الحق﴾؟","answer":"حصحص أي ظهر وتمكن بعد خفاء؛ و﴿الآن﴾ تعلن انتهاء زمن المواربة أمام تحقيق أعاد القضية من جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص753–769، يوسف: 51.","url":""}]},{"id":"s12-119","number":119,"surah":12,"verses":[51],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قولها: ﴿أنا راودته عن نفسه وإنه لمن الصادقين﴾؟","answer":"جمعت اعترافًا بفعلها وشهادة بصدقه، فهدمت الاتهام من مصدره وأتمت البراءة التي طلبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص753–769، يوسف: 51.","url":""}]},{"id":"s12-120","number":120,"surah":12,"verses":[52],"verseLabel":"يوسف: 52","question":"من القائل: ﴿ذلك ليعلم أني لم أخنه بالغيب﴾، ولماذا اختلف فيه؟","answer":"يحتمل أنه يوسف يبين أن طلب التحقيق لإثبات أمانته للعزيز، ويحتمل أنها امرأة العزيز تواصل اعترافها؛ وسياق كل قول له وجه معتبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص770–794، يوسف: 52.","url":""}]},{"id":"s12-121","number":121,"surah":12,"verses":[52],"verseLabel":"يوسف: 52","question":"ما سرّ التعبير في قوله تعالى: ﴿وأن الله لا يهدي كيد الخائنين﴾؟","answer":"لا يوصله إلى غايته المحمودة؛ فقد طال الكيد لكنه انتهى إلى ظهور البراءة ورفعة من أريد إسقاطه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص770–794، يوسف: 52.","url":""}]},{"id":"s12-122","number":122,"surah":12,"verses":[53],"verseLabel":"يوسف: 53","question":"ما سرّ التعبير بقوله تعالى: ﴿إن النفس لأمارة بالسوء إلا ما رحم ربي﴾؟","answer":"النفس بطبعها تكثر الأمر بالسوء إذا تركت لهواها، ولا نجاة بقوة الإنسان وحدها بل برحمة الله وتزكيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص770–794، يوسف: 53.","url":""}]},{"id":"s12-123","number":123,"surah":12,"verses":[53],"verseLabel":"يوسف: 53","question":"لماذا ختم بـ﴿إن ربي غفور رحيم﴾ بعد ذكر أمارة النفس؟","answer":"حتى لا يتحول تشخيص ضعف النفس إلى يأس؛ فالمغفرة تمحو والرحمة تعين على الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص770–794، يوسف: 53.","url":""}]},{"id":"s12-124","number":124,"surah":12,"verses":[54],"verseLabel":"يوسف: 54","question":"ما سرّ التعبير في قول الملك أولًا: ﴿ائتوني به﴾ ثم قال بعد كلامه: ﴿إنك اليوم لدينا مكين أمين﴾؟","answer":"طلبه أولًا إعجابًا بعلمه وبراءته، فلما كلمه اختبر شخصيته فزاده قربًا وثقة؛ انتقل من الاستدعاء إلى التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص770–794، يوسف: 54.","url":""}]},{"id":"s12-125","number":125,"surah":12,"verses":[54],"verseLabel":"يوسف: 54","question":"لماذا جمع الملك ليوسف بين ﴿مكين﴾ و﴿أمين﴾؟","answer":"المكانة تمنحه القدرة على التنفيذ، والأمانة تضمن سلامة استعمالها؛ فلا يصلح للولاية قادر بلا أمانة ولا أمين بلا تمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص770–794، يوسف: 54.","url":""}]},{"id":"s12-126","number":126,"surah":12,"verses":[55],"verseLabel":"يوسف: 55","question":"لماذا طلب يوسف: ﴿اجعلني على خزائن الأرض﴾؟","answer":"رأى أزمة قادمة وعلم قدرته على إدارتها، فطلب الولاية للمصلحة العامة لا لمجرد الجاه؛ ويجوز للخبير أن يعرف بكفايته عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص795–نهاية الجزء، يوسف: 55.","url":""}]},{"id":"s12-127","number":127,"surah":12,"verses":[55],"verseLabel":"يوسف: 55","question":"ما سرّ التعبير في قوله تعالى: ﴿إني حفيظ عليم﴾؟","answer":"الحفظ أمانة الموارد، والعلم حسن التدبير؛ فجمع الصفتين اللتين تحتاجهما خزائن دولة تستقبل مجاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص795–نهاية الجزء، يوسف: 55.","url":""}]},{"id":"s12-128","number":128,"surah":12,"verses":[56],"verseLabel":"يوسف: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك مكنا ليوسف في الأرض يتبوأ منها حيث يشاء﴾؟","answer":"يشير ﴿وكذلك﴾ إلى التمكين الذي دبره الله ليوسف، و﴿يتبوأ منها حيث يشاء﴾ تدل على سعة التصرف والاستقرار في أرض مصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص9–20، يوسف: 56.","url":""}]},{"id":"s12-129","number":129,"surah":12,"verses":[56],"verseLabel":"يوسف: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿نصيب برحمتنا من نشاء ولا نضيع أجر المحسنين﴾؟","answer":"التمكين رحمة يختص الله بها، لكنه لم يأت عبثًا؛ إحسان يوسف محفوظ، فجمع الفضل الإلهي والجزاء على العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص9–20، يوسف: 56.","url":""}]},{"id":"s12-130","number":130,"surah":12,"verses":[57],"verseLabel":"يوسف: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿ولأجر الآخرة خير للذين آمنوا وكانوا يتقون﴾ بعد تمكين يوسف؟","answer":"حتى لا تنتهي القصة عند نجاح دنيوي؛ فما عند الله خير وأبقى، والتمكين لا يعوض عن أجر الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص9–20، يوسف: 57.","url":""}]},{"id":"s12-131","number":131,"surah":12,"verses":[58],"verseLabel":"يوسف: 58","question":"لماذا عرف يوسف إخوته وهم له منكرون؟","answer":"هو فارقهم صغيرًا ثم تغيرت هيئته ومكانته ولباسه، أما هم فجاؤوا بصورتهم المعهودة؛ والمفارقة تحقق وعد ﴿وهم لا يشعرون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص21–40، يوسف: 58.","url":""}]},{"id":"s12-132","number":132,"surah":12,"verses":[59],"verseLabel":"يوسف: 59","question":"ما سرّ التعبير في قول يوسف: ﴿ائتوني بأخ لكم من أبيكم﴾؟","answer":"طلب إحضار أخيهم من أبيهم من غير أن يكشف لهم معرفته بهم، وجعل مجيئه شرطًا لاستمرار الكيل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص41–70، يوسف: 59.","url":""}]},{"id":"s12-133","number":133,"surah":12,"verses":[59],"verseLabel":"يوسف: 59","question":"لماذا احتج بقوله: ﴿ألا ترون أني أوفي الكيل وأنا خير المنزلين﴾؟","answer":"جمع الترغيب المادي وحسن الضيافة ليطمئنوا إلى العودة، ثم أتبع ذلك بالتهديد إن لم يأتوا بأخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص41–70، يوسف: 59.","url":""}]},{"id":"s12-134","number":134,"surah":12,"verses":[60],"verseLabel":"يوسف: 60","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا كيل لكم عندي ولا تقربون﴾؟","answer":"لم يهدد بنقص الكيل بل بمنعه كله، وزاد منع القرب؛ ليجعل إحضار الأخ شرطًا لا يمكن التحايل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص41–70، يوسف: 60.","url":""}]},{"id":"s12-135","number":135,"surah":12,"verses":[61],"verseLabel":"يوسف: 61","question":"ما وجه قولهم: ﴿سنراود عنه أباه﴾؟","answer":"يعلمون شدة تعلق يعقوب به، فاستعملوا فعل المراودة الدال على التلطف والتكرار؛ وهو اللفظ نفسه الذي صور إلحاح امرأة العزيز.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص41–70، يوسف: 61.","url":""}]},{"id":"s12-136","number":136,"surah":12,"verses":[62],"verseLabel":"يوسف: 62","question":"لماذا أمر يوسف فتيانه أن يجعلوا بضاعتهم في رحالهم؟","answer":"ليعرفوها عند الرجوع فيدركوا كرمه أو يتحرجوا فيعودوا لردها، وبذلك يضمن رجوعهم مع أخيهم من غير أن يطلب منهم صراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 62.","url":""}]},{"id":"s12-137","number":137,"surah":12,"verses":[63],"verseLabel":"يوسف: 63","question":"لماذا بدأوا أباهم بقولهم: ﴿منع منا الكيل﴾؟","answer":"قدموا الخطر العملي الذي يمس الأسرة كلها قبل طلب إرسال أخيهم، ليكون الإذن ضرورة لا رغبة شخصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 63.","url":""}]},{"id":"s12-138","number":138,"surah":12,"verses":[63],"verseLabel":"يوسف: 63","question":"لماذا أكدوا مرة أخرى: ﴿وإنا له لحافظون﴾؟","answer":"كرروا الضمان نفسه الذي قالوه في يوسف، فاستدعى كلامهم ذاكرة الجرح القديم بدل أن يطمئن الأب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 63.","url":""}]},{"id":"s12-139","number":139,"surah":12,"verses":[64],"verseLabel":"يوسف: 64","question":"ما سرّ التعبير في قول يعقوب: ﴿هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل﴾؟","answer":"واجه التكرار بذاكرة التجربة: الضمان البشري فشل من قبل، ولذلك نقل الحفظ إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 64.","url":""}]},{"id":"s12-140","number":140,"surah":12,"verses":[64],"verseLabel":"يوسف: 64","question":"ما سرّ التعبير في قوله تعالى: ﴿فالله خير حافظًا وهو أرحم الراحمين﴾؟","answer":"لم يرفض الأسباب، لكنه صحح الاعتماد: حفظ الله خير من حفظهم، ورحمته أوسع من خوف الأب وفقده.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 64.","url":""}]},{"id":"s12-141","number":141,"surah":12,"verses":[65],"verseLabel":"يوسف: 65","question":"لماذا فرحوا برد بضاعتهم وقالوا: ﴿ما نبغي﴾؟","answer":"أي ماذا نطلب أكثر من هذا الإكرام؟ فقد عاد الطعام والثمن معًا، فصار الرجوع إلى العزيز أجدر بالثقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 65.","url":""}]},{"id":"s12-142","number":142,"surah":12,"verses":[65],"verseLabel":"يوسف: 65","question":"ما وجه قولهم: ﴿ونزداد كيل بعير ذلك كيل يسير﴾؟","answer":"صوروا الفائدة المحددة من إرسال أخيهم، وقللوا الأمر على أبيهم: زيادة حمل بعير سهلة عند العزيز.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71–100، يوسف: 65.","url":""}]},{"id":"s12-143","number":143,"surah":12,"verses":[66],"verseLabel":"يوسف: 66","question":"لماذا طلب يعقوب ﴿موثقًا من الله﴾؟","answer":"لم يكتف بوعد عاطفي، بل ألزمهم عهدًا يستحضر رقابة الله، إلا إذا أحاط بهم عجز لا يملكون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص101–130، يوسف: 66.","url":""}]},{"id":"s12-144","number":144,"surah":12,"verses":[66],"verseLabel":"يوسف: 66","question":"ما سرّ تعقيب توثقهم بقوله: ﴿الله على ما نقول وكيل﴾؟","answer":"جعل الله شاهدًا وحافظًا للعهد، فانتقل الكلام من اتفاق أسري إلى مسؤولية دينية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص101–130، يوسف: 66.","url":""}]},{"id":"s12-145","number":145,"surah":12,"verses":[67],"verseLabel":"يوسف: 67","question":"لماذا أمرهم بالدخول من أبواب متفرقة؟","answer":"خشي عليهم العين أو لفت الأنظار وهم جماعة ذوو هيئة، فأخذ بسبب الحذر مع إقراره أن السبب لا يرد قدر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص101–130، يوسف: 67.","url":""}]},{"id":"s12-146","number":146,"surah":12,"verses":[67],"verseLabel":"يوسف: 67","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أغني عنكم من الله من شيء﴾ بعد النصيحة؟","answer":"حتى لا يظنوا أن الخطة تضمن السلامة؛ النصيحة سبب، والحكم لله وحده، وعليه يكون التوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص101–130، يوسف: 67.","url":""}]},{"id":"s12-147","number":147,"surah":12,"verses":[68],"verseLabel":"يوسف: 68","question":"ما سرّ التعبير في قوله تعالى: ﴿إلا حاجة في نفس يعقوب قضاها﴾؟","answer":"لم يغير الدخول المتفرق قدرًا مقدرًا، لكنه حقق حاجة الأب في الاحتياط؛ فالأخذ بالأسباب له قيمته ولو لم يستقل بالنتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص101–130، يوسف: 68.","url":""}]},{"id":"s12-148","number":148,"surah":12,"verses":[69],"verseLabel":"يوسف: 69","question":"ما سرّ التعبير في قول يوسف لأخيه: ﴿إني أنا أخوك فلا تبتئس بما كانوا يعملون﴾؟","answer":"عرّفه بنفسه في خلوة ليبدد غربته ويهيئه للتدبير الآتي، ونهاه عن الحزن من أذى الإخوة الماضي والحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص131–160، يوسف: 69.","url":""}]},{"id":"s12-149","number":149,"surah":12,"verses":[70],"verseLabel":"يوسف: 70","question":"لماذا وضع يوسف السقاية في رحل أخيه؟","answer":"كانت وسيلة مشروعة في شريعتهم لاستبقائه ضمن تدبير علّمه الله، من غير ظلم نهائي له؛ وقد كان أخوه عالمًا بالأمر على قول.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص131–160، يوسف: 70.","url":""}]},{"id":"s12-150","number":150,"surah":12,"verses":[70],"verseLabel":"يوسف: 70","question":"لماذا نادى المنادي: ﴿أيتها العير إنكم لسارقون﴾؟","answer":"نسب الحكم إلى ظاهر فقد الصواع ووجوده في رحلهم، أو قصد سرقة يوسف القديمة على توجيه؛ والنص لا ينسب النداء مباشرة إلى يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص131–160، يوسف: 70.","url":""}]},{"id":"s12-151","number":151,"surah":12,"verses":[71],"verseLabel":"يوسف: 71","question":"لماذا أقبل الإخوة يسألون: ﴿ماذا تفقدون﴾؟","answer":"الثقة ببراءتهم جعلتهم يعودون إلى المنادي بدل الفرار، وسؤالهم عن المفقود سبق معرفتهم بالتهمة المحددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص161–193، يوسف: 71.","url":""}]},{"id":"s12-152","number":152,"surah":12,"verses":[72],"verseLabel":"يوسف: 72","question":"لماذا جعلوا لمن يأتي بالصواع ﴿حمل بعير﴾ وقال المنادي: ﴿وأنا به زعيم﴾؟","answer":"جمعوا المكافأة والضمان لتحريك البحث؛ والزعيم هنا الكفيل، فصار الإعلان ملزمًا لا وعدًا مجهولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص161–193، يوسف: 72.","url":""}]},{"id":"s12-153","number":153,"surah":12,"verses":[73],"verseLabel":"يوسف: 73","question":"لماذا أقسموا: ﴿لقد علمتم ما جئنا لنفسد في الأرض وما كنا سارقين﴾؟","answer":"احتجوا بما عرفه رجال يوسف من حسن معاملتهم وردهم أو انتظام دخولهم، ونفوا عن أنفسهم أصل الإفساد ثم السرقة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص194–202، يوسف: 73.","url":""}]},{"id":"s12-154","number":154,"surah":12,"verses":[74,75],"verseLabel":"يوسف: 74–75","question":"لماذا سألهم رجال يوسف عن جزاء السارق بدل تطبيق قانون مصر؟","answer":"ليحكموا هم بشريعتهم أن من وجد المتاع في رحله يُسترق، فيتحقق بقاء بنيامين من غير فرض حكم غريب عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص203–220، يوسف: 74–75.","url":""}]},{"id":"s12-155","number":155,"surah":12,"verses":[76],"verseLabel":"يوسف: 76","question":"لماذا بدأ يوسف بأوعيتهم قبل وعاء أخيه؟","answer":"بدأ بأوعيتهم قبل وعاء أخيه حتى يجري التفتيش على صورة طبيعية، ولا يظهر أنه يعرف موضع السقاية أو أن الأمر مدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص221–235، يوسف: 76.","url":""}]},{"id":"s12-156","number":156,"surah":12,"verses":[76],"verseLabel":"يوسف: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿كذلك كدنا ليوسف﴾؟","answer":"نسب التدبير إلى الله لأنه أراه الطريق الذي يحقق المقصد المشروع؛ والكيد هنا تدبير خفي يقابل تدبير الإخوة القديم ويقلب نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص221–235، يوسف: 76.","url":""}]},{"id":"s12-157","number":157,"surah":12,"verses":[76],"verseLabel":"يوسف: 76","question":"ما سرّ التعبير في قوله تعالى: ﴿ما كان ليأخذ أخاه في دين الملك إلا أن يشاء الله﴾؟","answer":"قانون الملك لا يجيز استبقاء السارق بهذه الصورة، فجعل الله الإخوة ينطقون بالحكم الذي يسمح ليوسف بأخذ أخيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص221–235، يوسف: 76.","url":""}]},{"id":"s12-158","number":158,"surah":12,"verses":[76],"verseLabel":"يوسف: 76","question":"لماذا ختم بـ﴿وفوق كل ذي علم عليم﴾؟","answer":"علم يوسف فوق علم إخوته في التدبير، لكن فوق كل عالم من هو أعلم منه حتى ينتهي العلم الكامل إلى الله؛ فلا مجال للاغترار.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص221–235، يوسف: 76.","url":""}]},{"id":"s12-159","number":159,"surah":12,"verses":[77],"verseLabel":"يوسف: 77","question":"ما وجه قولهم: ﴿إن يسرق فقد سرق أخ له من قبل﴾؟","answer":"دفعوا العار عن أنفسهم بإلصاقه بيوسف وأخيه، فعاد الحسد القديم في لحظة الأزمة بدل التضامن.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص236–247، يوسف: 77.","url":""}]},{"id":"s12-160","number":160,"surah":12,"verses":[77],"verseLabel":"يوسف: 77","question":"لماذا أسر يوسف كلمتهم في نفسه ولم يبدها؟","answer":"ملك غضبه وحفظ غرضه ولم يكشف هويته، فكان الصبر هنا ضبطًا للكلمة مع قدرته على الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص236–247، يوسف: 77.","url":""}]},{"id":"s12-161","number":161,"surah":12,"verses":[77],"verseLabel":"يوسف: 77","question":"ما سرّ التعبير في قوله تعالى في نفسه: ﴿أنتم شر مكانًا والله أعلم بما تصفون﴾؟","answer":"رد التهمة إلى حقيقتهم دون أن يدخل في جدال؛ شرهم ثابت بما صنعوا، والله أعلم بكذب الوصف الذي ألصقوه بيوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص236–247، يوسف: 77.","url":""}]},{"id":"s12-162","number":162,"surah":12,"verses":[78],"verseLabel":"يوسف: 78","question":"لماذا نادوه بـ﴿يا أيها العزيز﴾ عند طلب الاستبدال؟","answer":"استمالوه بلقبه ومكانته، ثم شرحوا ضعف الأب، لعل الرحمة تحمل صاحب السلطة على قبول واحد منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص248–255، يوسف: 78.","url":""}]},{"id":"s12-163","number":163,"surah":12,"verses":[78],"verseLabel":"يوسف: 78","question":"ما وجه قولهم: ﴿إنا نراك من المحسنين﴾ كما قال صاحبا السجن؟","answer":"الإحسان صار سمة يراها كل من يخالطه في الضعف والقوة؛ وهم يرجون أن يمتد إحسانه إلى أبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص248–255، يوسف: 78.","url":""}]},{"id":"s12-164","number":164,"surah":12,"verses":[79],"verseLabel":"يوسف: 79","question":"ما سرّ التعبير في قول يوسف: ﴿معاذ الله أن نأخذ إلا من وجدنا متاعنا عنده﴾؟","answer":"صاغ الرد بمبدأ العدل الظاهر دون كشف الخطة؛ أخذ بريء بدل من وُجد المتاع عنده ظلم لا يليق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص256–264، يوسف: 79.","url":""}]},{"id":"s12-165","number":165,"surah":12,"verses":[80],"verseLabel":"يوسف: 80","question":"لماذا خلص الإخوة ﴿نجيًا﴾؟","answer":"انفردوا يتناجون سرًا بعيدًا عن الناس لعظم المأزق؛ والمفرد ﴿نجيًا﴾ يصورهم كأنهم كتلة واحدة في الهمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 80.","url":""}]},{"id":"s12-166","number":166,"surah":12,"verses":[80],"verseLabel":"يوسف: 80","question":"ما سرّ التعبير في قول كبيرهم: ﴿ومن قبل ما فرطتم في يوسف﴾؟","answer":"أعاد الجرح الأول ليفهموا أن الأزمة الجديدة امتداد لتقصير لم يتوبوا من أثره كاملًا؛ فلم تعد العودة بلا أخ أمرًا بسيطًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 80.","url":""}]},{"id":"s12-167","number":167,"surah":12,"verses":[80],"verseLabel":"يوسف: 80","question":"لماذا قرر كبيرهم البقاء في مصر؟","answer":"وفاءً بالموثق وعجزًا عن مواجهة الأب بتكرار الفقد؛ ينتظر إذن يعقوب أو حكم الله، وهو خير الحاكمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 80.","url":""}]},{"id":"s12-168","number":168,"surah":12,"verses":[81],"verseLabel":"يوسف: 81","question":"ما سرّ التعبير في قوله لهم: ﴿ارجعوا إلى أبيكم﴾ ولم يقل «أبينا»؟","answer":"وجّه الخطاب إليهم فقال ﴿أبيكم﴾؛ لأنه يأمرهم هم بالرجوع إلى أبيهم وإبلاغه ما وقع، ولا يدل التعبير على نفي بنوته هو ليعقوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 81.","url":""}]},{"id":"s12-169","number":169,"surah":12,"verses":[81],"verseLabel":"يوسف: 81","question":"ما وجه قولهم: ﴿وما شهدنا إلا بما علمنا وما كنا للغيب حافظين﴾؟","answer":"لم يشهدوا إلا بما علموه من ظهور السقاية في رحله والحكم المبني على ذلك؛ أما حقيقة الغيب وما وراء الظاهر فلا يملكون حفظه أو العلم به.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 81.","url":""}]},{"id":"s12-170","number":170,"surah":12,"verses":[82],"verseLabel":"يوسف: 82","question":"ما وجه قولهم: ﴿واسأل القرية التي كنا فيها والعير التي أقبلنا فيها﴾؟","answer":"بالغوا في طلب التحقق من أهل مصر والقافلة كلها، حتى كأن القرية والعير نفسيهما تشهدان؛ فالحقيقة هذه المرة علنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 82.","url":""}]},{"id":"s12-171","number":171,"surah":12,"verses":[83],"verseLabel":"يوسف: 83","question":"لماذا كرر يعقوب قوله: ﴿بل سولت لكم أنفسكم أمرًا فصبر جميل﴾؟","answer":"تشابهت صورة الفقد عنده، فاستعاد العبارة القديمة، لكن رجاءه اتسع الآن: ﴿عسى الله أن يأتيني بهم جميعًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 83.","url":""}]},{"id":"s12-172","number":172,"surah":12,"verses":[83],"verseLabel":"يوسف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيني بهم جميعًا﴾ مع أن الخبر عن بنيامين؟","answer":"شمل يوسف وبنيامين وأخاهم الكبير الباقي في مصر؛ فاليقين بلطف الله رأى اجتماع المفقودين قبل ظهور سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص265–296، يوسف: 83.","url":""}]},{"id":"s12-173","number":173,"surah":12,"verses":[84],"verseLabel":"يوسف: 84","question":"لماذا تولى يعقوب عنهم وقال: ﴿يا أسفى على يوسف﴾ عند فقد بنيامين؟","answer":"الفقد الجديد أيقظ الحزن الأول الأعمق؛ فذكر يوسف لأنه أصل سلسلة الأحزان، لكنه أعرض عن لومهم إلى مناجاة ألمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص297–317، يوسف: 84.","url":""}]},{"id":"s12-174","number":174,"surah":12,"verses":[84],"verseLabel":"يوسف: 84","question":"لماذا ابيضت عيناه من الحزن وهو كظيم؟","answer":"بيّن ابيضاض العينين أثر الحزن الشديد في جسده، و﴿كظيم﴾ تدل على أنه ممتلئ حزنًا ممسك له، لا يبث شكواه للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص297–317، يوسف: 84.","url":""}]},{"id":"s12-175","number":175,"surah":12,"verses":[85],"verseLabel":"يوسف: 85","question":"ما وجه قولهم: ﴿تالله تفتأ تذكر يوسف حتى تكون حرضًا أو تكون من الهالكين﴾؟","answer":"استنكروا استمرار الذكر وخافوا أن يذيبه المرض أو يهلكه؛ لكنهم أخطؤوا فهم رجائه، فحزنه لم يكن يأسًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص318–326، يوسف: 85.","url":""}]},{"id":"s12-176","number":176,"surah":12,"verses":[86],"verseLabel":"يوسف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿إنما أشكو بثي وحزني إلى الله﴾؟","answer":"حصر شكواه في الله؛ والبث حزن لا يستطيع صاحبه كتمانه، أما الصبر الجميل فلا يمنع إظهار الافتقار للخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص327–336، يوسف: 86.","url":""}]},{"id":"s12-177","number":177,"surah":12,"verses":[86],"verseLabel":"يوسف: 86","question":"ما سرّ التعبير في قوله تعالى: ﴿وأعلم من الله ما لا تعلمون﴾؟","answer":"لديه من حسن الظن بوعد الله ورؤيا يوسف ومعرفته بلطفه ما يمنعه من اليأس، وإن خفي طريق الفرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص327–336، يوسف: 86.","url":""}]},{"id":"s12-178","number":178,"surah":12,"verses":[87],"verseLabel":"يوسف: 87","question":"لماذا أمرهم بالتحسس من يوسف وأخيه؟","answer":"التحسس طلب الخبر بالحواس والبحث العملي؛ فاليقين لا يعني الانتظار السلبي، بل يحرك إلى استعمال الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص337–348، يوسف: 87.","url":""}]},{"id":"s12-179","number":179,"surah":12,"verses":[87],"verseLabel":"يوسف: 87","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تيأسوا من روح الله﴾؟","answer":"روح الله فرجه ورحمته التي تحيي القلب بعد الاختناق؛ واليأس منها سوء معرفة بسعة قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص337–348، يوسف: 87.","url":""}]},{"id":"s12-180","number":180,"surah":12,"verses":[88],"verseLabel":"يوسف: 88","question":"ما وجه قولهم: ﴿مسنا وأهلنا الضر وجئنا ببضاعة مزجاة﴾؟","answer":"انتقلوا من خطاب الندية إلى إعلان الضعف: الضر شامل، والبضاعة قليلة رديئة؛ فتهيأ مقام الاسترحام.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص349–456، يوسف: 88.","url":""}]},{"id":"s12-181","number":181,"surah":12,"verses":[88],"verseLabel":"يوسف: 88","question":"لماذا طلبوا: ﴿فأوف لنا الكيل وتصدق علينا﴾؟","answer":"طلبوا إتمام الكيل مع رداءة بضاعتهم وقلتها، وجعلوا ما يتجاوز مقابلها من الإحسان صدقة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص349–456، يوسف: 88.","url":""}]},{"id":"s12-182","number":182,"surah":12,"verses":[89],"verseLabel":"يوسف: 89","question":"لماذا كشف يوسف نفسه بسؤال: ﴿هل علمتم ما فعلتم بيوسف وأخيه إذ أنتم جاهلون﴾؟","answer":"لم يبدأ بالتعريف، بل أيقظ ضمائرهم بالفعل القديم، وخفف عنهم بوصف الجهل تمهيدًا للتوبة لا للتشفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص349–456، يوسف: 89.","url":""}]},{"id":"s12-183","number":183,"surah":12,"verses":[90],"verseLabel":"يوسف: 90","question":"ما وجه قولهم: ﴿أإنك لأنت يوسف﴾؟","answer":"تراكم الاستفهام والتوكيد يصور صدمة التعرف: العزيز الذي يقفون أمامه هو الغلام الذي ألقوه في الجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص457–464، يوسف: 90.","url":""}]},{"id":"s12-184","number":184,"surah":12,"verses":[90],"verseLabel":"يوسف: 90","question":"ما سرّ التعبير في قول يوسف: ﴿أنا يوسف وهذا أخي﴾؟","answer":"عرّف بنفسه صراحة وأشار إلى أخيه، مستعيدًا رابطة الأخوة بدل هوية العزيز؛ فالمقام مقام اجتماع لا استعراض سلطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص457–464، يوسف: 90.","url":""}]},{"id":"s12-185","number":185,"surah":12,"verses":[90],"verseLabel":"يوسف: 90","question":"لماذا لخّص طريقه بقوله: ﴿من يتق ويصبر فإن الله لا يضيع أجر المحسنين﴾؟","answer":"لم ينسب النجاح إلى ذكائه أو منصبه، بل إلى التقوى والصبر والإحسان؛ وحول تجربته إلى قاعدة لكل قارئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص457–464، يوسف: 90.","url":""}]},{"id":"s12-186","number":186,"surah":12,"verses":[91],"verseLabel":"يوسف: 91","question":"ما وجه قولهم: ﴿لقد آثرك الله علينا وإن كنا لخاطئين﴾؟","answer":"اعترفوا بفضل الله عليه وبخطئهم هم، فاجتمع سقوط المقارنة الحاسدة وصدق التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 91.","url":""}]},{"id":"s12-187","number":187,"surah":12,"verses":[92],"verseLabel":"يوسف: 92","question":"ما سرّ التعبير في قول يوسف: ﴿لا تثريب عليكم اليوم﴾؟","answer":"نفى اللوم المؤذي في لحظة قدرته، وقيد بـ﴿اليوم﴾ إعلانًا فوريًا لإغلاق صفحة الانتقام، ثم دعا لهم بالمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 92.","url":""}]},{"id":"s12-188","number":188,"surah":12,"verses":[92],"verseLabel":"يوسف: 92","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر الله لكم وهو أرحم الراحمين﴾؟","answer":"عفوه البشري لا يغني عن مغفرة الله، فرفعهم من مواجهة أخيهم إلى الرجوع لربهم، ورجا لهم أوسع الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 92.","url":""}]},{"id":"s12-189","number":189,"surah":12,"verses":[93],"verseLabel":"يوسف: 93","question":"لماذا جعل يوسف قميصه وسيلة لعودة بصر أبيه؟","answer":"القميص الذي استعمل قديمًا دليل كذب صار الآن حامل البشرى والشفاء؛ فحوّل الله رمز الحزن إلى علامة الفرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 93.","url":""}]},{"id":"s12-190","number":190,"surah":12,"verses":[94],"verseLabel":"يوسف: 94","question":"ما سرّ التعبير في قول يعقوب قبل وصول البشير: ﴿إني لأجد ريح يوسف﴾؟","answer":"وجد ريح يوسف قبل وصول البشير على بُعد، وهو إدراك أكرمه الله به؛ ولذلك استبعد الحاضرون قوله وظنوه من تعلقه القديم بيوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 94.","url":""}]},{"id":"s12-191","number":191,"surah":12,"verses":[95],"verseLabel":"يوسف: 95","question":"ما وجه قولهم: ﴿إنك لفي ضلالك القديم﴾؟","answer":"ظنوا استمرار تعلقه بيوسف خطأً قديمًا، ولم يعلموا أن ما يسمونه ضلالًا كان يقينًا صادقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 95.","url":""}]},{"id":"s12-192","number":192,"surah":12,"verses":[96],"verseLabel":"يوسف: 96","question":"ما سرّ التعبير في قوله بعد رجوع بصره: ﴿ألم أقل لكم إني أعلم من الله ما لا تعلمون﴾؟","answer":"لم يشمت، بل ذكّرهم بأساس رجائه الذي أنكروه؛ فتحقق العلم الذي حمله على البحث وعدم اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 96.","url":""}]},{"id":"s12-193","number":193,"surah":12,"verses":[97],"verseLabel":"يوسف: 97","question":"لماذا طلب الأبناء من أبيهم أن يستغفر لهم؟","answer":"اعترفوا أن ظلمهم أصاب أباهم كما أصاب يوسف، فطلبوا دعاءه ومغفرته بعد إقرارهم بالخطيئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 97.","url":""}]},{"id":"s12-194","number":194,"surah":12,"verses":[98],"verseLabel":"يوسف: 98","question":"ما سرّ التعبير في قول يعقوب: ﴿سوف أستغفر لكم ربي﴾ ولم يستغفر فورًا؟","answer":"قيل أخره إلى وقت إجابة كالسحر، وقيل ليختبر صدق توبتهم؛ و﴿سوف﴾ وعد لا رفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 98.","url":""}]},{"id":"s12-195","number":195,"surah":12,"verses":[99],"verseLabel":"يوسف: 99","question":"لماذا آوى يوسف أبويه إليه قبل قوله: ﴿ادخلوا مصر﴾؟","answer":"بدأ بالاحتضان الأسري الخاص بعد طول الفراق، ثم انتقل إلى التكريم العام والأمن في مصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 99.","url":""}]},{"id":"s12-196","number":196,"surah":12,"verses":[99],"verseLabel":"يوسف: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿إن شاء الله آمنين﴾ وهو صاحب سلطة؟","answer":"علق الأمن بمشيئة الله اعترافًا بأن سلطانه سبب لا ضمان مستقل، وتعليمًا ألا يغتر الممكَّن بقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 99.","url":""}]},{"id":"s12-197","number":197,"surah":12,"verses":[100],"verseLabel":"يوسف: 100","question":"لماذا رفع أبويه على العرش؟","answer":"أكمل إكرامهما بعد الاستقبال، فجعل أقرب الناس إليه في موضع المكانة، ولم تنسه السلطة حق الوالدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 100.","url":""}]},{"id":"s12-198","number":198,"surah":12,"verses":[100],"verseLabel":"يوسف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿وخروا له سجدًا﴾، وهل كان سجود عبادة؟","answer":"كان سجود تحية وتعظيم جائزًا في شريعتهم، لا عبادة ليوسف؛ وبه تحقق رمز الرؤيا القديمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 100.","url":""}]},{"id":"s12-199","number":199,"surah":12,"verses":[100],"verseLabel":"يوسف: 100","question":"ما سرّ التعبير في قول يوسف: ﴿هذا تأويل رؤياي من قبل قد جعلها ربي حقًا﴾؟","answer":"لم يقل «صدقت رؤياي» فقط، بل نسب تحقيقها إلى ربه بعد سنين من الأسباب المتشابكة؛ فالحق ظهر في المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 100.","url":""}]},{"id":"s12-200","number":200,"surah":12,"verses":[100],"verseLabel":"يوسف: 100","question":"لماذا ذكر نعمة الخروج من السجن ولم يذكر الخروج من الجب؟","answer":"سترًا لإخوته في مقام الصفح والاجتماع، ولأن السجن أقرب النعم إلى التمكين؛ فلم يجدّد ذكر جريمتهم بعد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 100.","url":""}]},{"id":"s12-201","number":201,"surah":12,"verses":[100],"verseLabel":"يوسف: 100","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد أن نزغ الشيطان بيني وبين إخوتي﴾؟","answer":"نسب الإفساد إلى نزغ الشيطان، وقال ﴿بيني وبين﴾ بلطف يوزع صورة النزاع ولا يواجههم بالتجريم؛ هذا من كمال عفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 100.","url":""}]},{"id":"s12-202","number":202,"surah":12,"verses":[100],"verseLabel":"يوسف: 100","question":"لماذا وصف ربه بأنه ﴿لطيف لما يشاء﴾؟","answer":"لأن مشيئته تحققت عبر أسباب خفية بدت شرًا: الجب والبيع والسجن والمجاعة، ثم تكشفت كلها طريقًا للاجتماع والتمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص465–502، يوسف: 100.","url":""}]},{"id":"s12-203","number":203,"surah":12,"verses":[101],"verseLabel":"يوسف: 101","question":"لماذا دعا يوسف بعد الملك والعلم: ﴿توفني مسلمًا وألحقني بالصالحين﴾؟","answer":"لم يجعل قمة النجاح في الملك، بل في الثبات على الإسلام وحسن الخاتمة والصحبة بالصالحين؛ فالمآل أغلى من الإنجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص503–509، يوسف: 101.","url":""}]},{"id":"s12-204","number":204,"surah":12,"verses":[101],"verseLabel":"يوسف: 101","question":"ما سرّ التعبير في قوله تعالى: ﴿فاطر السماوات والأرض أنت وليي في الدنيا والآخرة﴾؟","answer":"استدل بالخلق الأعظم على ولاية ربه له في كل أطوار حياته، وحصر الولي الحقيقي في الله بعد زوال كل أسباب البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص503–509، يوسف: 101.","url":""}]},{"id":"s12-205","number":205,"surah":12,"verses":[102],"verseLabel":"يوسف: 102","question":"لماذا عاد الخطاب للنبي: ﴿ذلك من أنباء الغيب نوحيه إليك﴾؟","answer":"بعد اكتمال القصة استخرج دليل الوحي: لم يشهد النبي مؤامرة الإخوة، ومع ذلك جاءه خبرها المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص503–509، يوسف: 102.","url":""}]},{"id":"s12-206","number":206,"surah":12,"verses":[102],"verseLabel":"يوسف: 102","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يمكرون﴾ بعد ﴿أجمعوا أمرهم﴾؟","answer":"الأول يبين اتفاقهم على الخطة، والثاني يكشف طبيعتها الخفية المؤذية؛ فالنبي لم يحضر اجتماعهم ولا سرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص503–509، يوسف: 102.","url":""}]},{"id":"s12-207","number":207,"surah":12,"verses":[103],"verseLabel":"يوسف: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿وما أكثر الناس ولو حرصت بمؤمنين﴾؟","answer":"يواسي النبي بأن وضوح القصة وحرصه لا يجبران القلوب؛ البلاغ عليه والهداية بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص510–581، يوسف: 103.","url":""}]},{"id":"s12-208","number":208,"surah":12,"verses":[104],"verseLabel":"يوسف: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وما تسألهم عليه من أجر﴾؟","answer":"انتفاء المقابل المالي يقطع تهمة اختراع الوحي للمصلحة، ويثبت أن القرآن ذكر متاح للعالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص510–581، يوسف: 104.","url":""}]},{"id":"s13-1","number":1,"surah":13,"verses":[1],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿تِلْكَ آيَاتُ الْكِتَابِ﴾ باسم الإشارة للبعيد؟","answer":"للتعظيم ورفع المنزلة؛ فالآيات الحاضرة في التلاوة بعيدة الرتبة لا بعيدة المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص569-594.","url":""}]},{"id":"s13-2","number":2,"surah":13,"verses":[1],"verseLabel":"الرعد: 1","question":"لماذا جُمعت ﴿آيَاتُ﴾ في افتتاح السورة؟","answer":"لأن كل مقطع من الوحي علامة مستقلة، ومجموعها كتاب متآزر الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص585–598، الرعد: 1. (صُححت الإحالة السابقة إلى ص569؛ فهي من خاتمة تفسير سورة يوسف.)","url":""}]},{"id":"s13-3","number":3,"surah":13,"verses":[1],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿وَالَّذِي أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ﴾؟","answer":"فصل بين الإشارة إلى آيات الكتاب والحكم على المنزل كله بالحق، ليؤكد مصدره وحقيقته معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594.","url":""}]},{"id":"s13-4","number":4,"surah":13,"verses":[1],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ رَبِّكَ﴾ لا من الله؟","answer":"إضافة الرب إلى النبي تشعر بالرعاية والتثبيت: الذي تولى تربيته هو الذي أنزل إليه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594.","url":""}]},{"id":"s13-5","number":5,"surah":13,"verses":[1],"verseLabel":"الرعد: 1","question":"لماذا عرّف ﴿الْحَقُّ﴾؟","answer":"للقصر والكمال؛ المنزل هو الحق المعروف الكامل الذي لا يمازجه باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص594.","url":""}]},{"id":"s13-6","number":6,"surah":13,"verses":[1],"verseLabel":"الرعد: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يُؤْمِنُونَ﴾ بالمضارع وحذف متعلقه؟","answer":"المضارع يصور تجدد امتناعهم، وحذف المتعلق يعم كفرهم بالكتاب والرسول والبعث وسائر الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص585–598، الرعد: 1. (ص599 بداية تفسير الآية الثانية.)","url":""}]},{"id":"s13-7","number":7,"surah":13,"verses":[2],"verseLabel":"الرعد: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿رَفَعَ السَّمَاوَاتِ﴾، دون أن يقال: خلق السماوات؟","answer":"لأن المقام مقام إظهار الهيئة المشاهدة: رفعٌ بلا عمد مرئية، وفيه نقل النظر من أصل الخلق إلى إحكام نظامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص605.","url":""}]},{"id":"s13-8","number":8,"surah":13,"verses":[2],"verseLabel":"الرعد: 2","question":"لماذا جُمعت ﴿السماوات﴾ وأُفردت الأرض في السورة؟","answer":"لتعدد جهات العلو وطبقاته في الإدراك، مع ظهور الأرض للإنسان كقرار واحد يجتمع عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص605.","url":""}]},{"id":"s13-9","number":9,"surah":13,"verses":[2],"verseLabel":"الرعد: 2","question":"لماذا ذُكر ﴿الأجل﴾ ولم يقل: الوقت؟","answer":"الأجل هو الوقت المضروب لانتهاء الشيء، فهو أدق في تقرير أن الجريان محدود لا فوضى فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص611.","url":""}]},{"id":"s13-10","number":10,"surah":13,"verses":[2],"verseLabel":"الرعد: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿لِقَاءِ رَبِّكُمْ تُوقِنُونَ﴾ لا تؤمنون؟","answer":"لأن المطلوب هنا علم ثابت يطرد الشك في البعث، فالإيقان أخص من مطلق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص615.","url":""}]},{"id":"s13-11","number":11,"surah":13,"verses":[3],"verseLabel":"الرعد: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مَدَّ الْأَرْضَ﴾؟","answer":"صوّر تهيئتها للإنسان مبسوطة ممتدة بحسب رؤيته وانتفاعه، لا مجرد خلق مادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص625.","url":""}]},{"id":"s13-12","number":12,"surah":13,"verses":[3],"verseLabel":"الرعد: 3","question":"لماذا جُمعت ﴿الأنهار﴾ مع إفراد الأرض؟","answer":"للدلالة على كثرتها وتنوع مجاريها في الأرض الواحدة، وهو من وجوه القدرة والإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص625.","url":""}]},{"id":"s13-13","number":13,"surah":13,"verses":[3],"verseLabel":"الرعد: 3","question":"لماذا خُتمت الآية بـ﴿لِقَوْمٍ يَتَفَكَّرُونَ﴾؟","answer":"لأن دلائل المدّ والرواسي والزوجين وتعاقب الليل تحتاج أولًا إلى إعمال الفكر في ترابطها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص616–633، الرعد: 3. (ص634 بداية تفسير الآية الرابعة.)","url":""}]},{"id":"s13-14","number":14,"surah":13,"verses":[3,4],"verseLabel":"الرعد: 3-4","question":"ما سرّ التعبير في قوله تعالى في الآية 3: ﴿يتفكرون﴾، وفي الآية 4: ﴿يعقلون﴾؟","answer":"لأن التفكر في الظواهر المذكورة أول الطريق، ثم يفضي إلى عقل دلالتها ووحدة مدبرها.","sources":[{"label":"الكرماني، أسرار التكرار، ص151؛ الموسوعة ج23، ص634.","url":""}]},{"id":"s13-15","number":15,"surah":13,"verses":[4],"verseLabel":"الرعد: 4","question":"لماذا أُفردت ﴿آية﴾ في الآية 3 وجُمعت ﴿آيات﴾ في الآية 4؟","answer":"الآية 3 تجمع مشهدًا كونيًا مترابطًا، أما اختلاف القطع والجنات والنخيل والطعم ففيه دلائل متعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص616–645، الرعد: 3–4؛ والاستدراك العكسي ج26، ص161.","url":""}]},{"id":"s13-16","number":16,"surah":13,"verses":[4],"verseLabel":"الرعد: 4","question":"ما سر قوله: ﴿صِنْوَانٌ وَغَيْرُ صِنْوَانٍ﴾؟","answer":"ليبلغ التباين غايته: أصول متحدة وأخرى مختلفة، ثم تتفاوت الثمار مع ماء واحد؛ فتظهر قدرة المدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص642.","url":""}]},{"id":"s13-17","number":17,"surah":13,"verses":[4],"verseLabel":"الرعد: 4","question":"لماذا أُسند ﴿نُفَضِّلُ﴾ إلى ضمير العظمة؟","answer":"لإبراز أن تفاوت الطعوم مع اتحاد الماء والتربة ليس ذاتيًا محضًا، بل جارٍ بتقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص644.","url":""}]},{"id":"s13-18","number":18,"surah":13,"verses":[5],"verseLabel":"الرعد: 5","question":"ما وجه قولهم: ﴿أَئِذَا كُنَّا تُرَابًا أَئِنَّا لَفِي خَلْقٍ جَدِيدٍ﴾؟","answer":"كرّروا الاستفهام تصويرًا لاستبعادهم الشديد: استبعدوا البعث بعد التراب ثم استبعدوا كونهم خلقًا متجددًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص654.","url":""}]},{"id":"s13-19","number":19,"surah":13,"verses":[5],"verseLabel":"الرعد: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿خَلْقٍ جَدِيدٍ﴾، دون أن يقال: أنُبعث؟","answer":"ليجعل موضع إنكارهم نفسه دليلًا عليهم؛ فالذي بدأ الخلق قادر على تجديده.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص654.","url":""}]},{"id":"s13-20","number":20,"surah":13,"verses":[5],"verseLabel":"الرعد: 5","question":"لماذا عبّر بالكفر لا بالشرك؟","answer":"لأن السياق في ستر دلائل القدرة والبعث وجحودها، والكفر أدل على هذا الستر والجحود.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص655.","url":""}]},{"id":"s13-21","number":21,"surah":13,"verses":[6],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وَيَسْتَعْجِلُونَكَ﴾ بخطاب النبي؟","answer":"لتصوير جرأتهم في مواجهة الرسول نفسه بطلب العذاب، وفيه تسلية له ببيان عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص665.","url":""}]},{"id":"s13-22","number":22,"surah":13,"verses":[6],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿ذُو مَغْفِرَةٍ﴾، دون أن يقال: ذو رحمة؟","answer":"لأن السياق في الذنوب واستعجال السيئة، فالمغفرة هي الصفة الأنسب لمحو موجب العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص673.","url":""}]},{"id":"s13-23","number":23,"surah":13,"verses":[6],"verseLabel":"الرعد: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿عَلَى ظُلْمِهِمْ﴾ لا مع ظلمهم؟","answer":"«على» تشعر بتمكنهم من الظلم وثقله، ومع ذلك تتعلق بهم المغفرة والإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص675.","url":""}]},{"id":"s13-24","number":24,"surah":13,"verses":[6],"verseLabel":"الرعد: 6","question":"لماذا ختم بـ﴿شَدِيدُ الْعِقَابِ﴾ لا شديد العذاب؟","answer":"العقاب جزاءٌ على جرم سابق، وهو الأنسب بعد ذكر ظلمهم ومغفرته لهم مع التحذير من التمادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص679.","url":""}]},{"id":"s13-25","number":25,"surah":13,"verses":[7],"verseLabel":"الرعد: 7","question":"ما سرّ اختيارهم لفظ ﴿أُنْزِلَ﴾ دون «جاءت»؟","answer":"لأنهم يتعنتون بطلب آية منزلة من عند الله على وفق اقتراحهم، لا مطلق ظهور دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص685.","url":""}]},{"id":"s13-26","number":26,"surah":13,"verses":[7],"verseLabel":"الرعد: 7","question":"ما سرّ تقديم ﴿عَلَيْهِ﴾ في قولهم؟","answer":"لجعل شخص الرسول موضع اعتراضهم، وكأن نقص الآية -بزعمهم- متعلق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص686.","url":""}]},{"id":"s13-27","number":27,"surah":13,"verses":[7],"verseLabel":"الرعد: 7","question":"لماذا قُصر دور النبي على الإنذار: ﴿إِنَّمَا أَنْتَ مُنْذِرٌ﴾؟","answer":"لرد اقتراحهم؛ فالرسول مبلّغ منذر، وليس إليه إنشاء الآيات ولا إجبار القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص688.","url":""}]},{"id":"s13-28","number":28,"surah":13,"verses":[7],"verseLabel":"الرعد: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿وَلِكُلِّ قَوْمٍ هَادٍ﴾ لا لكل أمة منذر؟","answer":"«القوم» يلائم المخاطَبين مجتمعًا، و«هاد» أوسع من مجرد الإنذار إذ يشمل الدلالة إلى الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص690.","url":""}]},{"id":"s13-29","number":29,"surah":13,"verses":[8],"verseLabel":"الرعد: 8","question":"لماذا بدأ بـ﴿اللَّهُ يَعْلَمُ﴾؟","answer":"تقديم اسم الجلالة يرسخ اختصاص العلم المحيط به قبل تفصيل دقائق الأرحام.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص695.","url":""}]},{"id":"s13-30","number":30,"surah":13,"verses":[8],"verseLabel":"الرعد: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا تَحْمِلُ كُلُّ أُنْثَى﴾ بالمضارع؟","answer":"ليدل على تجدد تعلق علمه بكل حمل في كل وقت، لا بحالات مضت فقط.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص696-697.","url":""}]},{"id":"s13-31","number":31,"surah":13,"verses":[8],"verseLabel":"الرعد: 8","question":"ما سرّ تقديم الغيض على الازدياد؟","answer":"لأن النقص أسبق تصورًا وزمنًا في أطوار الحمل، ثم تأتي الزيادة بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص700-702.","url":""}]},{"id":"s13-32","number":32,"surah":13,"verses":[8],"verseLabel":"الرعد: 8","question":"ما سرّ التعبير في قوله تعالى: ﴿كُلُّ شَيْءٍ عِنْدَهُ بِمِقْدَارٍ﴾ وقدّم ﴿عنده﴾؟","answer":"للدلالة على أن التقدير مضبوط في علمه وتدبيره خاصة، لا يقع عبثًا أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص703.","url":""}]},{"id":"s13-33","number":33,"surah":13,"verses":[9],"verseLabel":"الرعد: 9","question":"لماذا حُذفت ياء ﴿الْمُتَعَالِ﴾ في الرسم والوقف المشهور؟","answer":"جاء الحذف على الفاصلة والرسم مع بقاء المعنى، وفي اللفظ خفة تناسب جلال الإيقاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص707.","url":""}]},{"id":"s13-34","number":34,"surah":13,"verses":[10],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿أَسَرَّ الْقَوْلَ﴾ لا أخفاه؟","answer":"الإسرار قول مقصود خفيض، فيناسب مقابلة الجهر وإحاطة العلم بدرجات النطق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص712-713.","url":""}]},{"id":"s13-35","number":35,"surah":13,"verses":[10],"verseLabel":"الرعد: 10","question":"لماذا اقتصر على ﴿القول﴾ دون الفعل؟","answer":"إذا استوى عند الله أدق ما يخفى من القول وما يجهر به، فإحاطته بالأفعال أولى، وفيه إيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص714-715.","url":""}]},{"id":"s13-36","number":36,"surah":13,"verses":[10],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير بقوله تعالى: ﴿جَهَرَ بِهِ﴾؟","answer":"الجهر إظهار الصوت بعد خفائه، وهو المقابل الدقيق للإسرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص716.","url":""}]},{"id":"s13-37","number":37,"surah":13,"verses":[10],"verseLabel":"الرعد: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿مُسْتَخْفٍ﴾ و﴿سَارِبٌ﴾؟","answer":"جمع بين طالب الخفاء في الليل والظاهر المنطلق في النهار؛ فالعلم محيط بأقصى حالتي الاستتار والظهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص717.","url":""}]},{"id":"s13-38","number":38,"surah":13,"verses":[10],"verseLabel":"الرعد: 10","question":"لماذا ذُكرت ﴿مَن﴾ مع ﴿أسر القول﴾ وحُذفت قبل ﴿سارب﴾؟","answer":"ذُكرت أولًا لتأسيس المقابلة وتعيين الإنسان، ثم حُذف نظيرها إيجازًا بعد وضوحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص721-722.","url":""}]},{"id":"s13-39","number":39,"surah":13,"verses":[11],"verseLabel":"الرعد: 11","question":"لماذا أُفرد الضمير في ﴿لَهُ مُعَقِّبَاتٌ﴾ ثم جُمع الناس في ﴿بِقَوْمٍ﴾؟","answer":"الأول ينظر إلى كل إنسان على حدة وما يحيط به، والثاني يقرر سنة اجتماعية عامة في الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص728-729.","url":""}]},{"id":"s13-40","number":40,"surah":13,"verses":[11],"verseLabel":"الرعد: 11","question":"هل في قوله تعالى: ﴿لَهُ مُعَقِّبَاتٌ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ يَحْفَظُونَهُ مِنْ أَمْرِ اللَّهِ﴾ تقديم وتأخير؟","answer":"ذهب بعض المفسرين إلى تقدير تقديم وتأخير، وجعلوا المعنى: له معقبات من أمر الله يحفظونه. لكن المصدر رجّح إبقاء النظم على ترتيبه؛ لأن حمل القرآن على التقديم والتأخير خلاف الأصل مع إمكان فهمه من غير عكس للترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص730.","url":""}]},{"id":"s13-41","number":41,"surah":13,"verses":[11],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ أَمْرِ اللَّهِ﴾؟","answer":"يفيد أن حفظهم واقع بأمره وتقديره، لا استقلالًا عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص733.","url":""}]},{"id":"s13-42","number":42,"surah":13,"verses":[11],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّ اللَّهَ لَا يُغَيِّرُ مَا بِقَوْمٍ﴾ بالمضارع المنفي؟","answer":"ليقرر سنة مطردة متجددة، لا واقعة تاريخية منقطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص734-735.","url":""}]},{"id":"s13-43","number":43,"surah":13,"verses":[11],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا بِقَوْمٍ﴾، دون أن يقال: حال قوم؟","answer":"«ما» تعم أحوالهم الظاهرة والباطنة، و«قوم» يدل على أن التغيير سنة جماعية لها أسباب بشرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص735-737.","url":""}]},{"id":"s13-44","number":44,"surah":13,"verses":[11],"verseLabel":"الرعد: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿مِنْ دُونِهِ مِنْ وَالٍ﴾؟","answer":"«دون» تصوّر كل ما سواه في رتبة العجز، و«وال» هو من يتولى النصرة والتدبير، وكلاهما منتفٍ عند إرادته السوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص741-742؛ استدراك ج52، ص779.","url":""}]},{"id":"s13-45","number":45,"surah":13,"verses":[12],"verseLabel":"الرعد: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿يُرِيكُمُ الْبَرْقَ خَوْفًا وَطَمَعًا﴾ فجمع الضدين؟","answer":"لأن المشهد الواحد يوقظ خوف الصاعقة أو فوات المطر، وطمع الغيث والنفع؛ فتجتمع الهيبة والرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص749-750.","url":""}]},{"id":"s13-46","number":46,"surah":13,"verses":[12],"verseLabel":"الرعد: 12","question":"ما سرّ التعبير في قوله تعالى: ﴿يُنْشِئُ السَّحَابَ﴾ لا يخلق؟","answer":"الإنشاء يصور تكوينه المتجدد شيئًا بعد شيء من بدايات دقيقة حتى يثقل بالماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص751.","url":""}]},{"id":"s13-47","number":47,"surah":13,"verses":[12],"verseLabel":"الرعد: 12","question":"لماذا وُصف السحاب بـ﴿الثِّقَالِ﴾؟","answer":"ليحس القارئ بما حمله من ماء كثير، فتقوى صورة القدرة والبشارة بالمطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص752.","url":""}]},{"id":"s13-48","number":48,"surah":13,"verses":[13],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ﴾؟","answer":"جمع بين التنزيه والحمد: فالصوت المهيب لا يدل على القوة فقط، بل على كمال صاحبها واستحقاقه الحمد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص755.","url":""}]},{"id":"s13-49","number":49,"surah":13,"verses":[13],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مَنْ يَشَاءُ﴾ في إرسال الصواعق؟","answer":"لإظهار نفاذ الإرادة في إصابة من يشاء، وإبطال وهم المصادفة أمام هذا التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص758.","url":""}]},{"id":"s13-50","number":50,"surah":13,"verses":[13],"verseLabel":"الرعد: 13","question":"ما سرّ تقديم ﴿فِي اللَّهِ﴾ في ﴿وَهُمْ يُجَادِلُونَ فِي اللَّهِ﴾؟","answer":"لتفظيع موضع جدالهم: ليس في أمر هين، بل في الله الذي عرضت الآيات قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص759.","url":""}]},{"id":"s13-51","number":51,"surah":13,"verses":[13],"verseLabel":"الرعد: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿شَدِيدُ الْمِحَالِ﴾؟","answer":"اختير اللفظ الجامع للقوة والتدبير والأخذ، ليلائم من يجادل مع ظهور الصواعق والآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص763-764.","url":""}]},{"id":"s13-52","number":52,"surah":13,"verses":[14],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿لَهُ دَعْوَةُ الْحَقِّ﴾؟","answer":"القصر يفيد أن الدعاء الحق الذي يسمع ويجيب إنما يتوجه إليه، وما عداه باطل لا يملك جوابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص774.","url":""}]},{"id":"s13-53","number":53,"surah":13,"verses":[14],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿يَسْتَجِيبُونَ﴾ لا يجيبون؟","answer":"صيغة الاستفعال تصور طلب الإجابة وترقبها، ثم تنفي تحققها عن المعبودات الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص776.","url":""}]},{"id":"s13-54","number":54,"surah":13,"verses":[14],"verseLabel":"الرعد: 14","question":"لماذا شُبّه الداعي بـ﴿بَاسِطِ كَفَّيْهِ إِلَى الْمَاءِ﴾؟","answer":"لأن هيئة الكفين المبسوطتين تبرز شدة التعلق بالمطلوب مع استحالة بلوغه بمجرد البسط.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص778-780.","url":""}]},{"id":"s13-55","number":55,"surah":13,"verses":[14],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿كفَّيه﴾ لا يديه؟","answer":"لأن الكفين موضع غرف الماء وتلقيه، فهما أدق في الصورة من عموم اليدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص780.","url":""}]},{"id":"s13-56","number":56,"surah":13,"verses":[14],"verseLabel":"الرعد: 14","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ﴾؟","answer":"جعل الدعاء نفسه غارقًا في الضلال، مبالغة في تصوير ضياعه وعدم بلوغه غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص784-785.","url":""}]},{"id":"s13-57","number":57,"surah":13,"verses":[15],"verseLabel":"الرعد: 15","question":"كيف يسجد لله من في الكون ﴿طَوْعًا وَكَرْهًا﴾؟","answer":"المؤمن يسجد اختيارًا، والجميع خاضعون قهرًا لسننه وقدره؛ فلا يخرج مخلوق عن سلطان ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص797؛ ج24، ص11.","url":""}]},{"id":"s13-58","number":58,"surah":13,"verses":[15],"verseLabel":"الرعد: 15","question":"لماذا ذُكرت الظلال بعد سجود الأحياء؟","answer":"لتجسيد الخضوع حتى في الظل الملازم للشيء، فيتحول المشهد الكوني كله إلى سجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص797؛ ج24، ص11.","url":""}]},{"id":"s13-59","number":59,"surah":13,"verses":[16],"verseLabel":"الرعد: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿أَوْلِيَاءَ﴾ لا أربابًا؟","answer":"«الأولياء» أعم؛ فهي تنفي عنهم كل ولاية ونصرة ونفع، لا مجرد دعوى الربوبية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص20.","url":""}]},{"id":"s13-60","number":60,"surah":13,"verses":[16],"verseLabel":"الرعد: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿لَا يَمْلِكُونَ لِأَنْفُسِهِمْ نَفْعًا وَلَا ضَرًّا﴾؟","answer":"بدأ بعجزهم عن أنفسهم؛ فمن عجز عن نفع نفسه ودفع ضرها كان أعجز عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص21-22.","url":""}]},{"id":"s13-61","number":61,"surah":13,"verses":[16],"verseLabel":"الرعد: 16","question":"لماذا كرر ﴿لا﴾ في ﴿لَا يَمْلِكُونَ... نَفْعًا وَلَا ضَرًّا﴾؟","answer":"للنص على استقلال النفي بكل واحد من النفع والضر، فلا يتوهم ثبوت أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص22.","url":""}]},{"id":"s13-62","number":62,"surah":13,"verses":[16],"verseLabel":"الرعد: 16","question":"لماذا شُبّه الكفر بالظلمات وجُمع، والإيمان بالنور وأُفرد؟","answer":"طرق الباطل كثيرة متفرقة، أما الحق فطريق واحد واضح يجمع ولا يشتت.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص24.","url":""}]},{"id":"s13-63","number":63,"surah":13,"verses":[16],"verseLabel":"الرعد: 16","question":"لماذا خُتمت الآية بـ﴿الْوَاحِدُ الْقَهَّارُ﴾؟","answer":"«الواحد» يهدم تعدد الشركاء، و«القهار» يهدم توهم استقلالهم بالقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص31.","url":""}]},{"id":"s13-64","number":64,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْزَلَ مِنَ السَّمَاءِ مَاءً﴾ لا غيثًا؟","answer":"الماء أعم في مقام ضرب المثل، والغيث يغلب في سياق الإغاثة بعد الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص38-39.","url":""}]},{"id":"s13-65","number":65,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"لماذا أُسند السيل إلى الأودية: ﴿فَسَالَتْ أَوْدِيَةٌ﴾ لا إلى الماء؟","answer":"لتصوير تفاوت القلوب في حمل الوحي كتفاوت الأودية في حمل الماء؛ فالمحل هو المقصود بالمثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص42.","url":""}]},{"id":"s13-66","number":66,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿بِقَدَرِهَا﴾؟","answer":"كل واد يحمل بقدر سعته، وكذلك القلوب من نور الحق بحسب استعدادها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص40-42.","url":""}]},{"id":"s13-67","number":67,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿فَاحْتَمَلَ السَّيْلُ زَبَدًا رَابِيًا﴾؟","answer":"جعل الزبد محمولًا طافيًا ليجسد ظهور الباطل مؤقتًا مع خفته وانفصاله عن جوهر النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص41-46.","url":""}]},{"id":"s13-68","number":68,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"لماذا لم يذكر استخراج المعادن من الأرض قبل إيقادها؟","answer":"انتقل النظم مباشرة إلى ما يوقد عليه؛ لأن المقصود تشبيه زبد المعادن بزبد السيل، وضُرب هذا المثل بما يعرفه أهل الحضر من صهر الذهب والفضة، كما ضُرب مثل السيل بما يلائم أهل البدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص48.","url":""}]},{"id":"s13-69","number":69,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"لماذا أُفرد ﴿الزَّبَد﴾ مع أنه في مثلين؟","answer":"لأن زبد الماء وزبد المعدن متحدان في الصفة المقصودة: الطفو والذهاب بلا نفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص55.","url":""}]},{"id":"s13-70","number":70,"surah":13,"verses":[17],"verseLabel":"الرعد: 17","question":"لماذا كرر: ﴿كَذَلِكَ يَضْرِبُ اللَّهُ الْأَمْثَالَ﴾ بعد ﴿كَذَلِكَ يَضْرِبُ اللَّهُ الْحَقَّ وَالْبَاطِلَ﴾؟","answer":"طال التفصيل بين طرفي الكلام، فأعيدت الجملة لتجمع المثل وتقرر قاعدته بعد بيان مصير الزبد والنافع.","sources":[{"label":"الكرماني، أسرار التكرار، ص152؛ الموسوعة ج24، ص60.","url":""}]},{"id":"s13-71","number":71,"surah":13,"verses":[18],"verseLabel":"الرعد: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿لِلَّذِينَ اسْتَجَابُوا لِرَبِّهِمُ الْحُسْنَى﴾؟","answer":"«الحسنى» لفظ موجز يجمع أحسن الجزاء كله من الجنة والرضوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص69.","url":""}]},{"id":"s13-72","number":72,"surah":13,"verses":[18],"verseLabel":"الرعد: 18","question":"ما سرّ التعبير في قوله تعالى: ﴿سُوءُ الْحِسَابِ﴾ لا سوء العقاب؟","answer":"الحساب يستحضر استقصاء الأعمال ودقتها قبل الجزاء، وهو أشد إيقاظًا للمسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص75.","url":""}]},{"id":"s13-73","number":73,"surah":13,"verses":[19],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿أَفَمَنْ يَعْلَمُ﴾ لا أفمن يرى؟","answer":"العلم بالوحي بصيرة ثابتة تتجاوز الرؤية الحسية، ولذلك قابله بالعمى المعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص86-91.","url":""}]},{"id":"s13-74","number":74,"surah":13,"verses":[19],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿أَعْمَى﴾ لا «لا يبصر»؟","answer":"العمى وصف متمكن يصور فساد البصيرة، بخلاف عدم الإبصار الذي قد يكون عارضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص91.","url":""}]},{"id":"s13-75","number":75,"surah":13,"verses":[19],"verseLabel":"الرعد: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿إِنَّمَا يَتَذَكَّرُ أُولُو الْأَلْبَابِ﴾؟","answer":"القصر يبين أن الانتفاع ليس بمجرد امتلاك المعلومات، بل بلبّ عقل صافٍ يرد صاحبه إلى الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص92-94.","url":""}]},{"id":"s13-76","number":76,"surah":13,"verses":[20],"verseLabel":"الرعد: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿يُوفُونَ بِعَهْدِ اللَّهِ﴾ بالمضارع؟","answer":"للدلالة على أن الوفاء خُلُق متجدد ملازم، لا موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص99.","url":""}]},{"id":"s13-77","number":77,"surah":13,"verses":[20],"verseLabel":"الرعد: 20","question":"لماذا جمع بين الوفاء بالعهد وعدم نقض الميثاق؟","answer":"الأول إثبات للأداء، والثاني نفي للإفساد بعد التوثيق؛ فاجتمع كمال الفعل والسلامة من ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص101-106.","url":""}]},{"id":"s13-78","number":78,"surah":13,"verses":[20],"verseLabel":"الرعد: 20","question":"ما سرّ التعبير بقوله تعالى: ﴿الميثاق﴾ بعد ﴿العهد﴾؟","answer":"الميثاق هو العهد المؤكد المشدود، فجيء به عند تصوير قبح النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص104-106.","url":""}]},{"id":"s13-79","number":79,"surah":13,"verses":[21],"verseLabel":"الرعد: 21","question":"لماذا كرر ﴿الذين﴾ في صفات أولي الألباب؟","answer":"لتجديد التنبيه إلى استقلال كل طائفة من الصفات بالعناية والمدح.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص112.","url":""}]},{"id":"s13-80","number":80,"surah":13,"verses":[21],"verseLabel":"الرعد: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿مَا أَمَرَ اللَّهُ بِهِ أَنْ يُوصَلَ﴾ ولم يحدد؟","answer":"عمّم ليشمل الأرحام والإيمان والعهود وكل صلة أمر الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص113-114.","url":""}]},{"id":"s13-81","number":81,"surah":13,"verses":[21],"verseLabel":"الرعد: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿يَخْشَوْنَ رَبَّهُمْ وَيَخَافُونَ سُوءَ الْحِسَابِ﴾؟","answer":"الخشية علمٌ بهيبة الرب، والخوف توقع أثر الحساب؛ فقدم السبب القلبي على نتيجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص115-117.","url":""}]},{"id":"s13-82","number":82,"surah":13,"verses":[22],"verseLabel":"الرعد: 22","question":"لماذا حُذف متعلق الصبر في ﴿صَبَرُوا﴾؟","answer":"ليعم الصبر على الطاعة وعن المعصية وعلى البلاء، فلا يحصر في لون واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص122.","url":""}]},{"id":"s13-83","number":83,"surah":13,"verses":[22],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿ابْتِغَاءَ وَجْهِ رَبِّهِمْ﴾؟","answer":"«الابتغاء» يدل على القصد والطلب، وذكر الوجه كناية عن إخلاص الجهة لله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص123-124.","url":""}]},{"id":"s13-84","number":84,"surah":13,"verses":[22],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿أَقَامُوا الصَّلَاةَ﴾ لا أدّوها؟","answer":"الإقامة تتضمن إتمام أركانها وحدودها والمحافظة عليها، لا مجرد وقوع الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص125.","url":""}]},{"id":"s13-85","number":85,"surah":13,"verses":[22],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿أَنْفَقُوا مِمَّا رَزَقْنَاهُمْ﴾ ولم يخص الزكاة؟","answer":"ليشمل الواجب والتطوع، و«مِن» تذكر أن المطلوب بعض الرزق لا كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص126-128.","url":""}]},{"id":"s13-86","number":86,"surah":13,"verses":[22],"verseLabel":"الرعد: 22","question":"ما سرّ تقديم ﴿سِرًّا﴾ على ﴿عَلَانِيَةً﴾؟","answer":"السر أبعد عن الرياء، فقدم بوصفه الأصل في سلامة القصد، ثم ذكرت العلانية لمصلحة القدوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص129-130.","url":""}]},{"id":"s13-87","number":87,"surah":13,"verses":[22],"verseLabel":"الرعد: 22","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ﴾ لا يدفعون؟","answer":"الدرء دفعٌ مع إزالة الأثر، فيشمل التوبة والإحسان ومقابلة الإساءة بما يمحوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص131-133.","url":""}]},{"id":"s13-88","number":88,"surah":13,"verses":[23],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿جَنَّاتُ عَدْنٍ﴾ بالجمع؟","answer":"يشعر بتعدد البساتين والدرجات وتنوع النعيم، لا موضع واحد محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص141.","url":""}]},{"id":"s13-89","number":89,"surah":13,"verses":[23],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿يَدْخُلُونَهَا﴾ لا يسكنونها؟","answer":"الدخول هو أول لحظات الفرح واللقاء بعد الانتظار، فاستحضره لتجديد المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص142.","url":""}]},{"id":"s13-90","number":90,"surah":13,"verses":[23],"verseLabel":"الرعد: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وَمَنْ صَلَحَ﴾ لا «والذين صلحوا»؟","answer":"«من» تعم كل صالح من الأصناف المذكورة، وتفتح باب اللحاق بلا تقييد بعدد أو جنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص143.","url":""}]},{"id":"s13-91","number":91,"surah":13,"verses":[23],"verseLabel":"الرعد: 23","question":"لماذا ذكر الآباء والأزواج والذريات بدل كلمة «الأهل»؟","answer":"لإبراز دوائر الأنس واحدة واحدة، واستحضار تمام اجتماع الأسرة في الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص145.","url":""}]},{"id":"s13-92","number":92,"surah":13,"verses":[23],"verseLabel":"الرعد: 23","question":"لماذا أُفرد ﴿بَابٍ﴾ في ﴿مِنْ كُلِّ بَابٍ﴾؟","answer":"لأن «كل» تستغرق أفراد الأبواب بابًا بابًا، فتُرى كثرة الوفود من كل جهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص148.","url":""}]},{"id":"s13-93","number":93,"surah":13,"verses":[24],"verseLabel":"الرعد: 24","question":"ما سرّ التعبير بقوله تعالى: ﴿سَلَامٌ عَلَيْكُمْ﴾ بالتنكير؟","answer":"للتعظيم والتكثير: سلام عظيم متجدد يحيط بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج24، ص151-152.","url":""}]}]);
